insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$1001$t$, $t$Alexandria Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance Certificate (CRC)$t$, $j$["Issued by: Alexandria Township Building Department (Construction Code Enforcement)","Contact: Marianna Voorhees, Technical Assistant to the Construction Official · 908-996-7071 ext. 211 · construction@alexandrianj.gov","Apply: The Township page says to submit the CRC application at least 30 business days before closing; the ordinance requires the application and fee at least 10 business days before the change of ownership","How to apply: Get the CRC application from the Building Department (242 Little York-Mt. Pleasant Road, Milford) or download it from the Township site, and submit it with the $50.00 fee payable to Alexandria Township. The seller or the seller's agent files it.","Records inspection by the construction office: all permits on the block and lot must be inspected and closed by the subcode officials","If there are open permits, all final inspections and prior approvals must be obtained before the CRC is issued","Smoke detector certification is required before closing and a copy must be forwarded to the Building Department","Application lists seller, real estate agent, seller's attorney, block and lot and approximate year built"]$j$::jsonb, $j$[{"label":"Construction Records Clearance application","amount":"$50.00"}]$j$::jsonb, $t$https://alexandrianj.gov/government/forms/construction/26-construction-records-clearance-application/file$t$, $t$https://alexandrianj.gov/departments/construction$t$, $j$[{"url":"https://alexandrianj.gov/construction-page-list/284-construction-records-clearance-are-you-selling-your-home","label":"Official source (alexandrianj.gov)"},{"url":"https://ecode360.com/15260359","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/15260371","label":"Official source (ecode360.com)"},{"url":"https://alexandrianj.gov/government/forms/construction/26-construction-records-clearance-application/file","label":"Official source (alexandrianj.gov)"}]$j$::jsonb, $t$This certificate is required on the sale of all residential and commercial properties.$t$, $t$7182ccff2e7fd6205c757ebf19846496586aee8cff2854431939905c36d0f5ee$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1001.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1001.json$t$, true),
  ($t$1001$t$, $t$Alexandria Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Alexandria Township Bureau of Fire Prevention (Fire Marshal) (town fire bureau)","Contact: Mike Giannone, Fire Marshal · 908-612-3592","Apply: Call the Fire Marshal to schedule; no lead time published","How to apply: Call Fire Marshal Mike Giannone at 908-612-3592 to arrange the smoke detector inspection, then forward a copy of the certificate to the Building Department before closing.","Fire official in the NJ state directory (town), updated 3/6/2023: Michael G Giannone · (908) 996-7071 · mggiannone@att.net","Smoke alarm on each level of the home and outside each separate sleeping area","Battery-only smoke alarms must be 10-year sealed battery units; hardwired alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (where there is a fuel-burning appliance or attached garage)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://alexandrianj.gov/departments/construction$t$, $j$[{"url":"https://alexandrianj.gov/departments/construction","label":"Official source (alexandrianj.gov)"},{"url":"https://alexandrianj.gov/construction-page-list/284-construction-records-clearance-are-you-selling-your-home","label":"Official source (alexandrianj.gov)"},{"url":"https://ecode360.com/50207659","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/50207675","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Marshall Mike Giannone (908) 612-3592 Call to arrange smoke detector inspections$t$, $t$0fb44d26a1e06c06240406a2e9015e430bc36ca81eab0690c3f7592ba60eee58$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1001.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1001.json$t$, true),
  ($t$1005$t$, $t$Clinton Town$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC)$t$, $j$["Issued by: Town of Clinton Construction Office (Construction & Zoning)","Contact: Catherine Innella, Technical Assistant to the Construction Official · 908-735-2275 · cinnella@clintonnj.gov","Apply: Submit far enough ahead of closing to allow review and any inspections; the fee rises if the application comes in within 10 business days of closing","How to apply: Download the Construction Records Clearance Application from the Town's Municipal Forms page, fill it out and submit it with the fee to the Construction Office, 43/47 Leigh Street. Questions go to the Technical Assistant to the Construction Official at 908-735-2275.","Records review for open construction permits (office checks open permits before issuing the Certificate of Records Clearance)","Application asks whether there is a swimming pool and a pool barrier","Application asks whether a water heater, HVAC, woodstove or fireplace insert was installed or replaced","Application asks whether a deck, hot tub, shed or outbuilding, or finished basement was built","Application asks whether the smoke, carbon monoxide and fire extinguisher application has been filed"]$j$::jsonb, $j$[{"label":"Construction Records Clearance application","amount":"$100.00"},{"label":"Construction Records Clearance application, submitted within 10 business days of closing","amount":"$150.00"}]$j$::jsonb, $t$https://www.clintonnj.gov/DocumentCenter/View/558/Construction-Records-Clearance-Application$t$, $t$https://www.clintonnj.gov/287/Construction-Zoning$t$, $j$[{"url":"https://www.clintonnj.gov/217/Selling-your-Residential-Property","label":"Official source (clintonnj.gov)"},{"url":"https://www.clintonnj.gov/DocumentCenter/View/558/Construction-Records-Clearance-Application","label":"Official source (clintonnj.gov)"},{"url":"https://ecode360.com/14296566","label":"Official source (ecode360.com)"},{"url":"https://www.clintonnj.gov/287/Construction-Zoning","label":"Official source (clintonnj.gov)"}]$j$::jsonb, $t$Whenever any residential property is sold, the current owner must submit the following two applications and receive final approval from the Town before the sale can occur$t$, $t$dd91b9d4d131f10dee353d138ff510f31afdbc79e3bc79b5bdc6ab391c2b5634$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1005.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1005.json$t$, true),
  ($t$1005$t$, $t$Clinton Town$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Town of Clinton Fire Safety & Prevention (Department of Fire Prevention, Fire Marshal) (town fire bureau)","Contact: Jack Daniels, Fire Marshal · 908-468-1696 · jdaniels@clintonnj.gov","Apply: Submit the application 4 to 5 weeks before closing; the inspection is scheduled about 2 weeks before the closing date","How to apply: Fill out the Town's 'Smoke-CO Alarm-Fire Extinguisher Application' and send it with a check or money order payable to the Town of Clinton. The owner may either ask the Department of Fire Prevention to inspect, or self-certify the alarms on the form with a notary's authentication if the Fire Official permits it.","Fire official in the NJ state directory (town), updated 4/28/2025: John K Daniels · (908) 735-2275 · jdaniels@clintonnj.gov","Smoke alarm on each level of the home and outside each separate sleeping area","Battery-only smoke alarms must be 10-year sealed battery units; hardwired alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (where there is a fuel-burning appliance or attached garage)","Portable ABC fire extinguisher within 10 feet of the kitchen along the exit path, no more than 10 pounds, mounted no higher than 5 feet, with a service tag within 1 year or new (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, application more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Application 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Application fewer than 4 business days before change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://www.clintonnj.gov/DocumentCenter/View/563/Smoke-CO-Alarm-Fire-Extinguisher-Application$t$, $t$https://www.clintonnj.gov/Directory.aspx$t$, $j$[{"url":"https://www.clintonnj.gov/DocumentCenter/View/563/Smoke-CO-Alarm-Fire-Extinguisher-Application","label":"Official source (clintonnj.gov)"},{"url":"https://www.clintonnj.gov/Directory.aspx","label":"Official source (clintonnj.gov)"},{"url":"https://ecode360.com/12167530","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION FOR ONE & TWO FAMILY DWELLING CERTIFICATE OF SMOKE ALARM AND CARBON MONOXIDE ALARM AND FIRE EXTINGUISHER COMPLIANCE$t$, $t$56ae98c76aef86421c556dd105e0117778fb8200623f90fc071a026def3872de$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1005.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1005.json$t$, true),
  ($t$1006$t$, $t$Clinton Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Construction Records Clearance (CRC), described on the Township site as a Municipal Code Compliance Inspection$t$, $j$["Issued by: Clinton Township Construction Code Enforcement (Building Department)","Contact: Terri Howell, Technical Assistant (Construction Official: Tom Petto, ext. 256, tpetto@clintontwpnj.org) · 908-735-8800 ext. 258 · thowell@clintontwpnj.org","Apply: The Township processes requests made more than 10 business days ahead within 10 business days; later requests cost more and timing is not guaranteed","How to apply: Complete the Construction Records Clearance Application and bring it with the fee to the Building Department, 1225 Route 31 South, Building D, 1st Floor, Lebanon. Choose call-to-pick-up or email delivery on the form.","Valid for: Six months from the date of issuance, provided no change in occupancy has occurred","Records inspection for open construction permits and pending, open, unabated violations","All building permits must be closed out (final inspections and prior approvals obtained) and violations cured before the certificate is issued","Bring the completed application and fee to the Building Department to schedule"]$j$::jsonb, $j$[{"label":"Construction Records Clearance, more than 10 business days before closing","amount":"$75.00"},{"label":"Construction Records Clearance, 10 business days or less before closing","amount":"$100.00"},{"label":"Updated certificate (update of a prior records inspection within six months)","amount":"$35.00"}]$j$::jsonb, $t$https://www.clintontwpnj.gov/_Content/pdf/forms/construction-code/construction-records-clearance-application.pdf$t$, $t$https://www.clintontwpnj.gov/department/construction-code-enforcement$t$, $j$[{"url":"https://www.clintontwpnj.gov/department/construction-code-enforcement","label":"Official source (clintontwpnj.gov)"},{"url":"https://ecode360.com/14397153","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/14397157","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/14397158","label":"Official source (ecode360.com)"},{"url":"https://www.clintontwpnj.gov/_Content/pdf/forms/construction-code/construction-records-clearance-application.pdf","label":"Official source (clintontwpnj.gov)"}]$j$::jsonb, $t$Whenever a house, apartment, or any other structure is rented or sold, The Clinton Township Code section 158-8 A requires the current owner to obtain a Municipal Code Compliance Inspection.$t$, $t$b0377f6c4b9da709e0ecefb1f741bc599b2b5889aa2c7e5af2a888b16cff16de$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1006.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1006.json$t$, true),
  ($t$1006$t$, $t$Clinton Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Clinton Township Bureau of Fire Safety (Fire Marshal's Office) (town fire bureau)","Contact: Frank Ur, Fire Marshal · 908-735-8800 ext. 254 · firemarshal@clintontwpnj.org","Apply: Allow at least 1 to 2 weeks for mailed applications; fees step up at 10 and 4 business days before the change of occupancy","How to apply: Complete the Township application for smoke alarm, carbon monoxide alarm and secondary power source ID (updated 2025-03-26) and send it with a check payable to Township of Clinton Bureau of Fire Safety, 1225 Route 31 South, Suite 411, Lebanon, NJ 08833.","Fire official in the NJ state directory (town), updated 7/28/2025: Frank Ur · (908) 735-8800 · fireinspector2@clintontwpnj.org","Smoke alarm on each level of the home and outside each separate sleeping area","Battery-only smoke alarms must be 10-year sealed battery units; hardwired alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (where there is a fuel-burning appliance or attached garage)","Secondary power source identification label, only if the home has a secondary power source (added by P.L.2025, c.19)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, more than 10 business days before change of occupancy","amount":"$50.00"},{"label":"4 to 10 business days before change of occupancy","amount":"$90.00"},{"label":"Fewer than 4 business days before change of occupancy","amount":"$161.00"},{"label":"Re-inspection (failed inspection or no-show)","amount":"$50.00"}]$j$::jsonb, $t$https://www.clintontwpnj.gov/_Content/pdf/forms/fire/Smoke-Alarm-Carbon-Monoxide-Alarm-Fire-Extinguisher-Compliance-App.pdf$t$, $t$https://www.clintontwpnj.gov/department/fire-safety$t$, $j$[{"url":"https://www.clintontwpnj.gov/_Content/pdf/forms/fire/Smoke-Alarm-Carbon-Monoxide-Alarm-Fire-Extinguisher-Compliance-App.pdf","label":"Official source (clintontwpnj.gov)"},{"url":"https://ecode360.com/33022893","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/33022895","label":"Official source (ecode360.com)"},{"url":"https://www.clintontwpnj.gov/department/fire-safety","label":"Official source (clintontwpnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Updated 2025-03-26$t$, $t$8792d88ba4575112189a1d1535a6d98c992a3d7b685397e750c77116c47b9132$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1006.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1006.json$t$, true),
  ($t$1007$t$, $t$Delaware Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Construction Records Clearance (CRC)$t$, $j$["Issued by: Delaware Township Office of the Construction Code Official","Contact: Debbi Hutton, Technical Assistant to the Construction Code Official · (609) 397-3240 ext. 201 · construction@delawaretwpnj.org","Apply: Submit the application and fee at least 10 business days before the change of ownership; the Township processes timely requests within 10 business days","How to apply: The seller or seller's agent completes the Construction Records Clearance Application - Residential (one per address) and submits it with cash or a check payable to Delaware Township to the Construction Office, 570 Rosemont Ringoes Road, Sergeantsville (PO Box 500).","Valid for: Six months from the date of issue unless a change in occupancy has occurred","Records inspection for open construction permits and pending, open, unabated violations; all must be closed or cured before the CRC is issued","House number clearly displayed at the end of the driveway (listed on the form)","Form asks about swimming pool and pool fence (at least 4 feet high with self-closing and latching gates)","Form asks about finished basement, space above garage, hot tub, deck and alarm system, and asks the seller to list all outbuildings with approximate size","A provisional CRC may be issued when there is not enough time to close open permits, if owner and buyer acknowledge them in writing and agree on a plan"]$j$::jsonb, $j$[{"label":"CRC, request more than 10 business days before change of occupancy","amount":"$75"},{"label":"CRC, request 10 or fewer business days before change of occupancy","amount":"$100"},{"label":"Update request for same premises within 6 months of prior issuance","amount":"$50"}]$j$::jsonb, $t$https://delawaretwpnj.org/government/forms/construction/700-construction-records-clearance-application-residential/file$t$, $t$https://delawaretwpnj.org/departments/construction$t$, $j$[{"url":"https://delawaretwpnj.org/departments/construction","label":"Official source (delawaretwpnj.org)"},{"url":"https://delawaretwpnj.org/government/forms/construction/700-construction-records-clearance-application-residential/file","label":"Official source (delawaretwpnj.org)"},{"url":"https://ecode360.com/51506728","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/13582718","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/13582729","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The Construction Records Clearance is the responsibility of the seller or agent for the seller. One application per address is needed at the closing of the property.$t$, $t$2c4c081e4b67723a27f21ea0fefc9410f73f44d2099ed961d9e0fcf6ca86437c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1007.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1007.json$t$, true),
  ($t$1007$t$, $t$Delaware Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lambertville Fire District #1 Bureau of Fire Safety (shared service with Delaware Township since July 1, 2026) (fire district)","Contact: Frank Ur, Fire Official · 609-397-2084 · firemarshal17@lfddistrict1.com","Apply: Allow at least 1 to 2 weeks for mailed applications; fees step up at 10 and 4 business days before the change of occupancy","How to apply: Complete the Lambertville Fire District #1 application for smoke alarm, carbon monoxide alarm and fire extinguisher compliance and submit it with a check payable to Lambertville Fire District # 1, 230 N. Main St., Lambertville, NJ 08530. Forms and payments can also be submitted electronically on the fire district website.","Fire official in the NJ state directory (fire district), updated 2/12/2021: Frank Ur · (609) 681-7913 · firemarshal17@lfddistrict1.com","Smoke alarm on each level of the home and outside each separate sleeping area","Battery-only smoke alarms must be 10-year sealed battery units; hardwired alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (where there is a fuel-burning appliance or attached garage)","Secondary power source identification label, if the home has a secondary power source (Code 197-6, P.L.2025, c.19)","Portable fire extinguisher in date and in compliance (the fire district form still lists it, and Code 197-6E(7) lists an out-of-date extinguisher as a failure reason)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request more than 10 business days before change of occupancy","amount":"$75"},{"label":"Request 4 to 10 business days before change of occupancy","amount":"$125"},{"label":"Request fewer than 4 business days before change of occupancy","amount":"$175"},{"label":"Same-day inspection (ordinance)","amount":"$250"},{"label":"Same-day inspection (fire district form)","amount":"$225.00"},{"label":"Re-inspection (failed inspection, no-show or incomplete application)","amount":"$50.00"}]$j$::jsonb, $t$https://delawaretwpnj.org/government/forms/fire-prevention/2327-application-for-smoke-alarm-carbon-monoxide-alarm-fire-extinguisher-compliance/file$t$, $t$https://delawaretwpnj.org/departments/fire-prevention$t$, $j$[{"url":"https://delawaretwpnj.org/departments/fire-prevention","label":"Official source (delawaretwpnj.org)"},{"url":"https://delawaretwpnj.org/departments/construction","label":"Official source (delawaretwpnj.org)"},{"url":"https://ecode360.com/13582752","label":"Official source (ecode360.com)"},{"url":"https://delawaretwpnj.org/government/forms/fire-prevention/2327-application-for-smoke-alarm-carbon-monoxide-alarm-fire-extinguisher-compliance/file","label":"Official source (delawaretwpnj.org)"},{"url":"https://lambertvillefirestation.com/permits/","label":"Official source (lambertvillefirestation.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/51506748","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Fire Prevention services are provided through a shared service agreement between the Township of Delaware and Lambertville Fire District #1.$t$, $t$0e5c7978c26c654a6706a28ab871fdf20cffd5e2272559db71cbce429eb0751a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":5,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1007.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1007.json$t$, true),
  ($t$1009$t$, $t$Flemington Borough$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC)$t$, $j$["Issued by: Borough of Flemington Construction / Zoning Department (Code Enforcement)","Contact: John Tillotson, Building Inspector, Construction Official (Technical Assistant: Maureen McIvor, mmcivor@historicflemington.com) · 908-782-8840 x220 · jtillotson@historicflemington.com","Apply: The code says to apply and pay at least two months before the change of ownership; the fee is lowest when filed 16 to 40 business days before closing.","How to apply: Fill out the Application for Construction Records Clearance (in the Borough's 'Selling or Renting Your Home' packet) with the closing date, seller, property and block/lot, and submit it with the fee for the matching time window to Code Enforcement, 38 Park Avenue, Flemington, NJ 08822. Choose call-to-pick-up or email for delivery.","Valid for: 90 days, and only for permits issued before the CRC application; a new CRC is needed for each sale or occupancy change","Records search for open construction permits, fines, fees, penalties or any money owed to any Borough entity","Any open permits must get their inspections and certificates (or be exempted by the Construction Official) before the CRC is issued","Smoke/CO certificate (CSACMAPFEC) from Flemington Borough Fire Safety; the code says no certificate of occupancy or continued certificate of occupancy is issued for a dwelling unit until that section is met","Owner and seller must certify in writing to the fire official that the home complies with the smoke/CO rules before the sale","Also: Sanitary sewer (sump pump) inspection: The Borough Sewer Department inspects before closing. Fee $25.00, payable to Flemington Borough Sewer Department (separate check from the smoke fee). Allow 2 weeks before closing. Non-owner occupied residential, commercial and 5+ unit buildings only need one if not inspected in the last two years. Phone (908) 782-8840 x223.","Also: Water utility (meter) inspection: Borough Water Department inspection before closing. Fee $30.00, payable to Flemington Borough Water Department. Allow 2 weeks before closing. Phone (908) 782-8840 x223.","Also: Final water/sewer read: Submit the Final Read Request; the final reading is done on the closing date and a $35 fee is added to the final bill. Tell the Borough if the closing date changes.","Also: Open permits and money owed: The CRC records search requires open permits to be closed and any money owed to any Borough entity to be paid before the CRC is issued."]$j$::jsonb, $j$[{"label":"Construction Records Clearance, 16 to 40 business days before closing","amount":"$50.00"},{"label":"Construction Records Clearance, 6 to 15 business days before closing","amount":"$80.00"},{"label":"Construction Records Clearance, 1 to 5 business days before closing","amount":"$150.00"},{"label":"Construction Records Clearance, 1 to 5 business days (Borough Code 9A-3j)","amount":"$150"},{"label":"Construction Records Clearance, 6 to 15 business days (Borough Code 9A-3j)","amount":"$80"},{"label":"Construction Records Clearance, 16 to 40 business days (Borough Code 9A-3j)","amount":"$50"}]$j$::jsonb, $t$https://www.historicflemington.com/forms-and-documents/forms/department-documents/construction/1446-selling-or-renting-your-home/file$t$, $t$https://www.historicflemington.com/departments/construction$t$, $j$[{"url":"https://ecode360.com/34748337","label":"Official source (ecode360.com)"},{"url":"https://www.historicflemington.com/forms-and-documents/forms/department-documents/construction/1446-selling-or-renting-your-home/file","label":"Official source (historicflemington.com)"},{"url":"https://ecode360.com/34748219","label":"Official source (ecode360.com)"},{"url":"https://www.historicflemington.com/departments/construction","label":"Official source (historicflemington.com)"}]$j$::jsonb, $t$A construction records clearance (CRC) shall be required prior to the sale or change of tenant of any residential or commercial structure.$t$, $t$9b98c84a6c9daa9e17e1e5566c783277fd2d29378a026edc0710c56b03fda353$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":13,"fee_ok":6,"fee_bad":0,"fee_unchecked":7,"quotes":17,"q_ok":9,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1009.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1009.json$t$, true),
  ($t$1009$t$, $t$Flemington Borough$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Flemington Borough Fire Safety (Bureau of Fire Safety / Fire Marshal) (town fire bureau)","Contact: Ken McCormick, Fire Marshal (Fire Official) · 908-782-8840 ext. 227 · fireofficial@historicflemington.com","Apply: Fee depends on business days before closing: more than 10 business days for the lowest fee. The certificate is issued right after a passed inspection and is valid for six months.","How to apply: Complete the 'Request for Certificate of Inspection Smoke & Carbon Monoxide Detector & Fire Extinguisher' form (in the Selling or Renting Your Home packet, or the separate fillable form) and submit it with the full fee, payable to \"Flemington Boro Fire Safety\", to 38 Park Ave, Flemington, NJ 08822. One form per inspection. Test all systems before the inspection. A no-show (no representative within 10 minutes, no power or no access) needs a new fee equal to the original.","Fire official in the NJ state directory (town), updated 8/17/2026: Kenneth J McCormick II · (908) 782-8840 · kmccormick@historicflemington.com","Smoke alarms on every level (excluding crawl spaces and unfinished attics) and within 10 feet of each bedroom; homes built 1990 or later also need one in each bedroom","Alarm type depends on the year built: before 1977, 10-year sealed battery alarms; 1977 to 1983, electric alarms; 1984 to 1989, interconnected electric; 1990 on, interconnected electric with battery backup","Smoke and CO alarms no older than 10 years from manufacture; listed to ANSI/UL 217, installed per NFPA 72","Carbon monoxide alarm within 10 feet of each sleeping area (electric, battery or plug-in)","Fire extinguisher (form still lists it): mounted within 10 feet of the kitchen in the path of egress, top no higher than 5 feet, 2A:10B:C, no more than 10 lbs, with proof of purchase within 1 year or a service tag within 12 months, and the manual left for the new occupant","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), received more than 10 business days before closing","amount":"$65"},{"label":"Received four to nine business days before closing","amount":"$100"},{"label":"Received fewer than four business days before closing","amount":"$200"},{"label":"Second and later re-inspections (first re-inspection included)","amount":"$30"},{"label":"Smoke/CO certificate, more than 10 days before closing (Borough packet)","amount":"$65.00"},{"label":"Smoke/CO certificate, 10 to 4 days before closing (Borough packet)","amount":"$100.00"},{"label":"Smoke/CO certificate, less than 4 days before closing (Borough packet)","amount":"$200.00"}]$j$::jsonb, $t$https://www.historicflemington.com/forms-and-documents/forms/department-documents/fire-prevention/564-smoke-co-detector-cert-for-change-of-occupancy-in-all-homes-rental-units-fillable/file$t$, $t$https://www.historicflemington.com/departments/fire-prevention$t$, $j$[{"url":"https://ecode360.com/34748219","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35093839","label":"Official source (ecode360.com)"},{"url":"https://www.historicflemington.com/forms-and-documents/forms/department-documents/construction/1446-selling-or-renting-your-home/file","label":"Official source (historicflemington.com)"},{"url":"https://www.historicflemington.com/forms-and-documents/forms/department-documents/fire-prevention/564-smoke-co-detector-cert-for-change-of-occupancy-in-all-homes-rental-units-fillable/file","label":"Official source (historicflemington.com)"},{"url":"https://www.historicflemington.com/departments/fire-prevention","label":"Official source (historicflemington.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The owner of each dwelling unit that is sold, leased, or otherwise made subject to a change of occupancy for residential purposes shall have a CSACMAPFEC obtained by the owner prior to said change of occupancy in accordance with N.J.A.C. 5:70-2.3 which evidences compliance with N.J.A.C. 5:70-4.19.$t$, $t$cd0a559f460c58d03d27958e92e964a6b74324b952992977cc988afd44c16a71$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":13,"fee_ok":6,"fee_bad":0,"fee_unchecked":7,"quotes":17,"q_ok":9,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1009.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1009.json$t$, true),
  ($t$1010$t$, $t$Franklin Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC) / resale clearance certification$t$, $j$["Issued by: Franklin Township (Hunterdon) Construction Department","Contact: Mark Fornaciari, Construction Official (Technical Assistant: Andrea Bergen, abergen@franklin-twp.org) · 908-735-5215 ext. 2 · construction@franklin-twp.org","Apply: Allow 10 business days to process (more if permits need to be closed); the code says to apply at least 10 business days before the change of ownership.","How to apply: Download the Construction Records Clearance (CRC) Application from the Construction Department's Applications and Forms page, or pick one up at the Municipal Building, 202 Sidney Road, Pittstown, NJ 08867 (Monday to Friday 8 am to 4 pm). Return it to the Building Department with a $200.00 check payable to Franklin Township, a copy of the listing, the private well test report, the signed water test sign-off sheet and a copy of the smoke certificate.","Valid for: If the closing does not occur within six months, a new application and payment may be required (per the application form)","Construction Records Clearance Application - Residential, with a copy of the home's real estate listing","Records search for open construction permits; open permits need final inspections and certificates before the CRC is issued","New Jersey Private Well Water Test report","Water Test sign-off sheet signed by the seller and the purchaser","Copy of the smoke certificate from the Franklin Township Bureau of Fire Prevention (Fire District #1)","Application asks about pools, pool fence, hot tub, finished basement, outbuildings, decks and whole house generator","Also: Private well water test: The CRC needs a New Jersey Private Well Water Test report and a Water Test sign-off sheet signed by seller and purchaser (Private Well Testing Act).","Also: Open permits: Any open construction permits must get final inspections and certificates before the CRC is issued."]$j$::jsonb, $j$[{"label":"Resale clearance certification records search (Township Code 182-10L)","amount":"$200"},{"label":"CRC fee as listed in Chapter 157 (2016, older)","amount":"$150"},{"label":"CRC application fee (Township form, 12-1-20)","amount":"$200.00"}]$j$::jsonb, $t$https://storage.googleapis.com/proudcity/franklintownshipnj/uploads/2020/06/Updated-CRC-12-1-20.pdf$t$, $t$https://franklin-twp.org/departments/construction/$t$, $j$[{"url":"https://ecode360.com/32466714","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10075192","label":"Official source (ecode360.com)"},{"url":"https://storage.googleapis.com/proudcity/franklintownshipnj/uploads/2020/06/Updated-CRC-12-1-20.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://franklin-twp.org/construction-applications-and-forms/","label":"Official source (franklin-twp.org)"},{"url":"https://franklin-twp.org/departments/construction/","label":"Official source (franklin-twp.org)"}]$j$::jsonb, $t$A CRC shall be required prior to the sale of any residential or commercial structure and prior to the rental of any tenant space in a commercial structure within the Township.$t$, $t$5611a246b63b88ffe43b3b905405ef5c36ebd9d7a67719faa0d35edc68ad15b4$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":4,"fee_bad":0,"fee_unchecked":7,"quotes":17,"q_ok":10,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1010.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1010.json$t$, true),
  ($t$1010$t$, $t$Franklin Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Franklin Township Fire District #1, Bureau of Fire Prevention (Fire Marshal) (fire district)","Contact: Richard Dziminski, Fire Official listed in the NJ DCA fire directory (survey 1/30/2023; may be out of date) · 908-735-8704 · firesafety@franklintwpfiredistrict1.com","Apply: Fee depends on business days before the change of occupancy: more than 10 business days for the lowest fee. Staff are part-time, so inspections are scheduled at mutually convenient times; fees must be paid when the appointment is scheduled.","How to apply: Download the 'Certificate of Smoke Alarm' packet from the Fire District website (or pick one up) and submit it at the Bureau of Fire Prevention, 67 Quakertown Rd, Pittstown, NJ 08867. Staff will call or email to schedule; pay when scheduling by exact cash, check payable to \"Franklin Township Fire District #1\" (checks to \"Franklin Township\" are not accepted) or online invoice (mark it on the application).","Fire official in the NJ state directory (fire district), updated 1/30/2023: Richard Dziminski · (908) 735-8704","Smoke alarms no older than 10 years; type depends on year built: before 1977, 10-year sealed battery alarm on each level including the basement; 1977 to Feb 21, 1983, interconnected electric alarms on the sleeping level and basement plus 10-year sealed battery alarms on other levels","Built Feb 22, 1983 to Apr 30, 1993: interconnected electric alarms with battery backup on every level including the basement; built May 1, 1993 or later: also in sleeping areas and every bedroom","Basement smoke alarm on the ceiling at the bottom of the basement stairs","Carbon monoxide alarm within 10 feet of every bedroom, not past the maker's replacement date","Secondary power source label (generators, solar, battery storage) within 18 inches of the main electrical panel and meter, not handwritten, e.g. 'CAUTION: MULTIPLE SOURCES OF POWER.'","No portable fire extinguisher needed (the District's January 2026 packet says they are no longer required)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, more than 10 business days before change of occupancy","amount":"$60"},{"label":"Four to 10 business days before","amount":"$100"},{"label":"Fewer than four business days before","amount":"$170"},{"label":"No-show or failed inspection (reinspection)","amount":"$25"},{"label":"Smoke/CO certificate, more than 10 business days (District form)","amount":"$60.00"},{"label":"Four to 10 business days (District form)","amount":"$100.00"},{"label":"Less than four business days (District form)","amount":"$170.00"},{"label":"Re-inspection (District form)","amount":"$25.00"}]$j$::jsonb, $t$https://franklintwpfiredistrict1.com/downloads/bureau-of-fire-prevention/certificate-of-smoke-alarm.pdf$t$, $t$https://franklintwpfiredistrict1.com/bureau-of-fire-prevention$t$, $j$[{"url":"https://franklintwpfiredistrict1.com/downloads/bureau-of-fire-prevention/certificate-of-smoke-alarm.pdf","label":"Official source (franklintwpfiredistrict1.com)"},{"url":"https://ecode360.com/10075192","label":"Official source (ecode360.com)"},{"url":"https://franklintwpfiredistrict1.com/bureau-of-fire-prevention","label":"Official source (franklintwpfiredistrict1.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Prior to the sale or lease of any residential structure or change in occupancy for residential purposes, the owner shall obtain a CSACMAPFEC from the Franklin Township Fire Marshal.$t$, $t$67b0caa93001b3ae4901ba13509d7cfa346da2027b71f86e9c8050f7e7b862ad$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":4,"fee_bad":0,"fee_unchecked":7,"quotes":17,"q_ok":10,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1010.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1010.json$t$, true),
  ($t$1014$t$, $t$High Bridge Borough$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continuing Certificate of Occupancy$t$, $j$["Issued by: Borough of High Bridge CCO Officer (smoke/CO part enforced by the Fire Marshal); CRC by the Borough construction enforcing agency","Contact: Fredrick C Roll, Fire Official; the Borough code assigns the smoke/CO part of the CCO to the Fire Marshal · 908-638-6455 · fireofficial@highbridge.org","Apply: The CCO Officer inspects within 10 working days of a complete application and fee, and issues the CCO (or a written violation list) within three working days after. The CRC application and fee are due at least 25 business days before the change of ownership.","How to apply: File the CCO application at the Borough of High Bridge administrative office (97 West Main Street) on the Borough's form, with the fee for the time left before the change of occupancy. File the CRC application and fee on the Borough's form at least 25 business days before closing. The Borough website (highbridge.org) blocked automated access, so the forms could not be checked online.","Valid for: CRC: six months from issuance. CCO: not stated.","CCO inspection: property fit for habitation and in line with Borough ordinances and state safety, health, maintenance and building codes","Smoke alarms (UL listed, under 10 years old, per the code when built, NFPA 72), carbon monoxide alarms (UL 2034) and a secondary power source label if the home has one, checked as part of the CCO","Corrections followed by a reinspection ($50); a new owner may get a CCO with an approved written repair plan","Construction Records Clearance: records check for open construction permits; open permits need final inspections and certificates first","Also: Sump pump certificate: Before any property is sold, the owner must get a certificate from the Director of Public Works that no sump pump or groundwater drain is connected to the sanitary sewer. The seller files the application at least 10 days before the change in ownership (Chapter 303). No fee amount was found.","Also: Final water reading: Notify the Borough Clerk three days before closing for a final meter reading and give the new owner's name; the amount owed goes to the closing attorney (Chapter 407).","Also: Private well potability certificate: Before transfer of title of a home on a private well, a certificate of potability is needed from the Hunterdon County Health Department (Chapter 407).","Also: Open permits (CRC): The Construction Records Clearance requires open construction permits to be finaled before closing; CRC fee $100 if filed 25 days ahead, $150 within 10 days."]$j$::jsonb, $j$[{"label":"CCO with smoke/CO/secondary power inspection, request received more than 10 business days before the change of occupant","amount":"$100"},{"label":"CCO with smoke/CO inspection, request received four to 10 business days before","amount":"$200"},{"label":"Reinspection for a TCO or CCO","amount":"$50"},{"label":"CCO reinspection after violations are corrected","amount":"$50"},{"label":"Construction Records Clearance, submitted within 25 days","amount":"$100"},{"label":"Construction Records Clearance, submitted within 10 days","amount":"$150"}]$j$::jsonb, null, $t$https://highbridge.org/$t$, $j$[{"url":"https://ecode360.com/14100924","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/14101071","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/37514622","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A continuing certificate of occupancy, hereinafter referred to as a "CCO," shall be required for all existing dwelling units, auxiliary structures, commercial buildings and industrial buildings in the Borough of High Bridge before a change in occupancy or change of use of any such structure may occur.$t$, $t$afe85a20621861d040f9f330c4e1be5b1ae5b21b3d6980ee1c8d5d7689a4e7bb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":0,"fee_bad":0,"fee_unchecked":9,"quotes":12,"q_ok":1,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/1014.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1014.json$t$, true),
  ($t$1014$t$, $t$High Bridge Borough$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: High Bridge Borough Fire Marshal / Fire Official (Bureau of Fire Prevention), as part of the Continuing Certificate of Occupancy (town fire bureau)","Contact: Fredrick C Roll, Fire Official (NJ DCA fire directory, survey 7/28/2025) · 908-638-6455 · fireofficial@highbridge.org","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lower fee. Inspection within 10 working days of a complete application.","How to apply: Apply for the Continuing Certificate of Occupancy at the Borough administrative office, 97 West Main Street, High Bridge; the smoke/CO/secondary power inspection is part of it. Contact the Fire Official at 908-638-6455 or fireofficial@highbridge.org.","Fire official in the NJ state directory (town), updated 7/28/2025: Fredrick C Roll · (908) 638-6455 · fireofficial@highbridge.org","Smoke detectors UL listed, no older than 10 years, meeting the code in force when the home was built, installed and maintained per NFPA 72, not recalled","Carbon monoxide alarms listed to UL 2034, installed per the Uniform Fire Code and NFPA 720","Secondary power source label (ANSI Z535.4) within 18 inches of the main electrical panel and meter, if the home has a generator, solar or battery system","No portable fire extinguisher listed in the June 2026 Article III (the 2024 fee section title still mentions one)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/secondary power compliance (with CCO), more than 10 business days before","amount":"$100"},{"label":"Four to 10 business days before","amount":"$200"},{"label":"Reinspection","amount":"$50"}]$j$::jsonb, null, $t$https://highbridge.org/$t$, $j$[{"url":"https://ecode360.com/14101071","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fees for certificate of smoke alarm and carbon monoxide alarm and portable fire extinguisher compliance (CSACMAPFEC) as required by N.J.A.C. 5:70-2.3, shall be based upon the amount of time remaining before the change of occupant is expected, as follows:$t$, $t$682ab252afc37bea954b7aee0352c4f463c254c956565486dbb0247992a2aa2d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":0,"fee_bad":0,"fee_unchecked":9,"quotes":12,"q_ok":1,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/1014.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1014.json$t$, true),
  ($t$1015$t$, $t$Holland Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO) for change in ownership$t$, $j$["Issued by: Holland Township Zoning Officer","Apply: Contact the Zoning Officer two weeks before closing. By code, the Zoning Officer inspects within 14 days of notice and issues the certificate within one business day of a passed inspection.","How to apply: Call the Zoning Officer about two weeks before closing to arrange the inspection, and pay $75.00 by check payable to the Township of Holland. The Zoning Officer may ask for an application form. Township offices are at 61 Church Road, Milford, NJ 08848.","Notify the Zoning Officer of the impending change in ownership and pay the inspection fee","Inspection for obvious noncompliance with Township Board of Health ordinances, Chapter 135 (Sewers) and the Zoning chapter","Smoke and carbon monoxide alarms in the right locations and working at the time of inspection (the CCO fee includes the smoke/CO inspection)","Fire extinguisher (the Township's Smoke & Carbon Monoxide Detectors & Fire Extinguishers handout is linked from the CCO section) (form still lists it)","The inspection does not cover the septic, sewage disposal, well, plumbing, electric or other systems","Also: Tax search notice: The Tax Search Officer puts a notice of the CCO requirement on every tax search for residential property, so the CCO shows up in title work."]$j$::jsonb, $j$[{"label":"CCO inspection (includes smoke and CO alarm inspection)","amount":"$75.00"},{"label":"Second inspection","amount":"$75.00"},{"label":"Certificate of occupancy first inspection fee (Code Chapter 83)","amount":"$75"},{"label":"Certificate of occupancy reinspection fee (Code Chapter 83)","amount":"$75"}]$j$::jsonb, null, $t$https://www.hollandtownshipnj.gov/departments/zoning-department$t$, $j$[{"url":"https://www.hollandtownshipnj.gov/departments/zoning-department","label":"Official source (hollandtownshipnj.gov)"},{"url":"https://ecode360.com/10268466","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/14104236","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Holland Township requires that you obtain a Continued Certificate of Occupany (CCO) prior to selling, renting or buying a home.$t$, $t$465ff18953945632291d91f979ad63186d4915d6e8d55c6c09cc638608fbe022$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1015.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1015.json$t$, true),
  ($t$1015$t$, $t$Holland Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire township: issued by Holland Township Zoning Officer (smoke and CO alarm check done as part of the CCO inspection)","Entire township, apply: Contact the Zoning Officer two weeks before closing.","Entire township, how to apply: Part of the CCO request: call the Zoning Officer and pay $75.00 by check payable to the Township of Holland.","Entire township (State-enforced, LEA code S): issued by NJ Department of Community Affairs, Division of Fire Safety (State is the fire code enforcing agency for Holland) (NJ DCA, state)","Entire township (State-enforced, LEA code S) contact: Louis Kilmer, Fire Official of record for Holland (NJ Division of Fire Safety), per the state directory · (609) 633-6132","Entire township (State-enforced, LEA code S), apply: State fee tiers count business days between DCA's receipt and the closing date: more than ten business days for the lowest fee. A new application is needed if the change of occupant does not happen within 6 months (per the DCA form).","Entire township (State-enforced, LEA code S), how to apply: If a State certificate is needed, apply to the NJ Division of Fire Safety online (DCA RIMS, Apply for a CSDCMAC) or with the DCA form mailed to PO Box 809, Trenton, NJ 08625-0809, with a check payable to Treasurer, State of New Jersey. Confirm with the Township first, since its CCO inspection already covers smoke and CO alarms.","Fire official in the NJ state directory (NJ DCA, state), updated 9/12/2025: Louis Kilmer · (609)633-6132","Smoke alarms and carbon monoxide alarms in the appropriate locations and working at the time of the CCO inspection","Fire extinguisher (listed on the Township handout linked from the CCO section) (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Entire township: CCO inspection, which includes the smoke and carbon monoxide alarm inspection","amount":"$75.00"},{"label":"Entire township (State-enforced, LEA code S): State smoke/CO certificate (N.J.A.C. 5:70-2.9(d)), received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Entire township (State-enforced, LEA code S): Received four to 10 business days before","amount":"$90.00"},{"label":"Entire township (State-enforced, LEA code S): Received fewer than four business days before","amount":"$161.00"}]$j$::jsonb, null, $t$https://www.hollandtownshipnj.gov/departments/zoning-department$t$, $j$[{"url":"https://ecode360.com/10268466","label":"Official source (ecode360.com)"},{"url":"https://www.hollandtownshipnj.gov/departments/zoning-department","label":"Official source (hollandtownshipnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/forms/bfce/certificationinlieu.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The foregoing fee shall include an inspection as to a smoke detector and carbon monoxide alarm where such devices are required by state law.$t$, $t$a735906aac712ca60ced7fcfe753c7c2373cc748230151251e3c1274dfd6d884$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1015.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1015.json$t$, true),
  ($t$1017$t$, $t$Lambertville City$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC)$t$, $j$["Issued by: City of Lambertville Construction Office","Contact: Paul Hardifer, Jr., Construction Official (also Zoning Officer) · 609-397-0110 x223 · construction@lambertvillenj.org","How to apply: Fill out the City's Construction Records Clearance Application (linked on the Construction page) and submit it with the $50.00 fee to the Construction Office, City Hall, Second Floor, 18 York Street, Lambertville, NJ 08530. Pay by check payable to the City of Lambertville or online (credit card or e-check). Office hours are weekdays 9:00 a.m. to 4:30 p.m. (Tuesday to 7:30 p.m., Friday to 12:30 p.m.).","Records search showing no open construction permits (building, electric, plumbing, mechanical or fire) or violations on the property","Application lists the property address, block and lot, owner, agent and closing date","Also: Sump pump inspection (Lambertville Municipal Utilities Authority): All properties need an LMUA sump pump inspection before a sale or transfer of ownership. Sump pumps, dehumidifiers and other groundwater or surface drains may not be connected to the sewer; any found must be removed and capped, then reinspected. Inspections are 9 a.m. to 12 p.m. and 1 to 3 p.m.; book with the LMUA at 609-397-1496 (8 a.m. to 4 p.m., Monday to Friday) or by email to mparsons@lambertvillemua.com.","Also: Construction Records Clearance: Covered under the resale certificate: the Construction Office confirms there are no open permits before the sale."]$j$::jsonb, $j$[{"label":"Construction Records Clearance application","amount":"$50.00"}]$j$::jsonb, $t$https://docs.google.com/document/d/15QrzNLkkW5n7eKRU1ys54iSEyqODBTPc/edit?usp=sharing&ouid=101551011737263940262&rtpof=true&sd=true$t$, $t$https://www.lambertvillenj.org/departments/construction$t$, $j$[{"url":"https://www.lambertvillenj.org/departments/construction","label":"Official source (lambertvillenj.org)"},{"url":"https://docs.google.com/document/d/15QrzNLkkW5n7eKRU1ys54iSEyqODBTPc/edit?usp=sharing&ouid=101551011737263940262&rtpof=true&sd=true","label":"Official source (docs.google.com)"}]$j$::jsonb, $t$Here's what you will need prior to sale:$t$, $t$359bc9f02385a9dd5faca4fcdaa37f2f597e5b999572faa51242c741c945e368$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":5,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1017.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1017.json$t$, true),
  ($t$1017$t$, $t$Lambertville City$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lambertville Fire District #1, Bureau of Fire Safety (Fire Marshal's Office) (fire district)","Contact: Frank J Ur, Fire Official · 609-397-2084 · firemarshal17@lfddistrict1.com","Apply: Fee depends on business days before the change of occupancy: more than 10 business days for the lowest fee; same-day inspection costs more. Allow at least 1 to 2 weeks if mailing. The appointment time range cannot be narrowed down.","How to apply: Download the Application for Smoke Alarm, Carbon Monoxide Alarm & Fire Extinguisher Compliance from the Fire Marshal page, fill it out completely and send it with the fee (checks payable to Lambertville Fire District # 1), or pay online through the District's electronic payment link. Incomplete applications or improper payments are rejected and need new fees.","Fire official in the NJ state directory (fire district), updated 7/13/2026: Frank J Ur · (609) 397-0110 · firemarshal17@lfddistrict1.com","Smoke alarms per the year the home was built (for example, before January 1977 battery alarms on all levels; March 2016 to present hardwired, interconnected alarms with battery backup on every level, near and in each sleeping area); battery-only alarms must be 10-year sealed, UL 217 listed, and no older than 10 years","Basement battery smoke alarms within 10 feet of the base of the stairs","Low voltage/central alarm systems need a full NFPA 72 inspection report from a certified contractor","Carbon monoxide alarms (UL 2034) in the immediate vicinity of the sleeping areas, within 10 feet of sleeping room doors","Portable fire extinguisher, ABC type rated at least 2A-10B:C and no more than 10 pounds, within 10 feet of the kitchen in the path of egress, mounted on the manufacturer's bracket, serviced and tagged within 12 months or with a recent purchase receipt (form says still required per municipal ordinance 11-1.8) (form still lists it)","Secondary power source label (CAUTION: MULTIPLE SOURCES OF POWER) within 18 inches of the main electrical panel and meter, if the home has a generator, solar panels or battery storage","A representative must be on site; snow and ice must be cleared; power must be on","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, CO alarm and fire extinguisher certificate, received more than 10 business days before the change of occupancy","amount":"$75.00"},{"label":"Received 4 to 10 business days before the change of occupancy","amount":"$125.00"},{"label":"Received fewer than 4 business days before the change of occupancy","amount":"$175.00"},{"label":"Same day inspection","amount":"$225.00"},{"label":"Reinspection","amount":"$50.00"}]$j$::jsonb, $t$https://lambertvillefirestation.com/wp-content/uploads/2026/02/Aplication-Smoke-DetectorCarbon-Monoxide-Detector-Fire-Extinguisher-Compliance.pdf$t$, $t$https://lambertvillefirestation.com/permits/$t$, $j$[{"url":"https://www.lambertvillenj.org/departments/construction","label":"Official source (lambertvillenj.org)"},{"url":"https://lambertvillefirestation.com/permits/","label":"Official source (lambertvillefirestation.com)"},{"url":"https://lambertvillefirestation.com/wp-content/uploads/2026/02/Aplication-Smoke-DetectorCarbon-Monoxide-Detector-Fire-Extinguisher-Compliance.pdf","label":"Official source (lambertvillefirestation.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$from the Lambertville Fire Department$t$, $t$f944100ffafa7eb018abe049586e9cf0f5259cfca53849c7bf7945b0b2c806e3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":5,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1017.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1017.json$t$, true),
  ($t$1022$t$, $t$Readington Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC)$t$, $j$["Issued by: Readington Township Construction Code Office (enforcing agency)","Contact: Thomas Petto, Construction Official (Code Office / Technical Assistant Kristina Chin, ext. 244) · (908) 534-2164 · KChin@readington.gov","Apply: Code says to apply with the fee at least 10 business days before the change of ownership or occupancy; the fee is lower when filed 6 to 12 business days ahead.","How to apply: Submit the Application for Construction Records Clearance (seller name, property address, block and lot, closing date, residential or commercial) with the fee to the Readington Township Code Enforcement / Construction office, 509 Route 523, Whitehouse Station, or use the Township's online CRC submission form linked on the Construction page. Choose pick-up or mail to owner/agent.","Valid for: 6 months from the date of issue, unless a change in occupancy has occurred","Records check by the construction office: no open construction permits on the property","Any open permits must get final inspections and the proper Uniform Construction Code certificates before the CRC is issued","Exempt transfers (for example spouse to spouse, parent and child, estate distribution, refinancing, deed corrections) do not need a CRC as long as no change in physical occupancy occurs"]$j$::jsonb, $j$[{"label":"Construction Records Clearance, 6 to 12 business days","amount":"$40.00"},{"label":"Construction Records Clearance, 1 to 5 business days","amount":"$70.00"}]$j$::jsonb, $t$https://www.readington.gov/government/forms/construction/56-construction-record-clearance-crc/file$t$, $t$https://www.readington.gov/departments/construction$t$, $j$[{"url":"https://ecode360.com/26808204","label":"Official source (ecode360.com)"},{"url":"https://www.readington.gov/government/forms/construction/56-construction-record-clearance-crc/file","label":"Official source (readington.gov)"},{"url":"https://www.readington.gov/departments/construction","label":"Official source (readington.gov)"},{"url":"https://www.readington.gov/departments/zoning-department","label":"Official source (readington.gov)"}]$j$::jsonb, $t$A construction records clearance (CRC) shall be required prior to the sale of any residential or commercial structure.$t$, $t$bc3dfbf82e304b97da03eb18d0c26cc93117b007e15466ba822e7297f45aa714$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":26,"q_ok":16,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/1022.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1022.json$t$, true),
  ($t$1022$t$, $t$Readington Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Raritan Township Department of Fire Safety Services (Fire Marshal's Office) (town fire bureau)","Contact: Dennis B. Concannon, Chief Fire Marshal (administrative assistant Suanne Traynor, (908) 806-6100 ext. 2280) · 908-806-6314 · firesafety@raritantwpnj.gov","Apply: Fee depends on business days between receipt of the completed application and fee and the closing date: 11 or more business days for the lowest fee. Inspections are on Wednesdays. The Township page recommends applying a couple of weeks before closing and says the certificate is good for 90 days.","How to apply: Apply online through the Township's SDL portal smoke detector application, or send the paper application with a check or money order payable to Raritan Township to the Department of Fire Safety Services, One Municipal Drive, Flemington, NJ 08822 (firesafety@raritantwpnj.gov). Fees must be paid before the certificate is issued. Inspections are done on Wednesdays; the office calls the Monday before with a time slot and takes no special requests.","Fire official in the NJ state directory (town), updated 10/25/2021: Dennis B Concannon II · (908) 534-4051 · dennis.concannon@raritantwpnj.gov","Smoke alarms as required for the year the home was built or renovated (for example, homes before 1977 need 10-year sealed battery alarms on all levels including the basement and within 10 feet outside all bedrooms; later homes must keep hardwired and interconnected alarms)","Hardwired smoke alarms may not be replaced with battery alarms; the most recent approved configuration must be kept","Carbon monoxide alarms within 10 feet outside every bedroom; battery or plug-in units allowed for homes built before 2016; alarms no older than 10 years","All alarms must be UL listed and replaced at end-of-life signal or 10 years from manufacture; smoke alarms at least 36 inches from ceiling fans and vents","Homes with a generator, solar panels, battery storage or other secondary power source need reflective 'CAUTION MULTIPLE SOURCES OF POWER' labels (ANSI Z535.4) within 18 inches of the main electrical panel and meter","House numbers at least 4 inches high, reflective or high-contrast, facing the access road","A fire alarm or combined burglar/fire alarm system that does not meet the listed requirements will not pass; finished basements are reported to the building department","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm and CO alarm certificate, completed application and fee received 11 or more business days before closing","amount":"$55.00"},{"label":"Received 10 or fewer and at least 4 business days before closing","amount":"$100.00"},{"label":"Received less than 4 business days before closing","amount":"$160.00"},{"label":"Re-inspection, per re-inspection","amount":"$55.00"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/hunterdon/raritantwp/forms/793b5cf4-0801-4827-a196-2d7a394cc3df?&mobile=1&embedded=7fb156eb-b206-4814-8b6b-fe7f17dea4a6$t$, $t$https://www.raritantwpnj.gov/departments/fire$t$, $j$[{"url":"https://www.raritantwpnj.gov/departments/fire","label":"Official source (raritantwpnj.gov)"},{"url":"https://www.raritantwpnj.gov/media/attachments/2026/07/06/residential-inspection-application-fillable-7.6.2026.pdf","label":"Official source (raritantwpnj.gov)"},{"url":"https://www.raritantwpnj.gov/fire-prevention-page-list/251-certificate-of-smoke-detector","label":"Official source (raritantwpnj.gov)"},{"url":"https://www.raritantwpnj.gov/forms-documents/forms/department-documents/fire-prevention/494-updated-residental-home-inspection-guide-with-labels-9-24-25/file","label":"Official source (raritantwpnj.gov)"},{"url":"https://ecode360.com/44451557","label":"Official source (ecode360.com)"},{"url":"https://www.readington.gov/departments/fire-prevention","label":"Official source (readington.gov)"},{"url":"https://ecode360.com/8746189","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Our primary responsibility is enforcement of the New Jersey Uniform Fire Code and other local fire safety regulations to over 150 square miles of Hunterdon County including the Townships of Raritan, Readington, Kingwood, and Tewksbury.$t$, $t$3c1a06e2a3dcc519f9bb584fc22631212b6aee0feda207bd66d72b70e18ec816$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":26,"q_ok":16,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/1022.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1022.json$t$, true),
  ($t$1025$t$, $t$Union Township$t$, $t$HUNTERDON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Union Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Michael Mullin, Zoning Officer · 908-735-8027 x19 · zoning@uniontwp-hcnj.org","How to apply: No Township resale Certificate of Occupancy. The Township's Zoning page says a certificate of occupancy is not required for a home sale; only the state Smoke Detector Fire Safety Certification is needed (see fire certificate)."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://uniontwp-hcnj.gov/zoning$t$, $j$[{"url":"https://uniontwp-hcnj.gov/zoning","label":"Official source (uniontwp-hcnj.gov)"}]$j$::jsonb, $t$If you are selling your home, a Smoke Detector Fire Safety Certification from the State is required.$t$, $t$ed245eabfdfd9e6b34e47757a269a712248538104951d66fa449d321213cded8$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1025.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1025.json$t$, true),
  ($t$1025$t$, $t$Union Township$t$, $t$HUNTERDON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety, Bureau of Fire Code Enforcement (state-enforced town) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official of record for state-enforced towns (NJ Division of Fire Safety), per the state directory · (609) 633-6132","Apply: State fee tiers count business days between the Division's receipt of the application and the closing date: more than ten business days for the lowest fee. Per the DCA form, a new application is needed if the change of occupant does not happen within 6 months.","How to apply: Apply to the NJ Division of Fire Safety online through DCA RIMS / firesolutions.dca.nj.gov ('Apply for a CSDCMAC (Smoke Detector) Certification'), as registered or non-registered user. The older paper form SD-41 goes to PO Box 809, Trenton, NJ 08625-0809 with a check or money order payable to Treasurer, State of New Jersey. Phone (609) 633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 2/22/2023: Louis Kilmer · (609)633-6132","Smoke alarm on each level, including basements (not crawl spaces or unfinished attics), and outside each separate sleeping area","Carbon monoxide alarm outside each separate sleeping area, within 10 feet of bedrooms","All alarms in working order; AC powered or interconnected alarms in homes built after January 1977 must be kept working","Portable fire extinguisher within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate (N.J.A.C. 5:70-2.9(d)), received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Received four to 10 business days before","amount":"$90.00"},{"label":"Received fewer than four business days before","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://uniontwp-hcnj.gov/zoning$t$, $j$[{"url":"https://uniontwp-hcnj.gov/zoning","label":"Official source (uniontwp-hcnj.gov)"},{"url":"https://uniontwp-hcnj.gov/fire","label":"Official source (uniontwp-hcnj.gov)"},{"url":"https://uniontwp-hcnj.gov/departments","label":"Official source (uniontwp-hcnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/RIMSHELP/bfce_public/bfce_-_public_-_apply_for_csdcmac_help.htm","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/forms/bfce/certificationinlieu.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$If you are selling your home, a Smoke Detector Fire Safety Certification from the State is required.$t$, $t$66a55639dbb12d882b4e76cb8d19765831f8886ac17860e5687dea408be48d06$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1025.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1025.json$t$, true),
  ($t$1301$t$, $t$Aberdeen Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Resale of Residential Property (Housing Department)$t$, $j$["Issued by: Aberdeen Township Housing Department (Housing Officer / Housing Inspector), Building/Construction/Housing office","Contact: 732-583-4200 ext. 177 · lisa.balletta@aberdeennj.org","Apply: The Township code says the certificate is granted or denied within 10 days of the application.","How to apply: Fill out the Township's Application for Certificate of Occupancy for Resale of Residential Property and pay the $175.00 non-refundable fee to the Housing Department at Town Hall, 1 Aberdeen Square, Aberdeen, NJ 07747. Call 732-583-4200 ext. 177 to schedule. Also apply separately to the fire district for the fire certificate of occupancy.","Township housing inspection before any new occupancy; a certificate is needed for each new occupant","Separate fire certificate of occupancy (smoke/CO) from the fire district that covers the property","Application lists the new owners and any intended occupants over 2 years of age","Certificate confirms the building and premises comply with all other Township ordinances"]$j$::jsonb, $j$[{"label":"Certificate of occupancy for resale of residential property","amount":"$175.00"},{"label":"Residential transfer of ownership inspection (Township Code 12-2.4c, Ord. 17-2023)","amount":"$175"}]$j$::jsonb, $t$https://aberdeennj.org/DocumentCenter/View/2920/RESALE-FORM$t$, $t$https://aberdeennj.org/200$t$, $j$[{"url":"https://aberdeennj.org/DocumentCenter/View/2920/RESALE-FORM","label":"Official source (aberdeennj.org)"},{"url":"https://www.aberdeennj.org/DocumentCenter/View/2889/17-2023","label":"Official source (aberdeennj.org)"},{"url":"https://aberdeennj.org/200","label":"Official source (aberdeennj.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF OCCUPANCY FOR RESALE OF RESIDENTIAL PROPERTY$t$, $t$69d732a6b4b7864067f76f54e11301faaddb440733df186306e4f617fcb28d15$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":17,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1301.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1301.json$t$, true),
  ($t$1301$t$, $t$Aberdeen Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District No: issued by Aberdeen Township Fire District No. 1, Bureau of Fire Prevention, Inspections and Fire Safety (fire district). 1 part of the Township (490 Lloyd Road firehouse area); confirm which district covers the property","Fire District No contact: Robert DeBold, District Chief & District Fire Official · (732) 566-3704 · rdebold@aberdeenfd1.com","Fire District No, apply: Fee depends on business days before the inspection; business days start when payment is made. Inspections between 10 a.m. and 12 p.m.","Fire District No, how to apply: Fill out the Fire District No. 1 Fire Certificate of Occupancy Inspection form completely and pay by check made out to Fire District No. 1 (cash, check, money order or bank check). Pick the inspection date you want. The fire district's site also points applicants to the Township Building/Construction/Housing Department at 732-583-4200 ext. 177.","Fire District No: issued by Aberdeen Township Fire District No. 2 (Cliffwood), Bureau of Fire Prevention (fire district). 2 part of the Township (Cliffwood area); confirm which district covers the property","Fire District No contact: George C Chevalier, Fire Official, per state directory · (732) 566-8920 · bfp489@optimum.net","Fire District No, how to apply: No District 2 web page or form was found. Contact the District 2 fire official listed in the state fire directory, or start with the Township Housing Department at 732-583-4200 ext. 177.","Fire official in the NJ state directory (fire district), updated n/a: George C Chevalier · (732) 566-8920 · bfp489@optimum.net","Smoke alarm on every floor, including basements, and in the hallway outside the bedrooms","Carbon monoxide alarm in the hallway outside the bedrooms","Battery smoke alarms (and combination smoke/CO alarms) must be 10-year sealed battery units","Hardwired smoke or CO alarms over 10 years old must be replaced, and only with hardwired alarms","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District No: Fire certificate of occupancy (smoke/CO), 11 or more business days","amount":"$45.00"},{"label":"Fire District No: 4 to 10 business days","amount":"$90.00"},{"label":"Fire District No: 1 to 3 business days","amount":"$161.00"}]$j$::jsonb, $t$https://aberdeenfd1.com/docs/CERTIFICATE_OF_OCCUPANCY.pdf$t$, $t$https://aberdeenfd1.com/fire-prevention$t$, $j$[{"url":"https://aberdeenfd1.com/docs/CERTIFICATE_OF_OCCUPANCY.pdf","label":"Official source (aberdeenfd1.com)"},{"url":"https://aberdeenfd1.com/contact","label":"Official source (aberdeenfd1.com)"},{"url":"https://aberdeenfd1.com/fire-prevention","label":"Official source (aberdeenfd1.com)"},{"url":"https://aberdeennj.org/DocumentCenter/View/320/07-2020-PDF","label":"Official source (aberdeennj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$I AM AWARE THAT I MUST OBTAIN A CERTIFICATE OF OCCUPANCY FOR EACH NEW OCCUPANT FROM ABERDEEN FIRE DISTRICT NO. 1 AND THE ABERDEEN TOWNSHIP HOUSING INSPECTOR PRIOR TO ANY NEW OCCUPANCY.$t$, $t$fb7ae6704cdcba301d977f362e7c74523dc9dd33a5678747f4d2f9986c50aebc$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":17,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1301.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1301.json$t$, true),
  ($t$1302$t$, $t$Allenhurst Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Home Sale)$t$, $j$["Issued by: Borough of Allenhurst Code Official (Zoning / Code Officer)","Contact: Matt Mariano, Zoning / Code Officer · 732-531-2757 · code@allenhurstnj.org","Apply: The Borough code says a Certificate of Occupancy is granted or denied within ten days of the application.","How to apply: Complete the Borough's Application for Certificate of Occupancy (check Sale), attach a current survey, sign under oath and pay the fee to the Borough of Allenhurst, 125 Corlies Avenue, Allenhurst, NJ 07711. The form says to call 732-413-8911 or email zoning@allenhurstnj.org to set up the inspection. Borough Hall: 732-531-2757.","Borough inspection of the home for compliance with all Borough ordinances","Applications for sales must include a current survey of the property","List all people who will occupy the home (each adult may need an affidavit as a member of a single family unit), school-age and pre-school children, and pets","Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (CSACMAPFEC) is required for all residential CO applications","All fees paid and all ordinances complied with before an inspection is scheduled"]$j$::jsonb, $j$[{"label":"Certificate of occupancy inspection and reinspection, houses (Borough code 9-3.3, Section 307.3)","amount":"$125.00 per unit"},{"label":"Certificate of occupancy, houses (Borough application form)","amount":"$125.00"}]$j$::jsonb, $t$https://www.allenhurstnj.org/DocumentCenter/View/210/Certificate-of-Occupancy---Home-Sale$t$, $t$https://www.allenhurstnj.org/230/Zoning-BoardCode-Enforcement$t$, $j$[{"url":"https://ecode360.com/34651658","label":"Official source (ecode360.com)"},{"url":"https://www.allenhurstnj.org/DocumentCenter/View/210/Certificate-of-Occupancy---Home-Sale","label":"Official source (allenhurstnj.org)"},{"url":"https://www.allenhurstnj.org/303/Forms","label":"Official source (allenhurstnj.org)"},{"url":"https://www.allenhurstnj.org/230/Zoning-BoardCode-Enforcement","label":"Official source (allenhurstnj.org)"}]$j$::jsonb, $t$No owner, owner of rental properties, agent of owner, real estate agent or broker, firm, company, partnership, corporation or person or persons, shall sell, rent, transfer or occupy$t$, $t$274a95beed0c58070ffb2d4c1f322da94a60094c9501defe96b2967634fba153$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":3,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/1302.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1302.json$t$, true),
  ($t$1302$t$, $t$Allenhurst Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety (state-enforced) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official (NJ Division of Fire Safety), per state directory · (609) 633-6132","How to apply: Allenhurst is state-enforced for the fire code. Apply through the NJ DCA Division of Fire Safety (DCA service portal, 'Apply For Smoke Certification', choosing Monmouth County and Allenhurst) or call (609) 633-6132. The Borough's home sale CO packet also includes a smoke/CO certification application and says the certificate is required for every residential CO application.","Fire official in the NJ state directory (NJ DCA, state), updated 6/26/2026: Louis Kilmer · (609) 633-6132","Smoke alarms on each level of the home, including basements (not attics or crawl spaces)","Smoke alarm and carbon monoxide alarm outside each separate sleeping area, within 10 feet of bedrooms","10-year sealed battery smoke alarms, unless the home has 110 volt alarms or a low voltage fire alarm system (low voltage systems need an annual certification)","Fire extinguisher rated 2A-10B:C, no more than 10 lbs, mounted within 10 feet of the kitchen in the path of egress, tagged or newly purchased with a receipt (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate (N.J.A.C. 5:70-2.9(d)), received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Received four to 10 business days before","amount":"$90.00"},{"label":"Received fewer than four business days before","amount":"$161.00"}]$j$::jsonb, null, $t$https://firesolutions.dca.nj.gov$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.allenhurstnj.org/DocumentCenter/View/211/Certification-Smoke-Co-Detector-Application","label":"Official source (allenhurstnj.org)"},{"url":"https://ecode360.com/34651658","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Allenhurst Borough$t$, $t$d939cc6f2b9d1aacf72c5b564d6ba3d6e7cfe3139e88e1645c11d27e4f6ea2b0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":3,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/1302.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1302.json$t$, true),
  ($t$1303$t$, $t$Allentown Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for re-sale (housing inspection)$t$, $j$["Issued by: Upper Freehold Township Housing Inspector, under Allentown Borough's shared service agreement with Upper Freehold Township","Contact: Ron Gafgen, Construction Official (Upper Freehold Township, shared service for Allentown) · 609-758-7738 · rgafgen@uftnj.com","Apply: An appointment is scheduled with the Housing Inspector after the application and fee are received.","How to apply: Fill out the 'Upper Freehold Township / Allentown Borough Application for Re-Sale or Rental of Property' (check Resale) and pay the $100.00 fee. The Housing Inspector then schedules the inspection. The Upper Freehold Township Municipal Building is at 314 Route 539, Cream Ridge, NJ 08514, phone 609-758-7738, Monday to Thursday 8:30 AM to 4:15 PM.","Valid for: 60 days once issued","Housing inspection by the Upper Freehold Township Housing Inspector","Any housing violations must be corrected before the certificate is issued","For homes on a private well: well water requirements set by the Hamilton Township Health Department, which issues a certificate of compliance","Smoke detector on each floor including the basement and outside bedroom doors; ten-year sealed battery unless AC powered interconnected","Carbon monoxide detectors in the vicinity of all bedrooms","Residential ABC fire extinguisher, no larger than 10 lb, within 10 feet of the kitchen (form still lists it)","Also: Private well water (if the home is on a well): The resale form says applicants must follow the Hamilton Township Health Department's well water requirements (609-890-3873); that department issues a certificate of compliance before the Housing Inspector issues the Certificate of Occupancy."]$j$::jsonb, $j$[{"label":"Re-sale or rental inspection application","amount":"$100.00"}]$j$::jsonb, $t$https://allentownboronj.com/vertical/sites/%7B7748EEEB-2391-4653-8B6A-4A64C85A6D79%7D/uploads/Application.pdf$t$, $t$https://allentownboronj.com/index.asp?SEC=7808D9E7-82BB-4F21-97A3-C9DB99A7CF28$t$, $j$[{"url":"https://allentownboronj.com/vertical/sites/%7B7748EEEB-2391-4653-8B6A-4A64C85A6D79%7D/uploads/Application.pdf","label":"Official source (allentownboronj.com)"},{"url":"https://allentownboronj.com/index.asp?SEC=FD810ACB-AA5C-494E-8696-E6D815AA346D","label":"Official source (allentownboronj.com)"},{"url":"https://allentownboronj.com/index.asp?SEC=7808D9E7-82BB-4F21-97A3-C9DB99A7CF28","label":"Official source (allentownboronj.com)"}]$j$::jsonb, $t$APPLICATION FOR RE-SALE OR RENTAL OF PROPERTY$t$, $t$2b1a75f5d63915b8efff6e3ccc93087bd823736c7874ba8390aae3c0b4c77084$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1303.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1303.json$t$, true),
  ($t$1303$t$, $t$Allentown Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Robbinsville Township Bureau of Fire Prevention (Division of Fire), local enforcing agency for Allentown under a shared services agreement (town fire bureau)","Contact: Brian Johnson, Fire Official, per state directory · (609) 758-7738 · bjohnson@robbinsville.net","How to apply: No smoke/CO application or fee schedule for Allentown was found online. Call the fire official listed in the state directory (609-758-7738) to confirm where to apply and pay.","Fire official in the NJ state directory (town), updated 4/28/2025: Brian Johnson · (609) 758-7738 · bjohnson@robbinsville.net","Smoke detector on each floor level including the basement and outside bedroom doors","Smoke detectors must be ten-year sealed battery units unless AC powered interconnected; removable-battery detectors fail","Carbon monoxide detectors in the vicinity of all bedrooms","Residential ABC fire extinguisher, no larger than 10 lb, within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[{"url":"https://ecode360.com/46098830","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The local enforcement agency ("LEA") within the Borough of Allentown shall be the Bureau of Fire Prevention within the Division of Fire of the Township of Robbinsville, as set forth in the shared services agreement executed by the Township of Robbinsville and the Borough of Allentown, effective July 1, 2024.$t$, $t$b0362e266f6ed9221c7359babd60dc045428e9960ebf94c67e9e35fb8e67197e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1303.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1303.json$t$, true),
  ($t$1304$t$, $t$Asbury Park$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale Compliance (formerly Transfer of Title certificate, TOT)$t$, $j$["Issued by: City of Asbury Park Department of Community Development / Code Enforcement","Contact: Tamica Smith, Code Enforcement contact named on the City's Code Enforcement page (no title shown) · 732-502-5742 · tamica.smith@cityofasburypark.com","How to apply: Create an account on the SDL Portal (www.sdlportal.com, town Asbury Park, Monmouth County), choose Requests, then Certificate Registration, upload the City's fillable Certificate of Resale Compliance application and pay online. Or file the application at Code Enforcement, City Hall, 1 Municipal Plaza, Asbury Park, NJ 07712, with a non-refundable check or money order (no cash).","Application and inspection before the closing of title","Inspection against the City's Property Maintenance Code (interior and exterior checklist: paint, windows and screens, handrails, GFI outlets, heating, plumbing, sidewalks and steps, house numbers and more)","Smoke detector on each level and within 10 feet of every bedroom; photoelectric within 5 feet of a kitchen or bathroom","Carbon monoxide detectors outside all bedrooms, within 10 feet of every bedroom","All open construction (UCC) permits must have a passed final inspection on file before the inspection","Fireplaces and wood stoves certified by a certified chimney sweep","The office checks open permits, available COs and the number of units with the Tax Assessor, Clerk, Code Enforcement and Construction offices","A buyer of a property with an open compliance order or notice of violation must sign a notarized statement accepting responsibility for the repairs (Code PM-106.5)","Application by someone other than the owner or registered agent needs a notarized authorization letter","Also: Open permits: All open construction (UCC) permits must have a passed final inspection on file with the Construction Department before the resale inspection, and work done without permits must be permitted and inspected.","Also: Open violations (Code PM-106.5): If the owner has a compliance order or notice of violation, the property cannot be sold until it is fixed or the buyer signs a notarized statement accepting responsibility for the repairs.","Also: Multiple dwellings (3 or more units): A buyer of a hotel or multiple dwelling must register with the NJ DCA Bureau of Housing Inspection within 30 days of the transfer."]$j$::jsonb, $j$[{"label":"Certificate of Resale Compliance, sale of a single-family dwelling or condo unit","amount":"$125.00"},{"label":"Certificate of Resale Compliance, sale of a two-family dwelling or two dwellings on one lot","amount":"$150.00"},{"label":"Transfer of title, sale of a single-family dwelling (City Code 12-7.8b)","amount":"$125.00"},{"label":"Transfer of title, sale of a two-family dwelling or two dwellings on one lot (City Code 12-7.8b)","amount":"$150.00"},{"label":"Transfer of title certificate, single family or condo (Ordinance 3042 fee schedule)","amount":"$125.00"},{"label":"Transfer of title certificate, two-family (Ordinance 3042 fee schedule)","amount":"$150.00"}]$j$::jsonb, $t$https://www.cityofasburypark.com/DocumentCenter/View/187/Certificate-or-Resale-Compliance-Application-PDF$t$, $t$https://www.cityofasburypark.com/239/Code-Enforcement$t$, $j$[{"url":"https://www.cityofasburypark.com/239/Code-Enforcement","label":"Official source (cityofasburypark.com)"},{"url":"https://www.cityofasburypark.com/DocumentCenter/View/187/Certificate-or-Resale-Compliance-Application-PDF","label":"Official source (cityofasburypark.com)"},{"url":"https://ecode360.com/34670913","label":"Official source (ecode360.com)"},{"url":"https://www.cityofasburypark.com/DocumentCenter/View/3412/How-to-Open-an-SDL-Account-and-Submit-CO-and-TOT-Applications","label":"Official source (cityofasburypark.com)"},{"url":"https://ecode360.com/34670931","label":"Official source (ecode360.com)"},{"url":"https://www.cityofasburypark.com/DocumentCenter/View/191/Code-Enforcement-Fee-Schedule-PDF","label":"Official source (cityofasburypark.com)"}]$j$::jsonb, $t$To purchase or sell a property, a Certificate of Resale Compliance application must be completed before closing.$t$, $t$b1180023f0ef00572f0db13323fbbce49840fad546eebb7765d47f1ab43703c6$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1304.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1304.json$t$, true),
  ($t$1304$t$, $t$Asbury Park$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Asbury Park Code Enforcement Department (CSDCMAC inspections), for the Asbury Park Fire Department local enforcing agency","Contact: Tawheshia M Gates, Fire Official, per state directory (Inspector Tee Gates on the Fire Department page) · 732-502-5742","How to apply: City Code says smoke detector and carbon monoxide alarm compliance (CSDCMAC) inspections are done by the City's Code Enforcement Department. No separate smoke/CO application or fee schedule was found online; ask Code Enforcement (732-502-5742) whether it is part of the resale compliance inspection or a separate application.","Fire official in the NJ state directory, updated 1/14/2025: Tawheshia M Gates · (732) 774-7400 · tee.gates@cityofasburypark.com","Smoke detector on each level of the unit and within ten feet of every bedroom","Smoke detectors within 5 feet of a kitchen or bathroom must be photoelectric","Carbon monoxide detectors outside all bedrooms, within ten feet of every bedroom","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.cityofasburypark.com/239/Code-Enforcement$t$, $j$[{"url":"https://ecode360.com/50586684","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.cityofasburypark.com/171/Fire-Department","label":"Official source (cityofasburypark.com)"}]$j$::jsonb, $t$Certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC) inspections shall be conducted by the City's Code Enforcement Department.$t$, $t$f15eaaceca5845a9a1ca063437ef6dc3f2f443913b7fd13932448047c354a248$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1304.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1304.json$t$, true),
  ($t$1305$t$, $t$Atlantic Highlands Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Certificate of Inspection) for sale$t$, $j$["Issued by: Borough of Atlantic Highlands Code Enforcement Officer","Contact: Richard Colangelo, Code Enforcement Officer · 732-904-5498 · rcolangelo@ahnj.com","Apply: Inspections are done on Wednesdays between 12:00 pm and 2:00 pm. If a re-inspection is needed, contact the office within 30 days or the application is voided.","How to apply: Fill out the Borough's Application for Certificate of Inspection (Ord. 03-2011) with the closing date and buyer names, and pay the non-refundable fee to the Borough of Atlantic Highlands by cash, check or money order. File it at Borough Hall, 100 First Avenue, Atlantic Highlands, NJ 07716 (732-291-1444). The same packet includes the smoke/CO application.","Visual inspection of the exterior and interior; an adult must be present and gas, water and electric must be on","Any open permits must be finalized by the Building Department before the C/O inspection","Exterior items include visible house numbers (at least 4 inches), gutters, roof, windows and screens, handrails on stairs with 4 or more risers, guardrails on porches 30 inches or higher, no peeling paint, pool fencing with self-latching gate","Separate smoke detector / carbon monoxide alarm compliance inspection (see fire certificate)"]$j$::jsonb, $j$[{"label":"Certificate of Occupancy inspection, residential","amount":"$75.00"},{"label":"Certificate of Occupancy application, single family dwelling (form)","amount":"$75.00"},{"label":"Certificate of Occupancy application, multi family dwelling (form)","amount":"$75.00"}]$j$::jsonb, $t$https://www.ahnj.com/ahnj/Departments/Code%20Enforcement/Residential%20Certificate%20of%20Inspection%20and%20Fire.pdf$t$, $t$https://www.ahnj.com/ahnj/Inspections/$t$, $j$[{"url":"https://www.ahnj.com/ahnj/Inspections/","label":"Official source (ahnj.com)"},{"url":"https://www.ahnj.com/ahnj/Departments/Code%20Enforcement/Residential%20Certificate%20of%20Inspection%20and%20Fire.pdf","label":"Official source (ahnj.com)"},{"url":"https://www.ahnj.com/ahnj/Departments/Code%20Enforcement/","label":"Official source (ahnj.com)"}]$j$::jsonb, $t$Inspections are done on Wednesday's between 12:00pm - 2:00pm$t$, $t$02e8e715c75b0e9e3fbdf2c674a8b8a613672ef29c682f6b2e8a043bfba1e0a2$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":7,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1305.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1305.json$t$, true),
  ($t$1305$t$, $t$Atlantic Highlands Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Atlantic Highlands Fire Marshal's Office (Division of Fire Prevention) (town fire bureau)","Contact: Martin O. Hawley, Jr., Fire Marshal · (732) 291-1444 · hawleym4@verizon.net","Apply: Fee depends on business days between receipt of the application and the inspection date. Inspections are Wednesdays 12:00 pm to 2:00 pm and a representative must be present. If the change of occupant does not happen within 30 days of the inspection, a new application and fee are needed.","How to apply: Get the smoke detector certification application at the Building Department or print it with the C/O form (Residential Certificate of Inspection and Fire packet). Pay by check or money order made payable to 'Borough of Atlantic Highlands Fire' (the Inspections page says payable to Borough of Atlantic Highlands) and file at Borough Hall, 100 First Avenue.","Fire official in the NJ state directory, updated 2/6/2026: Martin O Hawley · (732) 291-1444 · hawleym4@verizon.net","Smoke alarms as required by the state for one and two family homes at change of occupant","Carbon monoxide alarms within 10 feet of all sleeping rooms if the home has a fuel burning appliance or an attached garage, in the location the manufacturer specifies; battery, hardwired or plug-in allowed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector certification, inspection more than ten business days after receipt","amount":"$45.00"},{"label":"Fewer than ten but more than four business days","amount":"$90.00"},{"label":"Four business days or fewer","amount":"$161.00"},{"label":"CSDMAC request 10 or more business days before the inspection (as listed on the Borough Inspections page; conflicts with $45.00 on the Fire Marshal page)","amount":"$54.00"},{"label":"CSDMAC request 4 to 10 business days before the inspection (Inspections page)","amount":"$90.00"},{"label":"CSDMAC request fewer than 4 days before the inspection (Inspections page)","amount":"$161.00"}]$j$::jsonb, $t$https://www.ahnj.com/ahnj/Departments/Code%20Enforcement/Residential%20Certificate%20of%20Inspection%20and%20Fire.pdf$t$, $t$https://www.ahnj.com/ahnj/Departments/Fire%20Marshall%20Office/$t$, $j$[{"url":"https://www.ahnj.com/ahnj/Departments/Fire%20Marshall%20Office/","label":"Official source (ahnj.com)"},{"url":"https://www.ahnj.com/ahnj/Inspections/","label":"Official source (ahnj.com)"},{"url":"https://www.ahnj.com/ahnj/Departments/Code%20Enforcement/Residential%20Certificate%20of%20Inspection%20and%20Fire.pdf","label":"Official source (ahnj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$When selling your home, a "smoke detector certification" is required through the State of New Jersey.$t$, $t$b9a1e935e4cd27e332a0c5d423f9bad81ede87018a49a1806be4382bd79e5d1e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":7,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1305.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1305.json$t$, true),
  ($t$1306$t$, $t$Avon-by-the-Sea Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Title Transfer (certificate of inspection, sale or transfer)$t$, $j$["Issued by: Borough of Avon-by-the-Sea Fire Bureau / housing inspection (Code Enforcement)","Contact: Paul Murphy, House inspection (Fire Bureau); listed as Fire Official Paul A Murphy, Jr in the state directory · (732) 502-4518 · firebureau@avonbytheseanj.com","Apply: Apply at least 14 days ahead; requests under 14 days may be charged an additional fee.","How to apply: Pick up the Certificate of Occupancy & Transfer of Title application and the smoke/CO compliance application at the Borough Municipal Building, 301 Main Street (8:30 am to 4:30 pm), fill out both, and drop off or mail them with a check for the right amount; the inspection is then scheduled. Questions: firebureau@avonbytheseanj.com.","Housing inspection by the Fire Bureau; no Certificate of Occupancy is issued while any violations remain","Both the Certificate of Occupancy and Transfer of Title application and the smoke detector / carbon monoxide alarm compliance application must be submitted","Smoke detectors (10-year sealed if not hard wired) and carbon monoxide detector","Outside conditions such as porches, landings, sidewalks and driveway may need repair before the certificate is issued"]$j$::jsonb, $j$[{"label":"Certificate of inspection, sale or transfer, one family dwelling (Code 88-4)","amount":"$75.00"},{"label":"Certificate of inspection, sale or transfer, multifamily or apartments (Code 88-4)","amount":"$90.00"},{"label":"Reinspection if necessary (Code 88-4)","amount":"$25.00"}]$j$::jsonb, null, $t$https://www.avonbytheseanj.com/departments/code_enforcement/code_fire_marshal.php$t$, $j$[{"url":"https://www.avonbytheseanj.com/departments/code_enforcement/code_fire_marshal.php","label":"Official source (avonbytheseanj.com)"},{"url":"https://ecode360.com/35035920","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Housing License - Title Transfer - Yearly Rentals - Winter/Summer Rentals$t$, $t$53bea30ff6bf8e086d2401925be74609c436ea8a4fd9913e76925522de564ed3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":3,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1306.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1306.json$t$, true),
  ($t$1306$t$, $t$Avon-by-the-Sea Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Avon-by-the-Sea Fire Bureau (Borough fire official) (town fire bureau)","Contact: Paul A Murphy, Jr, Fire Official, per state directory · (732) 502-4518 · firebureau@avonbytheseanj.com","Apply: Fee depends on business days before the change of occupant. The office asks for at least 14 days for inspections.","How to apply: Submit the Certificate of Smoke Detector Carbon Monoxide Alarm Compliance application together with the C of O / Transfer of Title application at the Borough Municipal Building, 301 Main Street, with a check. Questions: firebureau@avonbytheseanj.com.","Fire official in the NJ state directory, updated 2/6/2026: Paul A Murphy, Jr · (732) 502-4518 · firebureau@avonbytheseanj.com","Smoke detectors required; 10-year sealed detectors if not hard wired","Carbon monoxide detector","Fire extinguisher on all sales and rentals: 5 to 10 lb ABC, on the manufacturer's bracket, within 10 feet of the kitchen, top no higher than 5 feet, near an exit path, with the manual and instructions visible (page still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSDCMAC), more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Four to 10 business days before","amount":"$90.00"},{"label":"Fewer than four business days before","amount":"$161.00"},{"label":"Smoke detector and CO inspection, R-3 dwellings, more than 10 business days (Code 100-8C)","amount":"$45"},{"label":"Four to 10 business days (Code 100-8C)","amount":"$90"},{"label":"Fewer than four business days (Code 100-8C)","amount":"$161"}]$j$::jsonb, null, $t$https://www.avonbytheseanj.com/departments/code_enforcement/code_fire_marshal.php$t$, $j$[{"url":"https://www.avonbytheseanj.com/departments/code_enforcement/code_fire_marshal.php","label":"Official source (avonbytheseanj.com)"},{"url":"https://ecode360.com/35036177","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Also, the sale or rental of any housing unit without a Smoke Defector or Carbon Monoxide Compliance Certificate is punishable by a $500.00 fine, according to the NJ Uniform Fire Code.$t$, $t$89a5ff4d2bbd344c506755478a295313a7b49972fc1005d7335b48fdf7a5142e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":3,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1306.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1306.json$t$, true),
  ($t$1307$t$, $t$Belmar Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection for Title Transfer (property sale inspection)$t$, $j$["Issued by: Borough of Belmar Housing Department (Code Official)","Contact: Ray Claudio, Housing Official · 732-681-3700 ext. 242 · Housing@Belmar.com","How to apply: Apply online through the SDL Portal (Belmar, Property Inspection: Rental Licenses & Property Sales application). Create an account with Sign Up, choose Belmar as the primary town, then file the Title Transfer request and track it online.","Certificate of Inspection from the Code Official before anyone occupies the home after a sale or other transfer of title","Inspection checklist covers exterior items (grading and drainage, sidewalks free of trip hazards, window screens, handrails, guardrail gaps no more than 5 inches, sump pumps, siding and roof, house numbers 4 inches and visible, labeled trash and recycling cans) and interior items","Smoke and carbon monoxide detectors on each floor, 10-year sealed","Kitchen stoves must be tip proof; dryers vented outside; bedroom egress windows at least 24 x 20 with sill no higher than 44 inches","Living space above a garage needs at least 5/8 inch fire code sheetrock on the ceiling"]$j$::jsonb, $j$[{"label":"Certificate of Inspection for title transfer, one family (Code 26-5d)","amount":"$100"},{"label":"Each additional house on the same property (Code 26-5d)","amount":"$50"},{"label":"Title transfer, two family, first unit (Code 26-5d)","amount":"$100"},{"label":"Each additional unit in the same building (Code 26-5d)","amount":"$50"},{"label":"Re-inspection (Housing Department checklist)","amount":"$250"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/belmar/requests/certificate$t$, $t$https://www.belmar.com/departments/community-development/housing/property-inspection-rental-sales$t$, $j$[{"url":"https://www.belmar.com/departments/community-development/housing/property-inspection-rental-sales","label":"Official source (belmar.com)"},{"url":"https://www.belmar.com/departments/community-development/housing","label":"Official source (belmar.com)"},{"url":"https://ecode360.com/35397304","label":"Official source (ecode360.com)"},{"url":"https://www.belmar.com/government/forms/housing/920-inspection-checklist/file","label":"Official source (belmar.com)"},{"url":"https://ecode360.com/35397458","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Please click the link below to file for a Winter, Annual or Summer Rental License as well as a Title Transfer for property sales.$t$, $t$457329fa54939df9914d6009c064f38aa635982269e9a9e609a1ea6fb120224b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":1,"fee_bad":0,"fee_unchecked":4,"quotes":12,"q_ok":8,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1307.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1307.json$t$, true),
  ($t$1307$t$, $t$Belmar Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Belmar Bureau of Fire Prevention (Fire Marshal) (town fire bureau)","Contact: Edward Ratyniak, Fire Marshal · 732-681-3700 x 239 · firemarshal@belmar.com","How to apply: No smoke/CO certificate application or fee schedule was found on the Borough site. Contact the Fire Marshal at 732-681-3700 x 239 or firemarshal@belmar.com, or ask the Housing Department whether the smoke/CO check is part of the title transfer inspection.","Fire official in the NJ state directory (town), updated 3/31/2025: Edward Ratyniak · (732) 681-3700 · firemarshal@belmar.com","Smoke and carbon monoxide detectors on each floor, 10-year sealed (Housing inspection checklist)","Smoke detectors on each floor and the basement; carbon monoxide detectors in homes with fuel-burning appliances or an attached garage (Borough Code 28-1.13.2)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.belmar.com/departments/fire-prevention$t$, $j$[{"url":"https://www.belmar.com/departments/fire-prevention","label":"Official source (belmar.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Edward Ratyniak$t$, $t$77f92a4d0aea558f1b908a815f94dafa6864d25b1e27c720866f4b130b4411b9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":1,"fee_bad":0,"fee_unchecked":4,"quotes":12,"q_ok":8,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1307.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1307.json$t$, true),
  ($t$1308$t$, $t$Bradley Beach Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) / certificate of inspection$t$, $j$["Issued by: Borough of Bradley Beach Office of Code Enforcement (Department of Community Development)","Contact: Bill Young, Code Enforcement Officer (wyoung@bradleybeachnj.gov, ext. 1034) · 732-776-2999 ext. 1033 · code@bradleybeachnj.gov","Apply: Apply more than 10 days before closing to avoid late surcharges. Inspection windows on the form are 10-12 and 12-2.","How to apply: Fill out the Borough's CCO application (choose SALE and give the closing date and buyer details), attach the heating system and water heater certification, and submit it with the fee to the Office of Code Enforcement, 701 Main Street, Bradley Beach. The Code Enforcement Officer then inspects; if minor violations remain, a temporary certificate may be issued with a letter of intent to fix them within 20 days.","Inspection of the home by the Code Enforcement Officer for compliance with Borough ordinances and the property maintenance code (CCO inspection checklist)","Smoke alarms, carbon monoxide alarms and a 2A:10BC fire extinguisher are checked as part of the CCO inspection (checklist revised October 2022; the state dropped the extinguisher from the sale requirement in February 2025, but the form still lists it)","Heating system and water heater certification by a qualified technician (form included with the CCO application packet)","Application must list the buyer and the closing date and be signed by both the owner/agent and the buyer","Occupancy is not permitted until the certificate is issued","Also: Heating system and water heater certification: A qualified technician must certify the heating system and water heater on the Borough form that comes with the CCO application."]$j$::jsonb, $j$[{"label":"Certificate of inspection (CCO), sale or transfer of a single-family home","amount":"$100"},{"label":"Certificate of inspection (CCO), sale or transfer of a two-family home or single-family home with an accessory unit","amount":"$150"},{"label":"Reinspection, per unit","amount":"$50"},{"label":"Late application surcharge, application made 10 to 5 days before the sale (added to the base fee)","amount":"$50"},{"label":"Late application surcharge, application made 4 days or less before the sale (added to the base fee)","amount":"$75"}]$j$::jsonb, $t$https://www.bradleybeachnj.gov/wp-content/uploads/2023/04/CCO-APPLICATION-1022.pdf$t$, $t$https://www.bradleybeachnj.gov/community-development/$t$, $j$[{"url":"https://ecode360.com/7043039","label":"Official source (ecode360.com)"},{"url":"https://www.bradleybeachnj.gov/wp-content/uploads/2023/04/CCO-APPLICATION-1022.pdf","label":"Official source (bradleybeachnj.gov)"},{"url":"https://www.bradleybeachnj.gov/community-development/","label":"Official source (bradleybeachnj.gov)"}]$j$::jsonb, $t$unless such person first obtains from the Code Enforcement Officer of the Borough a certificate of occupancy and permit authorizing any of the foregoing and when any of the foregoing shall take place.$t$, $t$2d20f1e564849cf5dd7bfa0e9fe39144b20994d3637c14afaac116e61052a845$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1308.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1308.json$t$, true),
  ($t$1308$t$, $t$Bradley Beach Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bradley Beach Office of Code Enforcement / Fire Marshal (Department of Community Development), checked during the CCO inspection (town fire bureau)","Contact: Jeffrey Spengler, Fire Marshal · 732-776-2999 · firemarshal@bradleybeachnj.gov","Apply: Handled with the CCO inspection; no separate smoke certificate schedule is published.","How to apply: The smoke alarm, carbon monoxide alarm and extinguisher items are inspected as part of the Borough CCO inspection (see resale certificate). No separate smoke/CO certificate application or fee was found online; call the office to confirm whether a separate certificate or fee applies.","Fire official in the NJ state directory (town), updated n/a: Jeffrey Spengler · (732) 776-2999 · firemarshal@bradleybeachnj.gov","Smoke alarms on each level and outside each sleeping area; homes built before 1977 need 10-year sealed battery alarms, newer homes keep their hardwired (and interconnected, where built that way) alarms","Carbon monoxide alarms near all sleeping areas on all floors if the home has fuel-burning appliances or an attached garage","Fire extinguisher, type 2A:10BC, mounted within 10 feet of the kitchen, not higher than 5 feet (still listed on the Borough checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.bradleybeachnj.gov/wp-content/uploads/2023/04/CCO-APPLICATION-1022.pdf$t$, $t$https://www.bradleybeachnj.gov/community-development/$t$, $j$[{"url":"https://www.bradleybeachnj.gov/wp-content/uploads/2022/10/CCO-CHECKLIST-1022.pdf","label":"Official source (bradleybeachnj.gov)"},{"url":"https://www.bradleybeachnj.gov/community-development/","label":"Official source (bradleybeachnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$10 year sealed battery operated smoke detectors are installed on each level of the structure and outside each sleeping area in the immediate vicinity of the bedrooms.$t$, $t$f5878360848086d556ece61d98ff0aae7febcf0bd455863e2ccc8ea055f141fd$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1308.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1308.json$t$, true),
  ($t$1309$t$, $t$Brielle Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Continued Occupancy (Certificate for Sale or Rental)$t$, $j$["Issued by: Borough of Brielle (Code Enforcement Officer; Construction Code Official under the Housing Ordinance)","Contact: Christopher Willms, Code Enforcement Officer (also Fire Inspector for the Sea Girt Fire Bureau) · 732-528-6600 ext. 5119 · cwillms@briellenj.gov","Apply: The certificate must be granted or denied within 10 days of the application; file 10 or more days before occupancy for the lowest fee.","How to apply: Apply online with the Borough's 'Certificate for Sale or Rental' GovPilot application (listed on the Borough Forms page), choosing Sale and giving the closing/occupancy date, then pay the fee. Review the Certificate for Sales and Rentals checklist before the inspection.","Inspection of the whole property against the Borough's Certificate for Sales and Rentals checklist (exterior, interior, bedroom size and egress)","Smoke alarms tested by push button; 10-year sealed battery alarms; detectors over 10 years old are not accepted; hardwired, interconnected alarms in newer homes","Carbon monoxide alarms outside each sleeping area where there are fuel-burning appliances or an attached garage; not older than 5 years or past the maker's expiration date","Fire extinguisher, minimum 2A:10B:C, permanently mounted within 10 feet of the kitchen and serviced/tagged in the past 12 months or newly bought (form still lists it)","Monitored alarm systems need an affidavit that the system is maintained and works","Owner certifies the home meets zoning and no rubbish, debris or bulk garbage will be left before the new occupancy","Application lists the closing/occupancy date, owners, any mortgage holders, and any deck, fence, shed, pool, garage or finished basement","Also: Final water/sewer meter reading: Request a final meter reading from the Water & Sewer Department at least 24 hours before closing; a $65.00 reading fee is added to the bill (another $65.00 if the closing date changes after the bill is done). Call Tara at 732-449-6463 or email tvermillion@seagirtboro.com."]$j$::jsonb, $j$[{"label":"Certificate of occupancy (sale or rental), application filed 10 or more days before occupancy","amount":"$100"},{"label":"Application filed less than 10 and more than 5 days before occupancy","amount":"$150"},{"label":"Application filed less than 5 and more than 2 days before occupancy","amount":"$200"},{"label":"Application filed less than 2 days before occupancy","amount":"$250"},{"label":"Reinspection, each request","amount":"$50"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/60392c47-4a7_CCO-Application-brielle?uid=7223&ust=NJ&pu=1&id=0$t$, $t$https://www.briellenj.gov/285/Forms$t$, $j$[{"url":"https://ecode360.com/36069533","label":"Official source (ecode360.com)"},{"url":"https://main.govpilot.com/web/public/60392c47-4a7_CCO-Application-brielle?uid=7223&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.briellenj.gov/DocumentCenter/View/777/Certificate-for-Sale-and-Rental-Guidelines-PDF","label":"Official source (briellenj.gov)"},{"url":"https://www.briellenj.gov/285/Forms","label":"Official source (briellenj.gov)"},{"url":"https://www.briellenj.gov/Directory.aspx","label":"Official source (briellenj.gov)"}]$j$::jsonb, $t$unless a certificate of occupancy certifying that the building and premises are in compliance with all applicable ordinances of the Borough shall first be obtained from the Borough.$t$, $t$6ed744b68a5d54ba58016bb34fbaf11ef93b0ebce9b65e73564d994f2e8eb05c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1309.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1309.json$t$, true),
  ($t$1309$t$, $t$Brielle Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Sea Girt Fire Bureau (local enforcing agency for Brielle under a shared service); smoke/CO items are inspected with the Brielle Certificate for Sale (town fire bureau)","Contact: Christopher Willms, Fire Inspector, Sea Girt Fire Bureau (also Brielle Code Enforcement Officer) · 732-449-9433 ext. 118 · cwillms@briellenj.gov","Apply: Handled with the Borough sale certificate inspection; no separate schedule published.","How to apply: The smoke alarm, CO alarm and extinguisher requirements are acknowledged and inspected through Brielle's Certificate for Sale or Rental application (GovPilot). No separate smoke certificate form or fee for Brielle was found online; call the Fire Inspector to confirm.","Fire official in the NJ state directory, updated 2/6/2026: Christopher Willms · (732) 449-9433 · cwillms@seagirtboro.com","Smoke alarms on each level per the year built (battery minimum before 1978; hardwired with battery backup later; interconnected and in each bedroom for 1991 and newer); battery alarms must be 10-year sealed","Carbon monoxide alarms outside each sleeping area where there are fuel-burning appliances or an attached garage","Fire extinguisher, minimum 2A:10B:C, mounted within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://main.govpilot.com/web/public/60392c47-4a7_CCO-Application-brielle?uid=7223&ust=NJ&pu=1&id=0$t$, $t$https://www.seagirt-nj.gov/fire-bureau$t$, $j$[{"url":"https://www.seagirt-nj.gov/fire-bureau","label":"Official source (seagirt-nj.gov)"},{"url":"https://ecode360.com/36069533","label":"Official source (ecode360.com)"},{"url":"https://main.govpilot.com/web/public/60392c47-4a7_CCO-Application-brielle?uid=7223&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Welcome to the Sea Girt Fire Bureau, serving the communities of Sea Girt, NJ and Brielle, NJ.$t$, $t$dcd273a2ced5f6d86021c45d30597fe4d37afaf14e79714c2458d43b5253e138$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1309.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1309.json$t$, true),
  ($t$1311$t$, $t$Deal Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Inspection / Certificate of Occupancy (Real Property Transfer Permit)$t$, $j$["Issued by: Borough of Deal Code Enforcement (Building Department / Construction Official)","Contact: (732) 531-1454 · Building@dealborough.com","Apply: Inspectors are part-time and inspection space is limited; plan ahead. Under the code, the permit is issued or denied within 10 days of a complete application and inspection.","How to apply: Fill out the Borough's Rental/Resale Certificate of Inspection & Fire Safety Application (check Resale), with the buyer and occupant information, and deliver it with the certificate fee and the smoke/CO fee (checks payable to the Borough of Deal) to Code Enforcement, 190 Norwood Ave. Faxed or emailed applications are not accepted. If title will transfer before the home is ready to occupy, a separate Transfer of Ownership (title only) application with a notarized buyer affidavit is available.","Valid for: A temporary transfer permit may be issued for up to 90 days","Complete Rental/Resale Certificate of Inspection & Fire Safety application with all buyer and occupant names and ages","All construction permits and violations must be closed out","All taxes must be paid up to date","Estates must provide executor documentation; corporations must provide formation documents","Exterior and interior inspection checklist (paint, street numbers, foundation, windows and screens, handrails, sidewalks and stairs, GFCI outlets, gutters, debris, cleanliness, no infestation)","Oil tanks not in use must be removed or filled under the Uniform Construction Code (demolition permit required)","Smoke and carbon monoxide inspection is required with every code enforcement inspection (separate fire fee)","First reinspection is free; there is a fee for the second; missing the inspection is an automatic failure","Also: Open permits and taxes: All construction permits and violations must be closed and all taxes paid before the certificate is issued.","Also: Unused oil tanks: Oil tanks not in use must be removed or filled under the Uniform Construction Code (demolition permit required).","Also: Sidewalks, driveway aprons and curbs: The transfer permit inspection requires sidewalks, driveway aprons and curbs to be in good repair and safe."]$j$::jsonb, $j$[{"label":"Resale certificate of inspection, single and two family homes","amount":"$200"},{"label":"Certification fee, single and two family homes (Borough Code §11-3.5b)","amount":"$200"},{"label":"Transfer of Ownership/Title only application (no occupancy allowed until a CO is issued)","amount":"$65.00"}]$j$::jsonb, $t$https://dealnj.gov/wp-content/uploads/2025/07/Rental-Resale-Certificate-Inspection-Application-2025.pdf$t$, $t$https://dealnj.gov/departments/building/$t$, $j$[{"url":"https://dealnj.gov/wp-content/uploads/2025/07/Rental-Resale-Certificate-Inspection-Application-2025.pdf","label":"Official source (dealnj.gov)"},{"url":"https://ecode360.com/49109216","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/49108720","label":"Official source (ecode360.com)"},{"url":"https://dealnj.gov/wp-content/uploads/2025/04/Transfer-of-Ownership-Application.pdf","label":"Official source (dealnj.gov)"},{"url":"https://dealnj.gov/departments/building/","label":"Official source (dealnj.gov)"}]$j$::jsonb, $t$RENTAL / RESALE CERTIFICATE OF INSPECTION & FIRE SAFETY APPLICATION$t$, $t$cd5fc9bd85e2068a5438e336ed82604a33ec90675168f723ee6cbf84e57af6a4$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":5,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1311.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1311.json$t$, true),
  ($t$1311$t$, $t$Deal Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Deal Code Enforcement / Deal Borough Fire Prevention (fee collected with the resale application) (town fire bureau)","Contact: Nicholas Simons, Fire Official (per NJ DCA fire directory) · (732) 531-1454 · nsimons@dealborough.com","Apply: Fee depends on how many days before the occupancy change the request is made: more than 10 days for the lowest fee.","How to apply: Pay the smoke and carbon monoxide fee on the same Rental/Resale Certificate of Inspection & Fire Safety Application as the resale certificate; checks payable to the Borough of Deal. Fire inspections are booked by email with the Building Department (Tuesdays and Wednesdays, 11:00 am to 1:30 pm).","Fire official in the NJ state directory (town), updated 7/1/2026: Nicholas Simons · (732) 567-8254 · nsimons@dealborough.com","10-year sealed battery smoke detectors on each level, including basements (not attic or crawl space), and outside each separate sleeping area","Homes built after 1977 with AC powered and/or interconnected detectors must keep them in working order","Carbon monoxide detector in the common area of any floor with a bedroom or garage","All detectors in working order","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide inspection, more than 10 days before the occupancy change","amount":"$45"},{"label":"Smoke and carbon monoxide inspection, 4 to 10 days before the occupancy change","amount":"$90"},{"label":"Smoke and carbon monoxide inspection, less than 4 days before the occupancy change","amount":"$161"}]$j$::jsonb, $t$https://dealnj.gov/wp-content/uploads/2025/07/Rental-Resale-Certificate-Inspection-Application-2025.pdf$t$, $t$https://dealnj.gov/departments/building/$t$, $j$[{"url":"https://dealnj.gov/wp-content/uploads/2025/07/Rental-Resale-Certificate-Inspection-Application-2025.pdf","label":"Official source (dealnj.gov)"},{"url":"https://ecode360.com/49108720","label":"Official source (ecode360.com)"},{"url":"https://dealnj.gov/departments/building/","label":"Official source (dealnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PLEASE NOTE ALL CODE ENFORCEMENT INSPECTIONS ARE REQUIRED TO HAVE A SMOKE & CARBON INSPECTION INCLUDING ALL MULTIPLE DWELLINGS$t$, $t$50c87a3b5defa177f0e3d8d463fe33aebb2de02104a06d5a354c739bc0229ef9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":5,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1311.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1311.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Continued Use (combined certificate of smoke alarm, carbon monoxide alarm and compliance, CSDCMAC)$t$, $j$["Issued by: Borough of Eatontown inspector (Housing Official, Code Enforcement Officer, Fire Marshal or Fire Inspector)","Contact: Nicholas Cosentino, Housing Official · 732-389-7616 · housing@eatontownnj.com","Apply: Fees rise when the request is made 10 or fewer business days before the change of occupancy. All fees are paid with the application before any inspection.","How to apply: Apply in writing to the Borough inspector (Housing Division, 47 Broad Street) with the buyer's information and pay the fee with the application. The inspector issues the certificate if no violations exist; otherwise the owner is told in writing what must be fixed. No online application form was found on the Borough website.","Valid for: 60 days (Code §116-6B); the code also says CSDCMAC inspections are valid for six months","Inspection for fitness for habitation under Borough Code §116-8 before the home is sold","Any outstanding permit issues must be closed; Zoning Officer certifies compliance","Smoke detectors on each level and within 10 feet of sleeping quarters, working and under 10 years old; 10-year sealed battery units; AC powered units cannot be swapped for battery units","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","Monitored fire alarm systems must be made available for testing, with a certificate of inspection","Checklist items include working doors and keyless deadbolts, GFCI in bathrooms, covered electrical boxes and plates, 4-inch house numbers, handrails on stairs over four risers, unbroken operable windows, safe sidewalk/driveway/apron/foundation, heating system and flue, water heater overflow pipe, metal dryer vent, minimum 60 amp service, sump pump on a dedicated receptacle","Application states the future owner's name and address and who will allow entry","Also: Open permits and zoning: Outstanding permit issues must be closed and the Zoning Officer must certify compliance before the certificate is issued."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"},{"label":"Transfer of residential properties (lawful two-family homes charged separately)","amount":"$200"},{"label":"Buyer backs out and a new buyer purchases before occupancy (updated application)","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/Directory.aspx$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/Directory.aspx","label":"Official source (eatontownnj.com)"}]$j$::jsonb, $t$Eatontown Borough shall perform inspections in accordance with the New Jersey Uniform Fire Code before any one- and two-family or attached single-family structure is sold, leased, or otherwise made subject to a change of occupancy for residential purposes.$t$, $t$ea7b674fa53da0559bee4ad6b29e6c25aca340262c9bce98e7c9784893d6bdf1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Eatontown Housing Division and Bureau of Fire Safety (combined certificate of occupancy and CSDCMAC) (town fire bureau)","Contact: Patrick A. Renaldi, Fire Marshal · 732-389-7620 · prenaldi@eatontownnj.com","Apply: Combined with the certificate of occupancy inspection; fee depends on business days before the change of occupancy.","How to apply: The smoke/CO certificate is not applied for separately: Eatontown issues one combined certificate after its habitability inspection (see resale certificate).","Fire official in the NJ state directory, updated 10/2/2024: Patrick Renaldi · (732) 389-7621 · prenaldi@eatontownnj.com","Smoke detectors on each level and within 10 feet of sleeping quarters, working and less than 10 years old","10-year sealed battery single station smoke alarms (ANSI/UL 217); AC powered alarms from original construction or rehabilitation stay AC powered","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","No fire extinguisher for owner sales; the code lists extinguishers for rental and apartment units only","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/194/Bureau-of-Fire-Safety$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/194/Bureau-of-Fire-Safety","label":"Official source (eatontownnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$To protect the health, safety, and wellness of all residents and first responders, the owner shall obtain a combined certificate of smoke alarm, carbon monoxide alarm, and compliance.$t$, $t$7ea2a858b63a558095796221e4aec80a61631eb45bb1a650e21afeccbc00b4eb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1313$t$, $t$Englishtown Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Englishtown Department of Code Enforcement (Housing Inspector)","Contact: Robert Cusic, Housing Inspector · (732) 446-9235","Apply: Apply in reasonable time before closing; the certificate is granted or denied within 10 days of the application.","How to apply: Fill out the Borough CCO Application (choose Resale), enclose the $100.00 fee with a check payable to the Borough of Englishtown, and submit it to Borough Hall, 15 Main Street. Schedule the CCO inspection with the Housing Inspector, then apply separately to the Fire District for the smoke/CO certificate.","Valid for: 90 days after issuance; one 90-day extension may be applied for","Inspection by the Borough Housing Inspector for compliance with Borough housing and property maintenance ordinances","Application lists the owner, block and lot, approximate closing date, type of occupancy (single family, apartment, condo/townhouse) and reason (resale)","Separate smoke and carbon monoxide certificate from the Englishtown Fire District No. 1 Bureau of Fire Prevention (apply after scheduling the CCO inspection)"]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy (CCO), all dwelling units","amount":"$100"},{"label":"CCO application fee, as printed on the Borough form","amount":"$100.00"},{"label":"Extension of a CCO for another 90 days","amount":"$50"}]$j$::jsonb, $t$https://www.englishtownnj.com/s/UPDATED-CCO-Application.pdf$t$, $t$https://www.englishtownnj.com/forms-and-applications$t$, $j$[{"url":"https://ecode360.com/42149011","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/42147516","label":"Official source (ecode360.com)"},{"url":"https://www.englishtownnj.com/s/UPDATED-CCO-Application.pdf","label":"Official source (englishtownnj.com)"},{"url":"https://englishtownbofc.com/docs/Fire%20Bureau/BOE_Fire_Bur_CSACMAPFEC_2026.pdf","label":"Official source (englishtownbofc.com)"},{"url":"https://www.englishtownnj.com/forms-and-applications","label":"Official source (englishtownnj.com)"}]$j$::jsonb, $t$No owner of any dwelling or dwelling unit shall rent, sell, renew the lease of, or otherwise permit occupancy of same or any part thereof by any person not a member of his/her family unless he/she shall first obtain a certificate of continued occupancy from the Department of Code Enforcement of the Borough of Englishtown.$t$, $t$2df9494ef62fd7a0415ad24d9afee5fc3a65096af7b89032dad539b7089a388c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":3,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1313.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1313.json$t$, true),
  ($t$1313$t$, $t$Englishtown Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Englishtown Fire District No. 1, Bureau of Fire Prevention (fire district)","Contact: Ken Marr, Jr., Fire Marshal · 732-786-4477 · firemarshal@englishtownfd.com","Apply: Fee depends on business days before closing. Inspections are noon to 3 pm Tuesday to Thursday and are not done at the same time as the CCO inspection.","How to apply: After applying for the CCO and scheduling that inspection, complete the Fire District's Application for Certificate of Smoke Detector & Carbon Monoxide Compliance (at Town Hall, on the Borough Forms page, or at englishtownbofc.com) and drop it with payment at the firehouse, 3 S. Main St. (secure red drop box at the back). Pay by check or money order to Englishtown Fire Prevention, not the Borough, or exact cash. Office hours Tuesday to Thursday, noon to 4 pm.","Fire official in the NJ state directory (fire district), updated 7/13/2026: Ken Marr, Jr · (732) 446-9235 · firemarshal@englishtownfd.com","Ten-year sealed battery single station smoke alarms or AC powered hardwired smoke detectors: one in each bedroom, and one on each level within ten feet of the bedrooms (not crawl spaces or unfinished attics)","Smoke detectors properly mounted, UL listed, with a test button; AC powered alarms from original construction or rehabilitation cannot be replaced with battery alarms","Carbon monoxide alarm on each level and within ten feet of the bedrooms (battery, plug-in, or part of a central station alarm system); UL listed","Central station alarm systems need a letter from the monitoring company that the system works","No fire extinguisher required (the Fire District FAQ cites the February 2025 change)","An adult must be present; pets secured","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and CO certificate, received more than 10 business days before closing","amount":"$45.00"},{"label":"Received 4 to 10 business days before closing","amount":"$80.00"},{"label":"Received less than 4 business days before closing","amount":"$135.00"}]$j$::jsonb, $t$https://englishtownbofc.com/docs/Fire%20Bureau/BOE_Fire_Bur_CSACMAPFEC_2026.pdf$t$, $t$https://englishtownbofc.com/inspection-requirements$t$, $j$[{"url":"https://englishtownbofc.com/docs/Fire%20Bureau/BOE_Fire_Bur_CSACMAPFEC_2026.pdf","label":"Official source (englishtownbofc.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The owner shall obtain a certificate of compliance from the Englishtown Fire District No.1, Bureau of Fire Prevention$t$, $t$4699d6c7b7b5ff1fb17f2c1507b62d794de6a6adc6c61808417a508cb8ec6a50$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":3,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1313.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1313.json$t$, true),
  ($t$1316$t$, $t$Freehold Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Freehold Borough Code Enforcement Office","Contact: Julissa Gelpi, Director of Code Enforcement · 732-462-5812","Apply: Standard inspections are scheduled by the office; an expedited inspection (3 days or less) costs a $100 surcharge, pending availability.","How to apply: Fill out the Application for Residential Certificate of Continued Occupancy and Smoke Detector Certificate (one combined Borough packet), give the tentative closing date, and pay by cash, check or money order payable to \"Borough of Freehold\" at the Code Enforcement Office, 30 Mechanic Street, Freehold. Include the heating and hot water heater certification from a licensed contractor. An adult must be present for the inspection.","Valid for: 90 days from the initial inspection for sales (30 days for rentals)","No open permits (checked on the application)","Exterior: property clean and free of rubbish; grass and bushes trimmed; sidewalks, driveway and driveway apron free of cracks, raised sections and trip hazards; garages, sheds, fences, retaining walls and pools sound","Exterior structure weathertight with no peeling paint or rotting boards; chimney caps on fireplace chimneys; handrails on 4 or more risers and guardrails over 30 inches; house numbers at least 4 inches tall","Windows open, stay open and have screens; exit doors and windows open without a key or tool","Interior surfaces clean and sound; bathrooms without windows need mechanical ventilation; tubs and showers need shower rods","Plumbing working with hot water able to reach 110 degrees F","Electrical: required outlets and light fixtures; GFI outlets in bathrooms, laundry rooms and within 6 feet of a sink","Dryer transition duct must be a single listed UL 2158A duct, 8 feet or less, not concealed","Heating and Hot Water Heater Certification signed by a licensed plumber or certified heating contractor; heat able to keep 68 degrees F","Chimney certification for all fireplaces","For homes built before 1978: a lead Certification of Clearance from the Freehold Area Health Department before the CCO is issued (see other items)","Also: Lead Certification of Clearance (homes built before 1978): Under Freehold Borough Ordinance 8.56.285, owners of homes built before 1978 that are changing ownership or occupancy must get a certification of clearance from the Freehold Area Health Department (1 Municipal Plaza, 732-294-2060) before the CCO is issued. The Health Department's certified inspectors inspect free of charge on Tuesdays and Thursdays, 9 am to 12 pm, or a NJ licensed private lead inspector may be used; lead-free documentation is also accepted.","Also: Heating and hot water heater certification: A licensed plumber or certified heating contractor must fill out the Borough's Heating System and Hot Water Heater Certification for the CCO; fireplaces need a chimney certification.","Also: Sidewalks and driveway aprons: The CCO checklist requires sidewalks, driveways and driveway aprons to be free of cracks, raised sections or trip hazards; the Borough posts a separate sidewalk and apron replacement permit."]$j$::jsonb, $j$[{"label":"CCO inspection, 1 and 2 family dwellings (including condo and townhouse)","amount":"$100"},{"label":"CCO inspection, apartments (multiple dwelling units)","amount":"$75"},{"label":"Expedited CCO inspection (3 days or less), surcharge","amount":"$100"},{"label":"Second and later CCO re-inspections (first re-inspection free)","amount":"$150"}]$j$::jsonb, $t$https://www.freeholdboroughnj.gov/government/forms/forms-documents/department-documents/code-enforcement/799-residential-cco-application-checklist-1/file$t$, $t$https://www.freeholdboroughnj.gov/departments/code$t$, $j$[{"url":"https://www.freeholdboroughnj.gov/government/forms/forms-documents/department-documents/code-enforcement/799-residential-cco-application-checklist-1/file","label":"Official source (freeholdboroughnj.gov)"},{"url":"https://freeholdboroughnj.gov/government/news/307-important-update-from-the-freehold-area-health-department","label":"Official source (freeholdboroughnj.gov)"},{"url":"https://www.freeholdboroughnj.gov/departments/code","label":"Official source (freeholdboroughnj.gov)"}]$j$::jsonb, $t$APPLICATION FOR RESIDENTIAL CERTIFICATE OF CONTINUED OCCUPANCY & SMOKE DETECTOR CERTIFICATE$t$, $t$37c9fc0a7e3cfaa226bdea715c48b75e4430022b3963e37b2781eec9704e09cb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":9,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1316.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1316.json$t$, true),
  ($t$1316$t$, $t$Freehold Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Freehold Borough Fire Bureau (Bureau of Fire Prevention) (town fire bureau)","Contact: Ken Volkmann, Fire Official · 732-462-3626 · kvolkman@freeholdboro.org","Apply: Lowest fee when the request comes in more than 3 business days before the change of occupancy. Allow up to 5 business days from a passed inspection to the certificate. The certificate is valid for 6 months.","How to apply: Fill out the Application for Certificate of Smoke Detector, Carbon Monoxide Alarm, and Secondary Power Source Compliance (part of the Borough's CCO packet) with the closing date and email addresses for the certificate, and submit it to the Freehold Borough Fire Bureau, 30 Mechanic St, Freehold. After a failed inspection the applicant must call to request a new appointment.","Fire official in the NJ state directory (town), updated 7/31/2026: Kenneth Volkman · (732) 462-3626 · kvolkman@freeholdboro.org","Smoke alarms per the date the home was built or renovated (10-year sealed battery alarms on all levels for homes before January 1977, up to hardwired, interconnected alarms with battery backup on all levels and in each bedroom for homes from March 1991); AC-powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarms outside every separate sleeping area","Secondary power source label (\"CAUTION: MULTIPLE SOURCES OF POWER\", not handwritten) within 18 inches of the main electrical panel and electric meter if the home has a generator, solar panels, battery storage or another supplemental source","An adult 18 or older must be present for the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke, CO and secondary power source certificate, request more than 3 business days before the change of occupancy","amount":"$50.00"},{"label":"Request less than 3 business days before the change of occupancy (pending availability)","amount":"$100.00"},{"label":"Second and later re-inspections (first re-inspection free)","amount":"$150"}]$j$::jsonb, $t$https://www.freeholdboroughnj.gov/government/forms/forms-documents/department-documents/code-enforcement/799-residential-cco-application-checklist-1/file$t$, $t$https://www.freeholdboroughnj.gov/departments/fire-prevention$t$, $j$[{"url":"https://www.freeholdboroughnj.gov/government/forms/forms-documents/department-documents/code-enforcement/799-residential-cco-application-checklist-1/file","label":"Official source (freeholdboroughnj.gov)"},{"url":"https://www.freeholdboroughnj.gov/departments/fire-prevention","label":"Official source (freeholdboroughnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Email: kvolkman@freeholdboro.org$t$, $t$43eaa24199d1cfae10791f8dc8db6517538c6c55479c86aed88711fe8f630dc3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":9,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1316.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1316.json$t$, true),
  ($t$1317$t$, $t$Freehold Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (C.C.O.)$t$, $j$["Issued by: Freehold Township Department of Zoning and Housing Enforcement (Housing Department)","Contact: 732-294-2066 · Housing@twp.freehold.nj.us","Apply: The ordinance says the certificate is granted or denied within 10 days of the application. The inspection can be scheduled only after both the CCO and fire applications are submitted with payment.","How to apply: Mail or deliver the CCO application and the Fire application, each with its own check or money order payable to \"Township of Freehold\" (no cash or cards), to the Township of Freehold, Attn: Housing Department, 1 Municipal Plaza (Construction Building), Freehold, NJ 07728. Then call to schedule the joint CCO and fire inspection. Results and the certificate are emailed. If the home cannot pass before closing, the buyer's attorney can request a \"Transfer of Title - No Occupancy\" letter once the fire inspection passes; the buyer may not occupy until the CCO is issued.","Valid for: A CCO issued for a resale is valid up to 120 calendar days from issuance or until a change of occupancy, whichever comes first","Submit the CCO application and the separate Fire (smoke and carbon monoxide) application together, each with its own check or money order","All permits must be closed; work done without construction or zoning permits (water heaters, furnaces, AC, decks, sheds, fences, finished basements) must be permitted and closed before the CCO is issued","Well or septic properties need Health Department approval","All utilities on; house number 6 inches high, visible from the street and contrasting; property in good condition and free of debris","Windows working with no broken seals and with screens; no double-keyed deadbolts or slide bolts on entry doors; interior doors working","Handrails on 4 or more risers; appliances, sinks, tubs, showers and toilets working; bathroom vent fan if no operable window","GFCI outlets within 6 feet of all sinks; outlets, switches and junction boxes covered","Solid core wood or steel, 20-minute rated door from an attached garage; garage door opener and sump pump on their own outlets (no extension cords)","Metal dryer vent; washer discharges into drainage; sump pump discharges outside, not into the sewer","Pool gates self-closing and self-latching; pool running or closed","If the home will be rented and was built before 1978, a lead-safe certificate is required (rentals only)","Also: Open permits: All construction permits must be closed, and any work done without construction or zoning permits must be permitted and closed, before the CCO is issued. Check with the Construction Department at 732-294-2050.","Also: Well or septic approval: Homes with a well or septic system need Health Department approval as part of the CCO (Health Department, 732-294-2060).","Also: Transfer of Title - No Occupancy: If the home cannot pass the CCO before closing, the buyer's attorney can submit the Township's sample letter; after the fire inspection passes the Township emails a Transfer of Title - No Occupancy document for closing. The buyer may not occupy until the CCO passes.","Also: Rental registration deactivation: If the home being sold was a registered rental, the landlord registration is deactivated when the sale CCO is processed."]$j$::jsonb, $j$[{"label":"CCO inspection, single family home, townhouse or condominium","amount":"$150.00"},{"label":"CCO inspection, Silvermead and apartments","amount":"$75.00"},{"label":"Each additional inspection date after the two included","amount":"$65.00"},{"label":"Continued certificate of occupancy, single-family homes or condominiums (Code Section 150-62D)","amount":"$150"},{"label":"Residential reinspection after second inspection (Code Section 150-62D)","amount":"$65"}]$j$::jsonb, $t$https://www.twp.freehold.nj.us/DocumentCenter/View/219$t$, $t$https://www.twp.freehold.nj.us/225/Department-of-Zoning-Housing-Enforcement$t$, $j$[{"url":"https://www.twp.freehold.nj.us/226/Forms","label":"Official source (twp.freehold.nj.us)"},{"url":"https://www.twp.freehold.nj.us/225/Department-of-Zoning-Housing-Enforcement","label":"Official source (twp.freehold.nj.us)"},{"url":"https://ecode360.com/9101756","label":"Official source (ecode360.com)"},{"url":"https://www.twp.freehold.nj.us/DocumentCenter/View/220","label":"Official source (twp.freehold.nj.us)"},{"url":"https://www.twp.freehold.nj.us/DocumentCenter/View/227","label":"Official source (twp.freehold.nj.us)"},{"url":"https://www.twp.freehold.nj.us/DocumentCenter/View/219","label":"Official source (twp.freehold.nj.us)"},{"url":"https://ecode360.com/9100866","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate of Continued Occupancy (CCO) inspection and Fire inspection are required when selling or renting a residential property in Freehold Township.$t$, $t$9593e36690f50073222e4cb924010180aea7db950929d27786dbefc786bda117$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":9,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1317.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1317.json$t$, true),
  ($t$1317$t$, $t$Freehold Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Freehold Township Fire Prevention (Department of Fire Prevention); inspections done with the Housing Department CCO inspection (town fire bureau)","Contact: Shaun Reilly, Fire Official (state fire directory: (732) 294-2083, sreilly@twp.freehold.nj.us) · 732-294-2066 · Housing@twp.freehold.nj.us","Apply: Submitted together with the CCO application; inspected at the same appointment. No tiered rush fees are published.","How to apply: Fill out the Fire Application (Smoke-Carbon Monoxide) and submit it with a separate $45.00 check or money order payable to \"Township of Freehold\", together with the CCO application, to the Housing Department, 1 Municipal Plaza, Freehold. Schedule the inspection after both are in.","Fire official in the NJ state directory (town), updated 1/26/2026: Shaun Reilly · (732) 294-2083 · sreilly@twp.freehold.nj.us","Working smoke alarms on every level including the basement, and within 10 feet of all bedrooms","Smoke and CO alarms replaced every 10 years; homes built before 1981 with only battery alarms need 10-year sealed battery units","Carbon monoxide alarm within 10 feet of all bedrooms in the hallway (two if bedrooms are more than 10 feet apart)","Fire extinguisher in the kitchen, 2A-10B:C, 10 lb or less, tagged or newly bought, mounted no higher than 5 feet (form still lists it; the Township checklist now says this applies to apartments in rental complexes only)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, carbon monoxide detector and fire extinguisher certification","amount":"$45.00"}]$j$::jsonb, $t$https://www.twp.freehold.nj.us/DocumentCenter/View/230$t$, $t$https://www.twp.freehold.nj.us/226/Forms$t$, $j$[{"url":"https://www.twp.freehold.nj.us/226/Forms","label":"Official source (twp.freehold.nj.us)"},{"url":"https://www.twp.freehold.nj.us/DocumentCenter/View/230","label":"Official source (twp.freehold.nj.us)"},{"url":"https://www.twp.freehold.nj.us/DocumentCenter/View/227","label":"Official source (twp.freehold.nj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.twp.freehold.nj.us/DocumentCenter/View/219","label":"Official source (twp.freehold.nj.us)"}]$j$::jsonb, $t$Each application requires its own check or money order (no cash or credit/debit cards).$t$, $t$17a25a941b166830a70762a4eac5fbb53b77c87e6c2fbc7a932ba539e2e36911$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":9,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1317.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1317.json$t$, true),
  ($t$1318$t$, $t$Hazlet Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale or Change of Tenancy (Property Resale or Change of Tenancy Certificate)$t$, $j$["Issued by: Hazlet Township Code Inspection Bureau (Code Official / Code Enforcement Office)","Contact: Tim Belicose, Code Enforcement Officer · 732-217-8681","How to apply: Register for the Property Resale or Change of Tenancy Certificate on the Township's SDL Portal (www.sdlportal.com, Hazlet Township), where fees can be paid by credit card or e-check and inspections requested. Get the items in this order: Construction Permit Clearance Release, then the Fire Compliance Certificate from the Bureau of Fire Prevention, then the Certificate of Resale from the Code Official. Fees are paid when the application is filed.","Valid for: Six months from the date of issuance; a renewal or extension costs $35","Step 1: Construction Permit Clearance Release from the Code Enforcement Department confirming there are no open permits; no certificate is issued while any permit is open","Step 2: Fire Compliance Certificate from the Hazlet Township Bureau of Fire Prevention (Hazlet Fire District #1)","Step 3: Certificate of Resale from the Township Code Official after a general visual inspection for unsafe conditions under the Property Maintenance Code (2012 IPMC as adopted)","A temporary certificate may be issued at the Code Official's discretion if there are no apparent life-safety issues","A home in disrepair may be transferred \"as is\" if the buyer requests a title transfer certificate in writing with an affidavit assuming all risk; no occupancy until the Code Official finds no life-safety issues","Also: Construction Permit Clearance Release (no open permits): Required first, before the fire certificate and the certificate of resale. Fee $65 for a single-family home. Any open permits must be documented, inspected and closed through the Construction Department. The fire checklist calls this a Letter of No Interest."]$j$::jsonb, $j$[{"label":"Certificate of resale inspection, single-family","amount":"$100"},{"label":"Certificate of resale inspection, multifamily, per unit","amount":"$75"},{"label":"Residential reinspection (one reinspection is included; each later one)","amount":"$45"},{"label":"Certificate renewal or extension","amount":"$35"},{"label":"Construction permit clearance release, single-family","amount":"$65"},{"label":"Construction permit clearance release, multifamily, per unit","amount":"$65"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/hazlettwp$t$, $t$https://www.hazlettwp.org/864/Resale-of-Property-Change-of-Tenancy$t$, $j$[{"url":"https://www.hazlettwp.org/864/Resale-of-Property-Change-of-Tenancy","label":"Official source (hazlettwp.org)"},{"url":"https://ecode360.com/27991326","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/27991365","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Be advised as of September 1, 2025 Hazlet Township has made new requirements for any resale, change of ownership, change of occupancy, or change of tenancy.$t$, $t$5b29204bc4a3a14f33b8fb129813dacd1132d292cca8212d374be6b845e0ea9a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":2,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1318.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1318.json$t$, true),
  ($t$1318$t$, $t$Hazlet Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hazlet Township Bureau of Fire Prevention (Hazlet Fire District #1) (fire district)","Contact: Thomas Horner, Fire Official (thorner@hazletfiredistrict.org); Michelle Barney, Administrative Clerk, handles applications · 732-264-1427 · mbarney@hazletfiredistrict.org","Apply: Pay online, then request an inspection date within 7 to 10 days of the closing; approval is pending the Bureau's review. Certificates are non-transferable.","How to apply: Apply online only with the Residential Resale - Change of Ownership - Change of Tenant Application (linked from the Fire District site) and pay the fee during the application. Get the Construction Permit Clearance from the Township first. Questions go to the Bureau of Fire Prevention, 812 Poole Ave, Hazlet, 732-264-1427.","Fire official in the NJ state directory (fire district), updated 7/1/2026: Thomas Horner · (732) 264-1700 · thorner@hazletfiredistrict.org","Smoke alarms on every level including the basement near the stairs, within 10 feet of bedrooms, and inside all bedrooms (Hazlet requirement); 10-year sealed battery or interconnected hardwired; hardwired alarms may not be replaced with battery units; all smoke alarms under 10 years old","Carbon monoxide alarms on each level with sleeping areas, within 10 feet of bedrooms; one in the attic if it has a fuel-burning appliance; CO alarms must be under 5 years old","Secondary power source label (\"CAUTION MULTIPLE SOURCES OF POWER\") within 18 inches of the main electrical panel if there is a generator, solar panels, battery storage or other supplemental source","Inspector also checks house numbers (at least 4 inches), exterior cleanliness, utilities on, electrical panel and GFCI outlets, thumb-latch deadbolts, 20-minute garage entry door, window locks, handrails on 4 or more risers, metal dryer hose","A Construction Permit Clearance letter (no open permits) must be on file before the fire certificate is approved","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential fire compliance inspection","amount":"$75.00"},{"label":"Re-inspection","amount":"$25.00"}]$j$::jsonb, $t$https://geo.muniverse.us/prod1/portal/portal.jsp?c=1411754&p=1434734&g=1435286$t$, $t$https://www.hazletfiredistrict1.org/residential-information.html$t$, $j$[{"url":"https://www.hazletfiredistrict1.org/residential-information.html","label":"Official source (hazletfiredistrict1.org)"},{"url":"https://www.hazletfiredistrict1.org/f/Residential_Fire_Compliance_Checklist3.pdf","label":"Official source (hazletfiredistrict1.org)"},{"url":"https://www.hazletfiredistrict1.org/contacts.html","label":"Official source (hazletfiredistrict1.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Fire Compliance is required as per N.J.A.C. 5:70-2.3 for residential dwellings at time of resale, change of tenancy, or change of occupancy.$t$, $t$dcdb16ce8416b5295abe54c567bf50dcf1052c3220d49dc44844cc2c6cf9658e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":2,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1318.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1318.json$t$, true),
  ($t$1319$t$, $t$Highlands Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Inspection (resale)$t$, $j$["Issued by: Borough of Highlands Department of Buildings & Housing (Housing Officer), inspected together with the Fire Prevention Division","Contact: 732-872-1224 ext. 204 · cashier@highlandsnj.gov","Apply: Inspections are not scheduled until payment is received. The combined housing and fire fee is lowest when the inspection is scheduled and paid more than 10 days ahead.","How to apply: Complete the Application for Residential Certificate of Inspection (checking \"Sale of Property\" or \"Transfer of Title\") and email it to the Cashier at cashier@highlandsnj.gov. Pay by check in person or by mail to Borough Hall, 151 Navesink Avenue, Highlands, NJ 07732 (one combined payment covers housing and fire). Then call the Housing Secretary at 732-872-1224 ext. 204 to schedule, and give access to the property.","Before the inspection is scheduled, the Cashier checks with the Tax Search Officer that taxes and sewer fees are current, with the Technical Assistant for open construction (UCC) permits or violations, and with the Code Enforcement Officer for violations","Open permits or violations must be inspected and closed before the housing and fire inspections are scheduled; flood-plain homes are checked for substantial improvement","Housing inspection to the Borough's Property Maintenance Code (exterior property, sidewalks and driveways, exterior structure and paint, roofs, stairs, decks, handrails, windows that open and have screens, doors and locks, interior surfaces, plumbing, heating, electrical)","Smoke/carbon monoxide inspection by the Fire Prevention Division at the same time (see fire certificate)","Also: Taxes and sewer fees current: Before scheduling the inspection, the Cashier confirms with the Tax Search Officer that property taxes and sewer fees are current.","Also: Open permits and violations: Open construction permits or code violations must be inspected and closed before the housing and fire inspections are scheduled; homes in the flood plain are checked for substantial improvement."]$j$::jsonb, $j$[{"label":"Certificate of inspection for resale, with one inspection","amount":"$100"},{"label":"Each added reinspection","amount":"$50"},{"label":"Combined housing and fire inspection, scheduled and paid more than 10 days ahead","amount":"$145"},{"label":"Combined expedited inspection, 4 to 9 days ahead","amount":"$190"},{"label":"Combined expedited inspection, 1 to 3 days ahead (Borough web page figure)","amount":"$261"},{"label":"Combined expedited inspection, 1 to 3 days ahead (application form figure)","amount":"$225"}]$j$::jsonb, $t$https://highlandsnj.gov/wp-content/uploads/2024/10/Residential-Certificate-of-Inspection-Application-1.pdf$t$, $t$https://highlandsnj.gov/departments/housing-inspections-and-enforcement/$t$, $j$[{"url":"https://highlandsnj.gov/departments/housing-inspections-and-enforcement/","label":"Official source (highlandsnj.gov)"},{"url":"https://ecode360.com/35386169","label":"Official source (ecode360.com)"},{"url":"https://highlandsnj.gov/wp-content/uploads/2024/10/Residential-Certificate-of-Inspection-Application-1.pdf","label":"Official source (highlandsnj.gov)"},{"url":"https://highlandsnj.gov/wp-content/uploads/2025/01/Housing-Workflow.pdf","label":"Official source (highlandsnj.gov)"},{"url":"https://ecode360.com/35385967","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Schedule your inspection by calling the Housing Secretary at 732-872-1224, ext. 204.$t$, $t$93e9fce57d2308979e4b59c92fd0b2c1381f0e7346c88626ee9a65da43f49c8a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":4,"fee_bad":0,"fee_unchecked":6,"quotes":10,"q_ok":7,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1319.json$t$, true),
  ($t$1319$t$, $t$Highlands Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Highlands Borough Fire Prevention Division (Bureau of Fire Prevention) (town fire bureau)","Contact: Charles Wells, Fire Official (state fire directory); also listed as Housing Officer and Fire Prevention Inspector on the Borough… · 732-872-1224 · cwells@highlandsnj.gov","Apply: Fee depends on business days between scheduling and the appointment: more than 10 business days for the lowest fee. Inspected together with the housing inspection.","How to apply: Use the same Borough Application for Residential Certificate of Inspection and Certificate of Smoke/Carbon Detector & Fire Extinguisher; one combined payment covers housing and fire. Email the form to cashier@highlandsnj.gov, pay by check at Borough Hall, and call 732-872-1224 ext. 204 to schedule.","Fire official in the NJ state directory (town), updated 8/2/2025: Charles Wells · (732) 872-1224 · cwells@highlandsnj.gov","Smoke alarms and carbon monoxide alarms per N.J.A.C. 5:70-4.19","Borough code (Section 11-10a4) says 1 and 2 family homes may not be sold unless hard-wired smoke detection devices are installed, with at least one per level and one within 15 feet of the main heating plant (a heat detector if the heating plant is in a confined space)","Fire extinguisher (form still lists it): the application and workflow still name a smoke/carbon detector and fire extinguisher certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector certificate, scheduled more than 10 business days ahead (CSDC-1)","amount":"$45"},{"label":"Scheduled 4 to 9 business days ahead (CSDC-2)","amount":"$90"},{"label":"Scheduled less than 4 business days ahead (CSDC-3)","amount":"$161"},{"label":"Reinspection after a missed appointment or failed detectors (CSDC-4)","amount":"$45"}]$j$::jsonb, $t$https://highlandsnj.gov/wp-content/uploads/2024/10/Residential-Certificate-of-Inspection-Application-1.pdf$t$, $t$https://highlandsnj.gov/departments/housing-inspections-and-enforcement/$t$, $j$[{"url":"https://highlandsnj.gov/wp-content/uploads/2024/10/Residential-Certificate-of-Inspection-Application-1.pdf","label":"Official source (highlandsnj.gov)"},{"url":"https://highlandsnj.gov/departments/housing-inspections-and-enforcement/","label":"Official source (highlandsnj.gov)"},{"url":"https://ecode360.com/35764536","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/35764527","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Certificate of Smoke/Carbon Detector & Fire Extinguisher$t$, $t$e7700012b65f0655c0d2a6521d298f3f4ac6b27398b858e59f5694e90f0de9dc$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":4,"fee_bad":0,"fee_unchecked":6,"quotes":10,"q_ok":7,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1319.json$t$, true),
  ($t$1320$t$, $t$Holmdel Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Certificate of Code Compliance (CCO, Certificate of Continued Occupancy)$t$, $j$["Issued by: Holmdel Township Department of Community Development (Enforcement Officer; Code Enforcement and Bureau of Fire Prevention staff)","Contact: Dina Rosado, Technical Assistant, Bureau of Fire Prevention / Community Development · 732-946-2820 ext. 1307 · drosado@holmdel.gov","Apply: Submit the application and fees at least 10 business days before the new owner moves in. Inspections can be requested up to 30 days ahead and are scheduled in the order received. A CCO or denial is issued within 10 business days of a complete application; a reinspection is done within 3 business days of the request.","How to apply: Apply online for a Residential Certificate of Code Compliance through the Township's SDL Portal (link on the Occupancy Certificate page) and pay before the inspection is scheduled. Apply at least 10 business days before the closing or move-in. Download the Residential Occupancy Certificate Checklist to prepare.","Property history review: all construction permits closed, all violations closed and penalties paid, deed and zoning restrictions checked","Work done without required construction permits is sent to the Construction Official and cited; the owner must obtain the permits","Exterior: accessory structures, walks and driveways in good repair; yard free of overgrowth and rubbish; wells and septic maintained or properly abandoned; pool gates self-closing and self-latching at least 54 inches high","Address numbers at least 3 inches high on the house or mailbox; exterior surfaces free of peeling paint and termite activity; stairs, decks and porches with approved handrails and guards","Interior: no second kitchen unless deed-restricted and permitted; no basement sleeping quarters without a permitted second exit; windows and doors working with screens; handrails on stairs with more than three risers; guards on landings 30 inches or higher","Bathroom exhaust fan or window; metal dryer duct vented outside; fuel-fired appliances properly vented; front door opens from inside without a key (no double-keyed deadbolts); sump pump not tied to the sanitary sewer; all utilities on","All parts of the premises must be accessible for the inspection","Also: Open permits and violations: The CCO review confirms all construction permits are closed and all violations closed with penalties paid; work done without permits is cited and must be permitted.","Also: Wells and septic: Wells and septic systems must be maintained in good repair or properly abandoned as part of the CCO inspection."]$j$::jsonb, $j$[{"label":"CCO, sale of a single-family home, condominium or townhouse, initial inspection","amount":"$125"},{"label":"Second and later reinspections, each (first reinspection free)","amount":"$50"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/holmdeltwp/requests/smokealarm$t$, $t$https://www.holmdeltownship.com/422/Occupancy-Certificate-of-Code-Compliance$t$, $j$[{"url":"https://www.holmdeltownship.com/422/Occupancy-Certificate-of-Code-Compliance","label":"Official source (holmdeltownship.com)"},{"url":"https://ecode360.com/35667860","label":"Official source (ecode360.com)"},{"url":"https://www.holmdeltownship.com/DocumentCenter/View/6584/Occupancy-Type-Fee-Requirements","label":"Official source (holmdeltownship.com)"},{"url":"https://www.holmdeltownship.com/DocumentCenter/View/5019/Code-Enforcement_Fire-Fee-Summary","label":"Official source (holmdeltownship.com)"}]$j$::jsonb, $t$Such inspection is required to be conducted at the time a Residential or Commercial property is sold, leased, or rented, or when a Commercial occupancy moves into a new space.$t$, $t$55913ca90988748aac0f7d8631958deb2756893b21ea93fd4e5bc8591af383f3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1320.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1320.json$t$, true),
  ($t$1320$t$, $t$Holmdel Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Holmdel Township Bureau of Fire Prevention (town fire bureau)","Contact: David Olsen, Fire Official · 732-946-2820 ext. 1315 · dolsen@holmdel.gov","Apply: Fee depends on business days before the change of occupant. Done alongside the CCO application through the SDL Portal.","How to apply: Apply through the Township's SDL Portal (Residential Certificate of Code Compliance / smoke alarm request) and pay online. Call the Bureau of Fire Prevention at 732-946-2820 with questions.","Fire official in the NJ state directory (town), updated 1/14/2026: David Olsen · (732) 946-2820 · dolsen@holmdeltownship-nj.com","Smoke alarms and carbon monoxide alarms per N.J.A.C. 5:70-4.19","Fire extinguisher (Township sheets still list it): the fee summary and workflow still call the certificate a smoke alarm, carbon monoxide alarm and portable fire extinguisher certificate (CSACMAPFEC)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request more than four business days before the change of occupant (workflow sheet)","amount":"$45"},{"label":"Request four business days or more before the change of occupant (fee summary sheet)","amount":"$90"},{"label":"Request fewer than four business days before the change of occupant","amount":"$161"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/holmdeltwp/requests/smokealarm$t$, $t$https://www.holmdeltownship.com/729/Fire-Prevention$t$, $j$[{"url":"https://www.holmdeltownship.com/729/Fire-Prevention","label":"Official source (holmdeltownship.com)"},{"url":"https://www.holmdeltownship.com/DocumentCenter/View/6584/Occupancy-Type-Fee-Requirements","label":"Official source (holmdeltownship.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.holmdeltownship.com/DocumentCenter/View/5019/Code-Enforcement_Fire-Fee-Summary","label":"Official source (holmdeltownship.com)"}]$j$::jsonb, $t$Resale and rental inspections$t$, $t$8aeeac504a3cc60ef8bf1fb83d8cba8f31b9bf09c68ddb5467f61f73853d387f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1320.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1320.json$t$, true),
  ($t$1322$t$, $t$Interlaken Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection Permitting Occupancy (Certificate of Occupancy for sale)$t$, $j$["Issued by: Borough of Interlaken Construction Official (Building & Code office)","Contact: Tom Haege, Construction Official / Fire Sub-Code Official · 732-531-7405","How to apply: Download the Certificate of Occupancy form from the Borough Forms page, check SALE, fill in the owner, buyer, dwelling type and requested inspection date, and return it with the fee to the Construction Department at Borough Hall (Monday to Friday, 8:30 to 4:30). The fee must be paid when you apply. Someone must be present to let the inspector in.","Written application to the Construction Official before transfer of title or occupancy, naming seller, buyer and proposed occupants, with consent to inspect","Inspection by the Construction Official; the certificate is issued only when the home complies with all Borough ordinances","All construction permits (building, electric, plumbing, fire) closed out","Stairs in good repair, guardrails on walking surfaces 30 inches or higher, windows operable with no broken panes","Fuel-fired appliance venting intact; visible wiring, electric panel and plumbing fixtures without defects; no obvious roof or wall leaks","Smoke detector on each level (110 volt and/or 10-year sealed battery type) and a carbon monoxide detector on every level with bedrooms","Fire separation and a minimum 1 3/8 inch solid core door between an attached garage and the living area","No double-keyed deadbolts (locks must capture the key)","Sidewalks free of cracks and trip hazards (maximum 3/4 inch height difference at joints)","Minimum 2A 10BC fire extinguisher mounted within 10 feet of the kitchen (form still lists it)","Also: Open permits: The Borough inspection checklist requires all construction permits (building, electric, plumbing, fire) to be closed out.","Also: Sidewalk condition: The resale inspection checks that sidewalks are free of cracks and trip hazards (maximum 3/4 inch height difference at joints)."]$j$::jsonb, $j$[{"label":"Certificate of inspection for the sale of a house (Code 10-5.12g)","amount":"$100"},{"label":"Certificate of occupancy application fee for a sale (Borough form)","amount":"$100.00"}]$j$::jsonb, $t$https://www.interlakenboro.com/uploads/2/1/3/0/21304132/2026_certificate_of_occupancy_w_rental.docx$t$, $t$https://www.interlakenboro.com/building--code.html$t$, $j$[{"url":"https://ecode360.com/35522794","label":"Official source (ecode360.com)"},{"url":"https://www.interlakenboro.com/forms.html","label":"Official source (interlakenboro.com)"},{"url":"https://www.interlakenboro.com/uploads/2/1/3/0/21304132/2026_certificate_of_occupancy_w_rental.docx","label":"Official source (interlakenboro.com)"},{"url":"https://www.interlakenboro.com/building--code.html","label":"Official source (interlakenboro.com)"}]$j$::jsonb, $t$No person shall occupy, rent, lease, transfer title to, or suffer the occupancy of, the letting of, or allow any person to live in or upon or inhabit as a tenant or occupant or occupy as a new owner or cotenant or co-owner any dwelling house or dwelling unit within the confines of the Borough unless and until that person shall have first obtained from the Construction Official of the Borough, a Certificate of Inspection Permitting Occupancy$t$, $t$755fc3f934c15646eab40167aa9486bc362db4d622e5776c38972b79afc1efc1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1322.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1322.json$t$, true),
  ($t$1322$t$, $t$Interlaken Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety (state-enforced) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official (NJ Division of Fire Safety), per state directory · (609) 633-6132","Apply: Fee depends on how many business days before the change of occupant the request is received: more than 10 business days for the lowest fee.","How to apply: Apply online through the DCA Service Portal 'Apply For Smoke Certification' (firesolutions.dca.nj.gov), choosing Monmouth County and Interlaken Borough, or call the Division of Fire Safety at (609) 633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 6/26/2026: Louis Kilmer · (609)633-6132","Smoke alarms on each level of the home, including basements, and outside each separate sleeping area","Battery smoke alarms must be 10-year sealed units; AC powered or interconnected alarms in homes built after January 1977 must be kept working","Carbon monoxide alarm on every level with bedrooms (Borough checklist)","Minimum 2A 10BC fire extinguisher mounted within 10 feet of the kitchen (Borough checklist still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate (N.J.A.C. 5:70-2.9(d)), received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Received four to 10 business days before","amount":"$90.00"},{"label":"Received fewer than four business days before","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create$t$, $t$https://firesolutions.dca.nj.gov$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.interlakenboro.com/uploads/2/1/3/0/21304132/2026_certificate_of_occupancy_w_rental.docx","label":"Official source (interlakenboro.com)"}]$j$::jsonb, $t$S Interlaken Borough$t$, $t$848f46e42b05337757ba7a6567acddf1767c163b39e9da6ba9b8da0f1aa0e338$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1322.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1322.json$t$, true),
  ($t$1323$t$, $t$Keansburg Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Housing Inspection (Housing Occupancy Certificate)$t$, $j$["Issued by: Borough of Keansburg Code Enforcement and Construction Office","Contact: Chris Hoff, Code Enforcement Officer (Ext. 222) · 732-787-0215 ext. 220","Apply: The inspection must be scheduled before the sale or occupancy.","How to apply: Fill out the Certificate of Housing Inspection Application and bring or mail it with payment to the Code Enforcement and Construction Office, Borough Hall, 29 Church Street, Keansburg, NJ 07734 (open Monday to Friday, 8:30 a.m. to 4:00 p.m.). Applications must be submitted in person or by mail; no electronic submissions. Schedule the inspection before the sale or occupancy.","Certificate of Housing Inspection application signed by the owner, buyer or agent, with seller and buyer details, number of bedrooms and occupants","Inspection by a municipal inspector; all violations corrected before occupancy unless written arrangements are made","Smoke and carbon monoxide detector inspection is done with the housing inspection (extra fee)","Smoke detector on each floor (Code 11-5)","Close all UCC permits (listed as a violation item on the form)","Fire extinguisher (form still lists it as a violation item)","By signing for a sale, the owner or agent attests that no adjoining property is owned by the same person that may require a formal subdivision","Also: Open permits: The housing inspection form lists 'Close all UCC Permits' as a violation that must be corrected before occupancy.","Also: Adjoining lots: For a sale, the person signing the application attests that no adjoining property is owned by the same person that may require a formal subdivision before the sale."]$j$::jsonb, $j$[{"label":"Housing inspection application, covers two inspections (2023 application)","amount":"$75.00"},{"label":"Inspection fee for two inspections (Construction Office page)","amount":"$120"},{"label":"Housing occupancy certificate, initial inspection and first reinspection (Code 11-3.1b)","amount":"$75"},{"label":"Each second or later reinspection (Code 11-3.1b)","amount":"$20"},{"label":"Smoke and carbon monoxide detector inspection, added to the housing inspection fee (2023 application)","amount":"$45"},{"label":"CSDCMAC, more than 10 business days before the change of occupancy (Code 11-5d)","amount":"$35"},{"label":"CSDCMAC, between four and 10 business days (Code 11-5d)","amount":"$75"},{"label":"CSDCMAC, less than four business days (Code 11-5d)","amount":"$125"}]$j$::jsonb, $t$https://keansburgnj.gov/wp-content/uploads/2023/01/Certificate-of-Housing-Inspection-Application-1.2023.pdf$t$, $t$https://keansburgnj.gov/development/construction-office/$t$, $j$[{"url":"https://ecode360.com/35677685","label":"Official source (ecode360.com)"},{"url":"https://keansburgnj.gov/wp-content/uploads/2023/01/Certificate-of-Housing-Inspection-Application-1.2023.pdf","label":"Official source (keansburgnj.gov)"},{"url":"https://keansburgnj.gov/development/construction-office/","label":"Official source (keansburgnj.gov)"},{"url":"https://keansburgnj.gov/development/contact-development/","label":"Official source (keansburgnj.gov)"},{"url":"https://ecode360.com/35677762","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Whenever there is a proposed change of ownership of any dwelling unit, such change of ownership shall not be made nor shall the subsequent owner occupy or permit occupancy of, nor shall any person rent, lease or occupy, the dwelling unit, without first complying with the requirements of this section.$t$, $t$b1d1d164fccdc4a175d925207166e2858473440d807b3717bae36362a82481d4$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":4,"fee_bad":0,"fee_unchecked":8,"quotes":13,"q_ok":10,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1323.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1323.json$t$, true),
  ($t$1323$t$, $t$Keansburg Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Keansburg Fire Official (Code Enforcement and Construction Office) (town fire bureau)","Contact: Arthur Boden, Fire Official · 732-787-0215 ext. 224 · arthur.boden@keansburg-nj.us","Apply: Code 11-5 bases the fee on business days before the change of occupancy; the 2023 application charges a flat $45 added to the housing inspection fee.","How to apply: The smoke and carbon monoxide inspection is requested on the same Certificate of Housing Inspection Application and paid with it at the Code Enforcement and Construction Office, 29 Church Street.","Fire official in the NJ state directory, updated 6/13/2025: Arthur V Boden · (732) 787-0215 · arthur.boden@keansburg-nj.us","Smoke detector on each floor of a one- or two-family house (Code 11-5)","Carbon monoxide detectors as required by the Uniform Construction Code","Smoke and carbon monoxide inspection is part of the housing inspection; the form lists 'Provide Fire Extinguisher' as a possible violation (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide detector inspection, added to the housing inspection fee (2023 application)","amount":"$45"},{"label":"CSDCMAC, more than 10 business days before the change of occupancy (Code 11-5d)","amount":"$35"},{"label":"CSDCMAC, between four and 10 business days (Code 11-5d)","amount":"$75"},{"label":"CSDCMAC, less than four business days (Code 11-5d)","amount":"$125"}]$j$::jsonb, $t$https://keansburgnj.gov/wp-content/uploads/2023/01/Certificate-of-Housing-Inspection-Application-1.2023.pdf$t$, $t$https://keansburgnj.gov/development/construction-office/$t$, $j$[{"url":"https://ecode360.com/35677762","label":"Official source (ecode360.com)"},{"url":"https://keansburgnj.gov/wp-content/uploads/2023/01/Certificate-of-Housing-Inspection-Application-1.2023.pdf","label":"Official source (keansburgnj.gov)"},{"url":"https://keansburgnj.gov/development/construction-office/","label":"Official source (keansburgnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$An application fee for a certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC), as required by N.J.S.A. 5:70-2.3, shall be based upon the amount of time remaining before the changing of occupancy:$t$, $t$da9aa1785aac49e63a4e57f057dd78da1b3a24774fd2f69e8a3f5aed12002045$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":4,"fee_bad":0,"fee_unchecked":8,"quotes":13,"q_ok":10,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1323.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1323.json$t$, true),
  ($t$1324$t$, $t$Keyport Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Housing and Building Code Change of Occupancy & Transfer of Title (Change of Occupancy CO)$t$, $j$["Issued by: Borough of Keyport Code Enforcement Office","Contact: David Quinn, Property Maintenance Official/Code Enforcement Official · 732-739-5157 · dquinn@keyportonline.com","Apply: Fee depends on business days before the inspection: 10 or more business days for the lowest fee. Payment is due when the appointment is scheduled.","How to apply: Bring the completed Change of Occupancy Residential Sale application (with the Fire Prevention Bureau smoke/CO page) and payment to the Code Enforcement office at Borough Hall, 70 West Front Street. Payment is due when the appointment is scheduled. Have the house vacant and unlocked for the inspector; if it passes, the CO is left on the kitchen counter, and if not, the report is emailed.","Application for Housing and Building Code Change of Occupancy & Transfer of Title, with owner, buyer and all occupants listed","Separate smoke detector, carbon monoxide alarm and fire extinguisher certificate from the Keyport Fire Prevention Bureau (smoke fee added to the CO fee)","Property should be vacant for the inspection; unlock the door and wait outside","GFI outlets in every bathroom and at kitchen counter outlets within six feet of a sink before a Certificate of Occupancy is issued (Code 12-12.1)","Fire extinguisher, minimum 5 lb. ABC, mounted in the kitchen (form still lists it)","Also: GFI outlets: Every dwelling to be sold must have GFI outlets in every bathroom and at every kitchen counter outlet within six feet of a sink before a Certificate of Occupancy is issued.","Also: Smoke detector inspection before transfer: Code 12-6 says no one-, two- or three-family residence may be sold unless inspected and approved for smoke detectors; the Tax Collector reminds anyone ordering a tax search."]$j$::jsonb, $j$[{"label":"Change of occupancy (resale), 10 or more business days","amount":"$110.00"},{"label":"Change of occupancy (resale), 4 to 10 business days","amount":"$190.00"},{"label":"Change of occupancy (resale), less than 4 business days","amount":"$245.00"},{"label":"Certificate of Occupancy application fee for a dwelling unit (Code 12-2.3, older amount)","amount":"$75"},{"label":"Expedited CO, four to 10 days (Code 12-2.3, older amount)","amount":"$155"},{"label":"Expedited CO, less than four days (Code 12-2.3, older amount)","amount":"$210"},{"label":"Smoke detector, CO alarm and fire extinguisher certificate, received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Received four to 10 business days before","amount":"$90.00"},{"label":"Received less than four business days before","amount":"$161.00"}]$j$::jsonb, $t$https://keyportonline.com/wp-content/uploads/2025/08/Change_of_Occupancy_Residential_Sale_-_fillable.pdf$t$, $t$https://keyportonline.com/government/building/$t$, $j$[{"url":"https://keyportonline.com/government/building/","label":"Official source (keyportonline.com)"},{"url":"https://keyportonline.com/wp-content/uploads/2025/08/Change_of_Occupancy_Residential_Sale_-_fillable.pdf","label":"Official source (keyportonline.com)"},{"url":"https://ecode360.com/35073717","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Change of Occupancy (CO) inspections are being conducted$t$, $t$bfd46ccc916381a0a7e4e12a5c30b71fe3db418d4c702e285f6c30751415a01a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":9,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":13,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1324.json$t$, true),
  ($t$1324$t$, $t$Keyport Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Keyport Fire Prevention Bureau (town fire bureau)","Contact: Tony Vecchio, Housing Official/Fire Marshall/Fire Subcode Official (Fire Inspector: Nick Vecchio, nvecchio@keyportonline.com… · 732-739-5269 · tvecchio@keyportonline.com","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lowest fee. Office hours vary; leave a message.","How to apply: Complete the 'Application for Certificate of Smoke Detector, Carbon Monoxide Alarm & Fire Extinguisher Compliance' page of the Borough's Change of Occupancy sale packet and submit it with the fee to Borough Hall, 70 West Front Street. Call the Fire Prevention Bureau at 732-739-5269 with questions.","Fire official in the NJ state directory, updated 7/14/2026: Anthony P Vecchio · (732) 739-3900 · Firebureau@keyportonline.com","Smoke alarms on each level, including basements, and within 10 feet outside each sleeping area","Ten-year sealed battery single station smoke alarms listed to ANSI/UL 217; AC powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm within 10 feet of all sleeping areas","Minimum 5 lb. ABC fire extinguisher in the kitchen, visible, unblocked and mounted with the manufacturer's bracket (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, CO alarm and fire extinguisher certificate, received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Received four to 10 business days before","amount":"$90.00"},{"label":"Received less than four business days before","amount":"$161.00"}]$j$::jsonb, $t$https://keyportonline.com/wp-content/uploads/2025/08/Change_of_Occupancy_Residential_Sale_-_fillable.pdf$t$, $t$https://keyportonline.com/government/building/$t$, $j$[{"url":"https://keyportonline.com/wp-content/uploads/2025/08/Change_of_Occupancy_Residential_Sale_-_fillable.pdf","label":"Official source (keyportonline.com)"},{"url":"https://keyportonline.com/government/building/","label":"Official source (keyportonline.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF SMOKE DETECTOR, CARBON MONOXIDE$t$, $t$601a373d78406224516c70d52964639c918a14ef2db2ec810ad6b72bd7cc87f6$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":9,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":13,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1324.json$t$, true),
  ($t$1327$t$, $t$Long Branch$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Compliance (COC)$t$, $j$["Issued by: City of Long Branch Fire Marshal's Office (Fire Bureau)","Contact: Frederick Fritz, Fire Marshal · 732-571-5651 · ffritz@longbranch.org","How to apply: Download the Residential Certificate of Compliance and Sale of Property Application from the Fire Bureau's Applications and Documents page. Gather the paid sewer and tax print outs and the Building Department's 'no open permits' sign-off, then deliver all original pages in person with payment to the Fire Marshal's Office, 344 Broadway, Long Branch, NJ 07740. Credit cards are accepted (3% fee). If the buyer is buying 'as is', the City has an As-is Sale letter of intent form.","Valid for: The application is good for 30 days, including one re-inspection.","Residential Certificate of Compliance application, plus the smoke alarm, CO alarm and fire extinguisher compliance application for 1 and 2 family homes (both forms, total $95.00)","Sale of Property page with buyer and seller details","Long Branch Sewerage Authority print out showing the sewer bill paid to the current quarter","Tax Office print out showing taxes paid to the current quarter","'No open building permits' form signed off by the Long Branch Building Department","All forms delivered in person (originals only; no fax or mail)","The unit must be unoccupied for the inspection (City Ordinance 262-25(I))","Inspection items include: clean and sanitary unit, trash containers with lids, street numbers at least 3 inches, working doors, windows and locks, handrails on stairs with four or more risers, no plumbing leaks, heat and hot water, screens May 1 to October 1","Fire extinguisher 2A-10B:C, no more than 10 lbs., mounted within 10 feet of the kitchen (form still lists it)","Lead safe certification for pre-1978 rental properties (rentals only)","Also: Sewer bill paid: A print out from the Long Branch Sewerage Authority (150 Joline Avenue) showing the sewer bill paid to the current quarter must be submitted with the Certificate of Compliance application.","Also: Taxes paid: A print out from the Long Branch Tax Office showing taxes paid to the current quarter must be submitted with the application.","Also: No open building permits: The Long Branch Building Department must sign a form stating there are no open construction permits (732-571-5690).","Also: As-is sale letter: A buyer purchasing 'as is' signs a letter of intent with the seller choosing 30, 60 or 90 days for repairs; occupancy is not allowed until the Certificate of Compliance is issued."]$j$::jsonb, $j$[{"label":"Residential Certificate of Compliance","amount":"$60.00"},{"label":"Total for a 1 or 2 family home (COC plus smoke/CO certificate)","amount":"$95.00"},{"label":"Re-inspection or missed appointment after the one included re-inspection","amount":"$60.00"},{"label":"Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (1 and 2 family)","amount":"$35.00"}]$j$::jsonb, $t$https://www.longbranch.org/DocumentCenter/View/509/Residential-Certificate-of-Compliance-and-Sale-of-Property-Application-PDF$t$, $t$https://www.longbranch.org/201/Fire-Bureau$t$, $j$[{"url":"https://www.longbranch.org/201/Fire-Bureau","label":"Official source (longbranch.org)"},{"url":"https://www.longbranch.org/DocumentCenter/View/509/Residential-Certificate-of-Compliance-and-Sale-of-Property-Application-PDF","label":"Official source (longbranch.org)"},{"url":"https://www.longbranch.org/202/Applications-and-Documents","label":"Official source (longbranch.org)"},{"url":"https://www.longbranch.org/DocumentCenter/View/515/As-is-Sale-Form-PDF","label":"Official source (longbranch.org)"}]$j$::jsonb, $t$The Fire Marshal's Office is responsible for fire inspections, issuance of certificates of occupancy for rental properties and sales$t$, $t$cf68938fd3845d3130773f3f25b9b3fd5df9cb12a89ff53e543fb9de1005c01a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1327.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1327.json$t$, true),
  ($t$1327$t$, $t$Long Branch$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Long Branch Fire Marshal's Office (Fire Bureau) (town fire bureau)","Contact: Frederick Fritz, Fire Marshal · 732-571-5651 · ffritz@longbranch.org","Apply: One flat fee; no days-before-closing tiers are published.","How to apply: Submit the Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance Inspection Application (part of the Residential Certificate of Compliance and Sale of Property packet) in person with the $35.00 fee at the Fire Marshal's Office, 344 Broadway.","Fire official in the NJ state directory, updated 1/26/2026: Frederick J Fritz · (732) 571-5651 · ffritz@longbranch.org","Ten-year sealed battery smoke alarms on each level, inside each bedroom and within 10 feet of each bedroom (not required where 110 volt alarms or a low voltage fire alarm system is installed)","Low voltage alarm systems need annual certification from a licensed electrician or certified fire alarm contractor","Carbon monoxide alarms (battery, hardwired or plug-in) in the area of the sleeping rooms","Fire extinguisher rated 2A-10B:C, no more than 10 lbs., mounted within 10 feet of the kitchen in the path of egress, tagged or newly bought with receipt (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (1 and 2 family)","amount":"$35.00"}]$j$::jsonb, $t$https://www.longbranch.org/DocumentCenter/View/509/Residential-Certificate-of-Compliance-and-Sale-of-Property-Application-PDF$t$, $t$https://www.longbranch.org/201/Fire-Bureau$t$, $j$[{"url":"https://www.longbranch.org/DocumentCenter/View/509/Residential-Certificate-of-Compliance-and-Sale-of-Property-Application-PDF","label":"Official source (longbranch.org)"},{"url":"https://www.longbranch.org/201/Fire-Bureau","label":"Official source (longbranch.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PORTABLE FIRE EXTINGUISHER COMPLIANCE$t$, $t$f752df7b1972dd6f27acc4afa2417ac68b29574f81660bf183589d65fcad56c2$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1327.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1327.json$t$, true),
  ($t$1328$t$, $t$Manalapan Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Housing Certification (formerly Certificate of Continued Occupancy, CCO)$t$, $j$["Issued by: Manalapan Township Construction Code Department, Office of Housing","Contact: Richard W. Hogan, Construction Code/Fire Official · 732-446-8320","Apply: Inspections are scheduled by availability; apply well before closing and close out open permits first to avoid a re-inspection.","How to apply: Fill out the Application for Housing Certification (PDF) and bring or mail it to the Construction Code Department, Office of Housing, 120 Route 522, Manalapan, NJ 07726, with two checks or money orders payable to Manalapan Township ($150 housing inspection and $75 smoke detector), or exact cash. The form asks for block and lot, approximate closing date, occupancy type, whether the home is vacant, and whether it has municipal sewer and water or septic and well. The Township never asks for wire transfers.","Valid for: 90 days from the date of issuance","Housing inspection of the home against the Township checklist (6 inch house numbers, steps, railings, window screens, doors, heating, roof, stove anti-tip device, plumbing, electrical covers, no extension cords, clean yard, pool fence code compliant)","All existing open permits must be closed out before the inspection","Smoke and carbon monoxide certification, inspected at the same visit (see fire certificate)","Fire extinguisher, 2A-10BC type, no larger than 10 lbs, under the kitchen sink or within 10 feet of the kitchen (form still lists it)","Homes with well and septic systems need Health Department approval before the certification is issued","Also: Open permits: All existing open permits must be closed out before the Housing Certification inspection.","Also: Well and septic approval: Homes with well and septic systems need Health Department approval before the Housing Certification is issued."]$j$::jsonb, $j$[{"label":"Housing Certification (housing inspection)","amount":"$150"},{"label":"Total to apply (Housing Certification plus smoke certificate)","amount":"$225"}]$j$::jsonb, $t$https://mtnj.org/wp-content/uploads/2024/07/Housing-Application_.pdf$t$, $t$https://mtnj.org/departments/construction/housing/certificate_of_continued_occupancy/$t$, $j$[{"url":"https://mtnj.org/departments/construction/housing/certificate_of_continued_occupancy/","label":"Official source (mtnj.org)"},{"url":"https://mtnj.org/wp-content/uploads/2024/07/Housing-Application_.pdf","label":"Official source (mtnj.org)"},{"url":"https://mtnj.org/departments/construction/housing/refinancing/","label":"Official source (mtnj.org)"},{"url":"https://mtnj.org/departments/construction/","label":"Official source (mtnj.org)"}]$j$::jsonb, $t$A Housing Certification is required when selling or renting a home and is the responsibility of the seller.$t$, $t$0a442e8e4808ab99029057f4edb98c59bd3220b976c506df7c0ea61fe5aa18b9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1328.json$t$, true),
  ($t$1328$t$, $t$Manalapan Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Manalapan Township Fire Bureau (Fire Prevention, Construction Code Department) (town fire bureau)","Contact: Richard W. Hogan, Construction Code/Fire Official (Fire Inspector: Michael Lennox, 732-446-8369, MLennox@mtnj.org) · 732-446-8318 · rhogan@twp.manalapan.nj.us","Apply: Done at the same visit as the Housing Certification inspection; scheduled by availability. The certificate is good for six months.","How to apply: Apply on the same Application for Housing Certification and include a separate $75 check or money order payable to Manalapan Township (smoke detector). Cash or money order are listed as acceptable on the fire page.","Fire official in the NJ state directory (town), updated 6/25/2026: Richard W Hogan · (732) 446-8318 · rhogan@twp.manalapan.nj.us","Working smoke detectors on each level, including basements and crawl spaces, and within 10 feet of any sleeping area","Original systems must be kept (interconnected systems cannot be replaced with stand-alone battery units); battery smoke alarms must have a ten-year sealed battery","At least one carbon monoxide detector in the vicinity of all sleeping areas, more if bedrooms are on more than one level; leave the instruction booklet for the new owner","Fire extinguisher, 2A-10BC type, no more than 10 lbs (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector / carbon monoxide compliance certificate","amount":"$75.00"}]$j$::jsonb, $t$https://mtnj.org/wp-content/uploads/2024/07/Housing-Application_.pdf$t$, $t$https://mtnj.org/departments/construction/fire_prevention/residential_smoke_co_detector_certification/$t$, $j$[{"url":"https://mtnj.org/departments/construction/fire_prevention/residential_smoke_co_detector_certification/","label":"Official source (mtnj.org)"},{"url":"https://mtnj.org/departments/construction/","label":"Official source (mtnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A residential Smoke/CO Detector Certification inspection is performed in conjunction with the CCO (Certificate of Continued Occupancy) inspection.$t$, $t$2fa98dede04f902e4702177d8c8bc705cad8376046390b6808cd0c4eaa1d1ee5$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1328.json$t$, true),
  ($t$1329$t$, $t$Manasquan Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Real Property Transfer Permit (Transfer Certificate of Occupancy)$t$, $j$["Issued by: Borough of Manasquan Code Enforcement Official","Contact: 732-223-0544","Apply: The code says a permit or a written denial is issued within 10 days of a complete application, fee and the inspection being scheduled. Applying within 3 business days of the inspection costs more.","How to apply: Apply online through the Borough's SDL Portal (Rental Certificate & Real Estate Transfer), linked from the Code Enforcement page; an SDL account is needed. The fee is paid when the application is filed and is not refundable. The real estate agent must tell the seller and buyer in writing, within 10 days of the agreement of sale, that a transfer permit is needed. Borough Hall: 201 East Main Street, Manasquan NJ 08736, 732-223-0544.","Valid for: Not stated. A temporary transfer permit may be issued for up to 90 days when the home substantially complies.","Inspection showing the home is fit for occupancy under the Borough Property Maintenance Code (Chapter 13)","Adequate toilet and bathing facilities","Fire-rated door between the house and garage, and fire code sheetrock in a garage that adjoins or sits under living space","No fire hazards or electrical hazards","Smoke detectors on each floor and in the basement; carbon monoxide detectors where there are fuel-burning appliances or an attached garage","Portable fire extinguisher per N.J.S.A. 52:27D-198.1 (code still lists it)","Sidewalks, driveway aprons and curbs in good repair and safe condition","The inspection report records water meters and remote readers, number of units and kitchens, and any sump pump and where it discharges","Application in affidavit form with owner, buyer, representative, number of future occupants and sale price","A separate fee for each unit on the property","Also: Sidewalks, aprons and curbs: The transfer permit inspection requires sidewalks, driveway aprons and curbs to be in good repair and safe.","Also: Water meters and sump pump: The transfer inspection report records the water meters and remote reading devices and any sump pump and where it discharges.","Also: Agent notice: The real estate agent must notify the seller and buyer in writing within 10 days of the agreement of sale that a transfer permit is needed."]$j$::jsonb, $j$[{"label":"Real property transfer permit, initial inspection (per unit)","amount":"$175"},{"label":"Initial inspection applied for within 3 business days of the inspection (per unit)","amount":"$250"},{"label":"Reinspection (per unit)","amount":"$300"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/manasquan/requests/certificate$t$, $t$https://www.manasquan-nj.gov/codeenforcement$t$, $j$[{"url":"https://ecode360.com/MA0368","label":"Official source (ecode360.com)"},{"url":"https://www.manasquan-nj.gov/codeenforcement","label":"Official source (manasquan-nj.gov)"}]$j$::jsonb, $t$No person, firm or corporation shall convey, grant or otherwise transfer title to real property with a residential, business or commercial structure or improvement thereon or permit the same to be sold without first obtaining a real property transfer permit$t$, $t$abbfb05a3e7190700c9864da634e084f97d8eeaeee944455c6ac9f8fef89b3f9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":3,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1329.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1329.json$t$, true),
  ($t$1329$t$, $t$Manasquan Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough: issued by Borough of Manasquan Code Enforcement (smoke and CO detectors are checked in the Real Property Transfer Permit inspection)","Entire borough contact: 732-223-0544","Entire borough, apply: Same as the transfer permit inspection.","Entire borough, how to apply: Part of the Real Estate Transfer request on the Borough's SDL Portal. Confirm with Code Enforcement whether a separate smoke/CO certificate (CSACMAPFEC) and fee apply.","Entire borough: issued by Manasquan Fire District No. 1, Bureau of Fire Prevention (Fire Marshal) (fire district)","Entire borough contact: Christopher Barkalow, Fire Official · (732) 223-1599 · squanfiremarshal@yahoo.com","Entire borough, how to apply: No smoke/CO resale certificate form or fee is posted on the Fire District's Fire Bureau page. Call the Fire Bureau at (732) 223-1599 to confirm who issues the certificate.","Fire official in the NJ state directory (fire district), updated 2/5/2026: Christopher Barkalow · (732) 223-1599 · squanfiremarshal@yahoo.com","Smoke detectors on each floor and in the basement, UL listed","Carbon monoxide detectors in homes with fuel-burning appliances or an attached garage","Portable fire extinguisher (Borough code still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/manasquan/requests/certificate$t$, $t$https://www.manasquan-nj.gov/codeenforcement$t$, $j$[{"url":"https://ecode360.com/MA0368","label":"Official source (ecode360.com)"},{"url":"https://www.manasquanfire.org/","label":"Official source (manasquanfire.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detectors capable of sensing visible and invisible particles of combustion shall be required on each floor and the basement area in all principal structures on a lot.$t$, $t$16dec41c6bd451ba8bc5adf766ad373fae27ce2e5bd966099520f631253b7ce6$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":3,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1329.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1329.json$t$, true),
  ($t$1330$t$, $t$Marlboro Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO, Non UCC)$t$, $j$["Issued by: Marlboro Township Community Development, Zoning Division","Contact: 732-536-0200 ext. 1809 · zoning@marlboro-nj.gov","Apply: All fees are due with the application before an inspection is booked. The application can go in before the HVAC checklist, chimney report, Board of Health letter and alarm company letter, which can be handed to the inspector on inspection day.","How to apply: Download the Residential CCO packet (application, Home Improvement Form, Fire Bureau smoke/CO application, HVAC checklist and inspection checklist). Have the owner sign and notarize it, and hand it in at the Zoning Office, 1979 Township Drive, Marlboro (8:30 am to 4:30 pm, or the 24-hour drop box) with all fees. Pay by cash, check, money order, certified check or Visa, MasterCard or Discover; checks payable to Marlboro Township. Fees are non-refundable.","Valid for: The application says that if the change of occupancy does not happen within 6 months, a new application is required. HVAC checklists and chimney reports are good for 90 days; the county well/septic certification is good for 6 months.","Notarized application signed by the owner (or Power of Attorney, executor or trustee certificate) with buyer name and contract closing date","Notarized Home Improvement Form reviewed by Zoning and Construction; all structures must conform with Township ordinances (pre-1990 nonconforming structures may be exempt by affidavit)","All open permits closed out; work done without permits must be permitted","HVAC Furnace Inspection Checklist completed by a licensed HVAC contractor (CO readings of 9 ppm or less)","Level 1 chimney inspection by a certified chimney sweep for wood or gas fireplaces or stoves","Well and septic certification from the Monmouth County Board of Health (732-431-7456) if the home has a well or septic","Letter or report from the alarm monitoring company if smoke or CO alarms are tied to a monitored system","Inspection items include working heat in all rooms, operable windows, covered outlets, labeled secondary power source, 4 inch house numbers, no sump pump tied to the sanitary sewer, broom-clean rooms, thumb-lock exit doors, pool gates, metal dryer vent, sound decks and exterior","Smoke and carbon monoxide alarm certificate (see fire certificate)","Also: Home Improvement Form and zoning review: A notarized Home Improvement Form listing fences, patios, pools, decks, sheds, generators and similar items must be approved by Zoning and Construction; the Zoning Officer must find all structures conform before the CCO is issued.","Also: Open permits: All open permits must be closed, and work done without permits must be permitted, before the CCO is issued.","Also: HVAC and chimney reports: A licensed HVAC contractor's furnace checklist and a certified chimney sweep Level 1 report (for fireplaces or stoves) are required, each good for 90 days.","Also: Well and septic: Homes on well or septic need a certification from the Monmouth County Board of Health (732-431-7456), good for 6 months.","Also: Sump pump: No sump pumps may be connected to the sanitary sewer."]$j$::jsonb, $j$[{"label":"CCO, single family dwelling (sale or rental)","amount":"$125"},{"label":"CCO, apartment (not condo)","amount":"$100"},{"label":"CCO re-inspection (failed inspections only)","amount":"$75"},{"label":"Certificate for a single-family dwelling unit (Township Code 278-3B)","amount":"$125"}]$j$::jsonb, $t$https://www.marlboro-nj.gov/_Content/pdf/forms/CCO-Residential.pdf$t$, $t$https://www.marlboro-nj.gov/pages/construction-resources-and-forms$t$, $j$[{"url":"https://ecode360.com/12880259","label":"Official source (ecode360.com)"},{"url":"https://www.marlboro-nj.gov/_Content/pdf/forms/CCO-Residential.pdf","label":"Official source (marlboro-nj.gov)"}]$j$::jsonb, $t$No person shall sell, transfer, lease or rent any structure located within the Township of Marlboro unless a certificate of continued occupancy certifying that said structure is in compliance with all provisions of the current version of the International Property Maintenance Code adopted by the State of New Jersey and all other applicable ordinances of the Township of Marlboro is issued.$t$, $t$e48bb5ff98d2ea8bc7d69948c649e5e3c42148604f983699e24243f71a03f097$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1330.json$t$, true),
  ($t$1330$t$, $t$Marlboro Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Marlboro Township Fire Bureau (town fire bureau)","Contact: Christopher C Weltner, Fire Official (per NJ DCA fire directory) · 732-536-0200 ext. 1802 · cweltner@marlboro-nj.gov","Apply: Fee depends on how many days before the change of occupancy the application is received: more than 10 days for the lowest fee. A new application is needed if the change of occupancy does not happen within 6 months. The CCO housing inspector may sign the certificate during the CCO inspection.","How to apply: Fill out the Fire Bureau's Application for Certificate of Smoke and Carbon Monoxide Alarm Compliance (part of the Residential CCO packet) and submit it with the CCO application and fee at the Zoning Office. The fire certificate fee is in addition to the CCO fee.","Fire official in the NJ state directory (town), updated 4/25/2025: Christopher C Weltner · (732) 536-0200 · cweltner@marlboro-nj.gov","Smoke alarm in the basement within 10 feet of the stairway (not in the stairway), on the first floor, outside bedrooms within 10 feet of each bedroom door, and in finished attics","Hardwired alarms must be replaced like for like and stay interconnected; homes without hardwired alarms need 10-year sealed battery alarms; required hardwiring depends on when the house was built (table on the form)","No smoke alarm older than 10 years","Carbon monoxide alarm outside each separate sleeping area; CO alarms not older than 5 years or past the maker's expiration date","Monitored alarm systems need a letter or report on the alarm company letterhead (a certificate of monitoring is not accepted)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and CO alarm certificate, received more than 10 days before the occupancy change","amount":"$45"},{"label":"Received 4 to 10 days before the occupancy change","amount":"$90"},{"label":"Received fewer than 4 days before the occupancy change","amount":"$161"}]$j$::jsonb, $t$https://www.marlboro-nj.gov/_Content/pdf/forms/CCO-Residential.pdf$t$, $t$https://www.marlboro-nj.gov/pages/construction-resources-and-forms$t$, $j$[{"url":"https://www.marlboro-nj.gov/_Content/pdf/forms/CCO-Residential.pdf","label":"Official source (marlboro-nj.gov)"},{"url":"https://ecode360.com/12880259","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$FIRE CERTIFICATE FEES (This is in addition to the residential sale/rental fees):$t$, $t$39a26af1f4f13817e717927b2f17072084eaafe4ab68cc2acc23a40256bc7977$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1330.json$t$, true),
  ($t$1331$t$, $t$Matawan Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Continued Occupancy (Resale-CCO), including the smoke and CO certificate$t$, $j$["Issued by: Borough of Matawan Fire Prevention Bureau","Contact: Jose Pujols, Fire Official (x135); Fire Prevention Office Assistant Lynn Kramer (x128, Lynn.Kramer@MatawanBorough.com) · 732-566-3898 · Jose.Pujols@MatawanBorough.com","Apply: The Bureau suggests filing a month in advance. The fee depends on how many business days before the requested inspection date the application is received (more than 10 business days for the lowest fee). Inspections are held on various days between 10 am and 2 pm; work needing construction permits can delay the closing.","How to apply: Fill out the Resale-CCO application and email it with the MLS listing sheet, the realtor's business card and a requested inspection date (from the Fire Official's posted schedule) to the Fire Prevention Bureau (Jose Pujols, Lynn Kramer or Lara Calo). Once the forms are checked, the Bureau gives you an inspection number and the fee by phone or email. Pay online through the Borough's Online Payments tab under Fire Prevention (Payment Service Network, description 'RESALE CCO'), or by check payable to 'Matawan Fire Prevention Bureau'. The Bureau then confirms the inspection date and time.","Valid for: 60 days from the first inspection date","Resale-CCO inspection by the Fire Prevention Bureau, which includes the Certificate of Smoke Alarm and Carbon Monoxide Detector Compliance","All buildings and items (boilers, hot water heaters, etc.) must have the proper construction permits on record; missing permits must be taken out and inspected before the CCO is issued","Email the completed application with the MLS sheet and the realtor's business card, plus a requested inspection date from the Fire Official's calendar","Closing attorneys must confirm the closing within 5 days of closing","A temporary CCO (TCCO) is only for unoccupied properties that meet the smoke alarm rules, at the Fire Official's discretion","Also: Construction permits on record: Boilers, water heaters and other work must have permits on record; unpermitted items need new permits and inspections before the CCO is issued.","Also: Closing confirmation: Closing attorneys must confirm the closing to the Fire Prevention Bureau within 5 days of closing."]$j$::jsonb, $j$[{"label":"Resale-CCO, single family, received more than 10 business days before the requested inspection (includes smoke certificate)","amount":"$110.00"},{"label":"Resale-CCO, single family, received 4 to 10 business days before the requested inspection","amount":"$135.00"},{"label":"Resale-CCO, single family, received fewer than 4 business days before the requested inspection","amount":"$160.00"},{"label":"Resale-CCO, duplex or two family (any date)","amount":"$185.00"},{"label":"Temporary Resale-CCO (additional)","amount":"$250.00"},{"label":"Re-inspection","amount":"$25.00"},{"label":"Duplex or two family Resale-CCO, Borough Code 17-2c4 (includes smoke certificate)","amount":"$185"}]$j$::jsonb, $t$https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/APPLICATION%20FOR%20RESALE-CCO%20NEW.pdf$t$, $t$https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/$t$, $j$[{"url":"https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/","label":"Official source (matawanborough.com)"},{"url":"https://ecode360.com/35432278","label":"Official source (ecode360.com)"},{"url":"https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/APPLICATION%20FOR%20RESALE-CCO%20NEW.pdf","label":"Official source (matawanborough.com)"}]$j$::jsonb, $t$The Fire Prevention Bureau is responsible for Continued Certificate of Occupancies(CCO) in all residential change of tenancy(Rentals) and transfer of deeds(Resales).$t$, $t$b9e4ccf6a4775db6f8b33e78ee1e228ad0c785322a7811bbe94bf2fe9a00953e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":5,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1331.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1331.json$t$, true),
  ($t$1331$t$, $t$Matawan Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Matawan Fire Prevention Bureau (Matawan Borough Fire Department) (town fire bureau)","Contact: Jose Pujols, Fire Official · 732-566-3898 · Jose.Pujols@MatawanBorough.com","Apply: Same as the Resale-CCO: fee tiers are counted in business days before the requested inspection date.","How to apply: Included in the Resale-CCO application and fee (see resale certificate).","Fire official in the NJ state directory, updated 3/12/2014: Jose E Pujols · (732) 566-3898 · jose.pujols@matawanborough.com","Smoke alarms and carbon monoxide alarms per N.J.A.C. 5:70-4.19; battery-only smoke alarms must have a 10-year sealed battery","Checked during the Resale-CCO inspection; no separate application","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke certificate (CSDCMC) portion of the single family Resale-CCO fee","amount":"$35"}]$j$::jsonb, $t$https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/APPLICATION%20FOR%20RESALE-CCO%20NEW.pdf$t$, $t$https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/$t$, $j$[{"url":"https://ecode360.com/35432278","label":"Official source (ecode360.com)"},{"url":"https://www.matawanborough.com/matawan/Departments/Fire%20Prevention%20Bureau/","label":"Official source (matawanborough.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This fee includes the Resale-Certificate of Continued Occupancy (Resale-CCO) and Smoke Certificate (CSDCMC).$t$, $t$b8057b32022101a8e86e0cc344264ed3ceaec7e3e766619b4eabe8042aea70eb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":5,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1331.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1331.json$t$, true),
  ($t$1332$t$, $t$Middletown Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (CO) for sale$t$, $j$["Issued by: Middletown Township Building & Inspection Department (Housing)","Contact: Paul Durnien, Construction Official (732-615-2000 ext. 2185) · 732-615-2106","Apply: Inspection timing depends on the inspector's daily workload. The CO must be issued before transfer of title or occupancy.","How to apply: Fill out the Application for Residential Certificate of Occupancy (check SALE and give the prospective transfer date) and submit it to the Housing Department, Building & Inspection, 1 Kings Highway, Middletown, NJ 07748, with two separate checks payable to the Township of Middletown ($150 CO fee and $15 filing fee). Then apply separately to Fire Prevention for the smoke/CO certificate, giving them your CO inspection date.","Housing inspection under the International Property Maintenance Code (4 inch address numbers, no double cylinder locks, working heat, water heater relief line, combustion air louvers, solid core or steel garage fire door, roof, range, plumbing, no extension cords, GFCI outlets, handrails and guards, neat yard, metal dryer hose, pool barriers)","All open permits must have a final inspection, and permits and approvals are needed for recent construction","Smoke detector and carbon monoxide compliance certificate from the Fire Prevention Office, sent to the Building Department as part of the CO","If the home is occupied, an adult must be present at the inspection","A 60-day conditional CO is available if the buyer signs and notarizes an agreement to close open permits and fix violations and not move in until the Township allows it","Also: Open permits: All open permits must have a final inspection before the CO is issued; recent construction needs permits and approvals.","Also: 60-day conditional CO: If violations or open permits remain, the buyer can sign a notarized 60-day conditional CO agreement to take responsibility for them and not occupy until the Township authorizes it."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy, each sale of a house","amount":"$150"},{"label":"Filing fee (separate check)","amount":"$15"},{"label":"Reinspection (3rd inspection)","amount":"$75"}]$j$::jsonb, $t$https://middletownnj.org/DocumentCenter/View/7789/Application-for-Inspection-and-Assurance-of-a-Certificate-of-Occupancy-PDF$t$, $t$https://middletownnj.org/150/Certificate-of-Occupancy$t$, $j$[{"url":"https://middletownnj.org/150/Certificate-of-Occupancy","label":"Official source (middletownnj.org)"},{"url":"https://middletownnj.org/DocumentCenter/View/7789/Application-for-Inspection-and-Assurance-of-a-Certificate-of-Occupancy-PDF","label":"Official source (middletownnj.org)"},{"url":"https://middletownnj.org/DocumentCenter/View/7851/Residential-Certificate-of-Occupancy-Check-List-PDF","label":"Official source (middletownnj.org)"},{"url":"https://www.middletownnj.org/DocumentCenter/View/5205/Sixty-Day-Conditional-CO","label":"Official source (middletownnj.org)"}]$j$::jsonb, $t$Before an owner/tenant can occupy or change the title of a house or apartment it must meet certain requirements.$t$, $t$44de57eb624d1ef106a164b5a7565b1d3023befc86625aa3e6259746c9440b1b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1332.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1332.json$t$, true),
  ($t$1332$t$, $t$Middletown Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Middletown Township Bureau of Fire Prevention (Fire Prevention Office) (town fire bureau)","Contact: Edward Skelly, Fire Official · 732-615-2270 · bskelly@middletownnj.org","Apply: Fee depends on business days between receipt of the application and the closing/change of occupancy date: more than 10 business days for the lowest fee. Inspections are done between 8:30 am and 2:30 pm Monday to Friday on the same day as the CO inspection (not at the same time); no call ahead.","How to apply: First apply for the residential CO with the Building Department and schedule the CO inspection. Then submit the Application for Certificate of Smoke Detector & Carbon Monoxide Compliance in person or by mail to Middletown Fire Prevention, 1 Kings Highway (Johnson Gill Annex), with a check or money order payable to Middletown Fire Prevention or exact cash. A drop box outside the office takes applications with checks. The certificate is sent to the Building Department as part of the CO.","Fire official in the NJ state directory, updated 3/8/2024: Edward Skelly · (732) 615-2270 · bskelly@middletownnj.org","Ten-year sealed battery or hardwired smoke alarms in each bedroom and on each level within ten feet of the bedrooms (crawl spaces and unfinished attics excluded); UL listed with a test button; hardwired alarms from original construction may not be replaced with battery units","Carbon monoxide alarm on each level and within ten feet of the bedrooms (battery, plug-in or part of a central station system)","Central station alarm systems need a letter from the monitoring company that the system works","An adult (18 or older) must be present; pets secured","No fire extinguisher needed (the Township FAQ says the February 2025 law removed it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and CO certificate, received more than 10 business days before closing","amount":"$100"},{"label":"Received 4 to 10 business days before closing","amount":"$125"},{"label":"Received less than 4 business days before closing","amount":"$150"}]$j$::jsonb, $t$https://middletownnj.org/DocumentCenter/View/11670$t$, $t$https://www.middletownnj.org/fireprevention$t$, $j$[{"url":"https://www.middletownnj.org/fireprevention","label":"Official source (middletownnj.org)"},{"url":"https://middletownnj.org/DocumentCenter/View/11670","label":"Official source (middletownnj.org)"},{"url":"https://middletownnj.org/DocumentCenter/View/11669","label":"Official source (middletownnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Due to a change in the State law, smoke detector and carbon monoxide compliance certificates are now inspected and issued through the Middletown Township Fire Prevention Office.$t$, $t$78a387d9efbfad7cd9f11fb493a4e0fe774fb506e6b0dfb8866b8539ef8207d3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1332.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1332.json$t$, true),
  ($t$1333$t$, $t$Millstone Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (COI) for residential resale$t$, $j$["Issued by: Millstone Township Construction Department (Construction Official)","Contact: 732-917-2953","Apply: Submit the written application at least ten business days before the change of ownership; the Township says to allow about twenty business days to complete the certificate process. Permits for any unpermitted work must be filed, inspected and closed before a resale inspection can be booked.","How to apply: Fill out the Application, Checklist for Residential, Rental, Resale Certificate of Inspection (check RESALE, give the approximate closing date and a contact person) and file it with the Construction Department, 470 Stagecoach Road, Millstone Township, with the $250 fee payable to Millstone Township (check or Visa/MasterCard). Also arrange the Fire Department smoke/CO inspection (609-259-2560). No inspection is scheduled until all required items are received.","Valid for: The Township page says certificates are valid up to six months from issuance; the Township code says up to 60 days, extendable by the Construction Official for up to 120 more days (180 days total).","Records check that there are no open construction permits; any work done without a permit must be permitted, inspected and closed before the resale inspection appointment","Visual inspection by the Construction Official (4 inch house numbers within 10 feet of the road, railings, washer/dryer discharge and metal dryer vent, no garbage disposals, working HVAC, garage door and sheetrock, roof, stove anti-tip device, plumbing, covered electrical and GFI protection, clean yard, pool fence code)","Chimney caps, and a Level 1 inspection by a certified chimney sweep for wood burning fireplaces","Millstone Township Fire Department smoke/CO certificate before the final COI is issued","Homes on well or septic: the Health Officer reviews the water supply and septic (septic pumped within the last three years or less than five years old)","Certificate of Construction Records Closure (CRC) required before the sale of any residential structure","Also: Construction Records Closure (CRC): A Certificate of Construction Records Closure is required before the sale of any residential structure.","Also: Well and septic review: For homes on a well or septic, the Health Officer reviews water supply and the septic system; proof the septic was pumped within three years (or is under five years old) is required.","Also: Chimney inspection: Chimney caps are required, and wood burning fireplaces need at least a Level 1 inspection by a certified chimney sweep."]$j$::jsonb, $j$[{"label":"Certificate of Inspection (residential, rental or resale)","amount":"$250"},{"label":"Certificate of Inspection (Township page)","amount":"$250"},{"label":"Reinspection (Township Code 5-14)","amount":"$50"},{"label":"Residential temporary certificate (Township Code 5-14)","amount":"$75"}]$j$::jsonb, $t$https://storage.googleapis.com/juniper-media-library/232/2026/05/APPLICATION%20CHECKLIST%20FOR%20RESIDENTIAL%20CERTIFICATE%20OF%20INSPECTION%2005-22-26.pdf$t$, $t$https://www.millstonenj.gov/departments/construction-department$t$, $j$[{"url":"https://www.millstonenj.gov/departments/construction-department","label":"Official source (millstonenj.gov)"},{"url":"https://storage.googleapis.com/juniper-media-library/232/2026/05/APPLICATION%20CHECKLIST%20FOR%20RESIDENTIAL%20CERTIFICATE%20OF%20INSPECTION%2005-22-26.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://ecode360.com/35725152","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35717185","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The Ordinance states that a COI (Certificate of Inspection) certificate shall be required prior to the sale of any building and prior to the rental of any building within Millstone Township.$t$, $t$5c9b9cadb5c6ea22bca8cdee750e25b35cd2fd0a57c51e75972bbaa280548105$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":2,"fee_bad":0,"fee_unchecked":6,"quotes":10,"q_ok":6,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1333.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1333.json$t$, true),
  ($t$1333$t$, $t$Millstone Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Millstone Township Fire District No. 1, Bureau of Fire Prevention (Millstone Township Fire Company) (fire district)","Contact: Nicholas Krauss, Fire Official (per NJ DCA fire directory) · 609-259-2560 · Nkrauss@millstonefire.com","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lowest fee.","How to apply: Call the Millstone Township Fire Department at 609-259-2560 to request the resale smoke/CO inspection. No online form was found on the Township or Fire Company websites.","Fire official in the NJ state directory (fire district), updated 7/1/2026: Nicholas Krauss · (609) 259-2560 · Nkrauss@millstonefire.com","Smoke alarms, carbon monoxide alarms and portable fire extinguisher compliance per N.J.A.C. 5:70-4.19 (code still lists the extinguisher)","Fire Department certificate is needed before the final COI is issued","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSACMAPFEC requested more than 10 business days before the change of occupant","amount":"$45"},{"label":"Requested 4 to 10 business days before","amount":"$90"},{"label":"Requested fewer than 4 business days before","amount":"$161"},{"label":"Reinspection","amount":"$30"}]$j$::jsonb, null, $t$https://www.millstonenj.gov/departments/fire-prevention$t$, $j$[{"url":"https://ecode360.com/35725077","label":"Official source (ecode360.com)"},{"url":"https://storage.googleapis.com/juniper-media-library/232/2026/05/APPLICATION%20CHECKLIST%20FOR%20RESIDENTIAL%20CERTIFICATE%20OF%20INSPECTION%2005-22-26.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any one- and two-family or attached single-family structure is sold, leased or otherwise made subject to a change of occupancy for residential purposes, the owner shall obtain a certificate of smoke alarm, carbon monoxide alarm, and portable fire extinguisher compliance (CSACMAPFEC), evidencing compliance with N.J.A.C. 5:70-4.19.$t$, $t$b8cf426d63c393b5e92928fb9bd992ca4f98caab47923d075640ba37ae76a653$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":2,"fee_bad":0,"fee_unchecked":6,"quotes":10,"q_ok":6,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1333.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1333.json$t$, true),
  ($t$1334$t$, $t$Monmouth Beach Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Code Compliance (residential occupancy certificate for sale)$t$, $j$["Issued by: Borough of Monmouth Beach Housing Official (also the Fire Official)","Contact: Dave Olsen, Housing Official · 732-229-2204 ext. 1009 · dolsen@monmouthbeach.org","Apply: The Borough code says the certificate is granted or denied within 10 days of the application. Inspections are Tuesdays and Thursdays, 4:00 pm to 7:00 pm.","How to apply: Apply online through the Borough's SDL Portal link 'Apply for a Residential Certificate of Code Compliance'; the same request covers the occupancy certificate for a sale and the fire, smoke and carbon monoxide detector inspection. All fees are paid at the time of application and are not refundable. Questions go to Housing Official Dave Olsen, 732-229-2204 ext. 1009.","Housing inspection showing the building and premises comply with all Borough ordinances (Chapter 15 Housing and Property Maintenance)","Checklist items include accessible common areas, clean and pest-free unit, lidded trash containers, house numbers at least 3 inches, working doors and windows, handrails on stairs with five or more risers, no key-operated locks from inside, trimmed yard, poison ivy and ragweed removed, paint and surfaces in good repair, no plumbing leaks, water heater relief pipe to within 6 inches of the floor, heat and screens in season","Smoke detectors on each level and within 10 feet of each bedroom, and CO alarms, checked at the same request","Fire extinguisher, ten lbs. or less (2019 checklist still lists it)"]$j$::jsonb, $j$[{"label":"Housing inspection, sale of property","amount":"$100"},{"label":"Certificate of Code Compliance, each single family resale (Borough Code 15-4.1c)","amount":"$100"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/monmouthbeach/requests/smokeAlarm$t$, $t$https://www.monmouthbeach.org/government/departments/housing-department/$t$, $j$[{"url":"https://www.monmouthbeach.org/government/departments/housing-department/","label":"Official source (monmouthbeach.org)"},{"url":"https://ecode360.com/32002803","label":"Official source (ecode360.com)"},{"url":"https://www.monmouthbeach.org/wp-content/uploads/2019/09/2019-Housing-Checklist.pdf","label":"Official source (monmouthbeach.org)"}]$j$::jsonb, $t$requires that prior to the sale, rental, or lease of any single family, multi-family dwellings, or dwelling space, a Certificate of Code Compliance must first be obtained from the$t$, $t$827b653d3d05b7e1468aeb23bca8adfe134bab9e968d8c57d05a1983f943edbb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":8,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1334.json$t$, true),
  ($t$1334$t$, $t$Monmouth Beach Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Monmouth Beach Fire Prevention Bureau (town fire bureau)","Contact: Dave Olsen, Fire Official · 732-229-2204 ext. 1009 · dolsen@monmouthbeach.org","Apply: Fee depends on business days before the change of occupant: four business days or more for the lower fee. Inspections are Tuesdays and Thursdays, 4:00 pm to 7:00 pm.","How to apply: Use the same SDL Portal request (Application for Inspection Certificate & Smoke Certification) linked from the Fire Prevention Bureau and Housing pages.","Fire official in the NJ state directory, updated 7/28/2026: David C Olsen · (732) 229-2204 · dolsen@monmouthbeach.org","Smoke alarms on each level and outside each separate sleeping area (within 10 feet of each bedroom); 10-year sealed battery alarms unless hardwired alarms from original construction","Carbon monoxide alarms near sleeping areas in homes with a fuel-burning device or attached garage","Portable fire extinguisher within 10 feet of the kitchen (2019 checklist still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and CO alarm certificate (CSDCMAC), received four business days or more before the change of occupant","amount":"$100"},{"label":"Received fewer than four business days before the change of occupant","amount":"$161"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/monmouthbeach/requests/smokeAlarm$t$, $t$https://www.monmouthbeach.org/public-safety/fire-prevention-bureau/$t$, $j$[{"url":"https://www.monmouthbeach.org/public-safety/fire-prevention-bureau/","label":"Official source (monmouthbeach.org)"},{"url":"https://ecode360.com/32003024","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for Inspection Certificate & Smoke Certification$t$, $t$161172c9797e4bb9cd8883c9da4bdb3264186a79c40bbdeac5161b95419ca545$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":8,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1334.json$t$, true),
  ($t$1335$t$, $t$Neptune Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Inspection (CI) for sale$t$, $j$["Issued by: Neptune Township Code Enforcement Department","Contact: Donald Clare, Director of Code & Construction (ext. 263); Janet Silvestri, Departmental Secretary (ext. 261) · 732-988-5200 · jsilvestri@neptunetownship.org","Apply: Apply more than five business days before closing to avoid the $50 rush increase. The application must be completed and the inspection finalized within 30 days or the application becomes void.","How to apply: Apply online through the Township's Community Portal (Code Enforcement page, Residential Certificate of Inspection - Sale Application). Enter the parcel, buyer and occupant information, sign, and pay online by card (3.25% fee) or e-check ($1.25 fee), or pay by check payable to Township of Neptune or cash in person. Close all permits and violations and pay taxes and sewer before scheduling. Code Enforcement is at 25 Neptune Blvd, 732-988-5200.","Valid for: A conditional or temporary CI expires within 30 days of issuance (renewable at the code official's discretion).","Inspection of the dwelling, exterior and accessory structures for compliance with the Township property maintenance code and ordinances","All construction permits and violations must be closed out before the inspection is scheduled","Municipal charges (property taxes and sewer) must be paid current","Smoke detector on each level; carbon monoxide alarms outside each sleeping area in units with fuel-fired appliances or an attached garage","Wood-burning fireplaces and stoves need a certification from a CSIA certified chimney sweep","Oil tanks not in use must be removed or filled under a demolition permit","Sidewalks and stairs free of cracks, holes and hazards","Estates must submit the surrogate's certificate; corporations must submit formation documents or annual report","One application per residential building","Also: Open permits and violations: All construction permits and violations must be closed out before the CI inspection is scheduled.","Also: Taxes and sewer paid: Property taxes and sewer charges must be paid current before applying.","Also: Chimney certification: Wood-burning fireplaces and stoves need a certification from a Chimney Safety Institute of America certified chimney sweep.","Also: Unused oil tank: Oil tanks not in use must be removed or filled under the Uniform Construction Code; a demolition permit is required.","Also: Transfer of Title certificate: If the buyer will not occupy at closing (for example a renovation), a Transfer of Title certificate ($85) can be used instead; no occupancy is permitted until a CI is issued."]$j$::jsonb, $j$[{"label":"Certificate of Inspection, detached single-family dwelling or structure with 2 or more dwellings, per structure","amount":"$150.00"},{"label":"Certificate of Inspection, sale application (online instructions)","amount":"$150.00"},{"label":"Each additional unit in the same structure (for example the second unit of a 2-family)","amount":"$75.00"},{"label":"Rush increase when applying five or fewer business days before closing, per required inspection","amount":"$50"},{"label":"Inspection during non-business hours, up to two hours (extra)","amount":"$150.00"},{"label":"Reinspection, per structure including the first unit","amount":"$50.00"},{"label":"Transfer of Title certificate (no occupancy allowed)","amount":"$85.00"}]$j$::jsonb, $t$https://webgeo.co/prod1/portal/portal.jsp?c=46639958&p=355657208&g=558540796$t$, $t$https://neptunetownship.org/departments/code-enforcement$t$, $j$[{"url":"https://neptunetownship.org/departments/code-enforcement","label":"Official source (neptunetownship.org)"},{"url":"https://neptunetownship.org/sites/default/files/ORD21-20.pdf","label":"Official source (neptunetownship.org)"},{"url":"https://neptunetownship.org/sites/default/files/documents/CI%20Checklist%202025-4-9.pdf","label":"Official source (neptunetownship.org)"},{"url":"https://neptunetownship.org/sites/default/files/documents/Code%20and%20Construction-%20Fee%20Schedule_Updated%2010-18-2022.pdf","label":"Official source (neptunetownship.org)"},{"url":"https://neptunetownship.org/sites/default/files/documents/Construction/How%20to%20Apply%20for%20a%20Residential%20Sale%20CI.pdf","label":"Official source (neptunetownship.org)"}]$j$::jsonb, $t$This application is to be used for owner occupancy or sale of the property after a Transfer of Title or the owner occupancy after a Rental CI.$t$, $t$cb149262d610a5d3da94dd84e1373b569e485cad98dc2e0be96df180e40cf9eb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1335.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1335.json$t$, true),
  ($t$1335$t$, $t$Neptune Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire township: issued by Neptune Township Code Enforcement Department (smoke/CO compliance checked as part of the Certificate of Inspection)","Entire township contact: 732-988-5200","Entire township, apply: Same as the Certificate of Inspection.","Entire township, how to apply: No separate smoke/CO application or fee was found. The Township's Certificate of Inspection checklist and Code Enforcement page include the smoke, CO and extinguisher requirements, and an older Township fee schedule describes the CI fees as including the smoke detector and carbon monoxide certificate (CSDCMAC). Confirm with Code Enforcement (732-988-5200) whether the CI also serves as the state smoke/CO certificate or whether the fire district issues one.","Fire District #1: issued by Neptune Fire District #1 Fire Prevention Bureau and Ocean Grove Fire District #2 (fire code LEAs) (fire district). enforces one portion of the township; Ocean Grove Fire District #2 enforces the remainder (per the state LEA registry)","Fire District #1 contact: Scott V Liddick, Fire Official, Ocean Grove Fire District #2 · (732) 774-0306 · ogfdfi@yahoo.com","Fire District #1, how to apply: Neither fire district posts a resale smoke/CO certificate process online. Call the fire district for the property's area if the Township says a separate certificate is needed.","Fire official in the NJ state directory (fire district), updated 2/25/2025: Scott V Liddick · (732) 774-0306 · ogfdfi@yahoo.com","Smoke alarms on each level and outside each separate sleeping area; 10-year sealed battery units, hardwired alarms may not be replaced with battery-only units (Township handout quoting N.J.A.C. 5:70-4.19)","Smoke detectors in or next to a kitchen must be photoelectric (Township CI checklist)","Carbon monoxide alarms (UL 2034) near sleeping areas in homes with a fuel-burning device or attached garage","Township handout title still mentions portable fire extinguishers","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://webgeo.co/prod1/portal/portal.jsp?c=46639958&p=355657208&g=558540796$t$, $t$https://neptunetownship.org/departments/code-enforcement$t$, $j$[{"url":"https://neptunetownship.org/sites/default/files/CodeEnforcementFeeSchedule%202020%20Update.pdf","label":"Official source (neptunetownship.org)"},{"url":"https://neptunetownship.org/departments/code-enforcement","label":"Official source (neptunetownship.org)"},{"url":"https://neptunetownship.org/sites/default/files/Fire%20Extinguishers%20%26%20Smoke%20Detectors%202026.pdf","label":"Official source (neptunetownship.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://neptunetownship.org/departments/neptune-fire-district-1","label":"Official source (neptunetownship.org)"}]$j$::jsonb, $t$and Carbon Monoxide Compliance (CSDCMAC):$t$, $t$de9ad47cfca68f89ac833950209ae3e44d792589f44474b217c7ad77f57fd34a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1335.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1335.json$t$, true),
  ($t$1336$t$, $t$Neptune City Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (CI) for sale$t$, $j$["Issued by: Borough of Neptune City Zoning and Code Enforcement (Code Official)","Contact: Frank Cinelli, Code Enforcement Officer · 732-776-7224 · code@neptunecitynj.com","Apply: At least five business days notice is required to schedule the inspection; the inspector sets the date and time.","How to apply: Complete the Borough's Certificate of Inspection application (check Sale), list the new occupants, and submit it with the $120.00 fee by check payable to Borough of Neptune City at Borough Hall, 106 West Sylvania Avenue. Call 732-776-9204 x 35 to arrange the inspection, with at least five business days notice. Close any open construction permits first.","Interior and exterior property maintenance inspection by the Code Official (walks, exterior, steps, house numbers at least 3 inches, kitchen, bathrooms, basement, occupancy limits)","Smoke detector on every story including the basement, and outside of and within 10 feet of every bedroom; carbon monoxide detectors where required (check with the official)","All open construction permits must be finalized before the CI is issued for a dwelling being sold","Stove anti-tip bracket, dryer vented outside with rigid pipe, door between house and attached garage","Megan's Law statement signed by the new owner","An adult reachable at the phone number on the application to confirm the inspection time","Also: Open construction permits: All open construction permits must be finalized before the Certificate of Inspection is issued for a dwelling being sold.","Also: Megan's Law statement: The CI application includes a Megan's Law statement to be signed by the new owner or new tenant."]$j$::jsonb, $j$[{"label":"Certificate of Inspection for a property to be sold or leased (each unit)","amount":"$120"},{"label":"Reinspection after a failed initial inspection (each unit)","amount":"$200.00"},{"label":"Updated certificate of inspection","amount":"$60.00"},{"label":"Certificate of Inspection application (Borough form)","amount":"$120.00"}]$j$::jsonb, $t$https://www.neptunecitynj.com/zoning-code-enforcement/files/certificate-inspection-application$t$, $t$https://www.neptunecitynj.com/zoning-code-enforcement$t$, $j$[{"url":"https://www.neptunecitynj.com/zoning-code-enforcement","label":"Official source (neptunecitynj.com)"},{"url":"https://ecode360.com/36197369","label":"Official source (ecode360.com)"},{"url":"https://www.neptunecitynj.com/sites/g/files/vyhlif5316/f/uploads/mercantile_license_packet_zoning_ci_fire_prevention_police_and_vending_initial_application_updated_04.26.pdf","label":"Official source (neptunecitynj.com)"},{"url":"https://www.neptunecitynj.com/sites/g/files/vyhlif5316/f/pages/2026-74_establishing_the_boroughs_master_fee_schedule_for_the_borough_of_neptune_city_as_of_03.23.26_0.pdf","label":"Official source (neptunecitynj.com)"},{"url":"https://ecode360.com/36189346","label":"Official source (ecode360.com)"},{"url":"https://www.neptunecitynj.com/sites/g/files/vyhlif5316/f/pages/2026-01_amend_chpt_34_uniform_construction_code_enforcement_section_3_fees_and_chapter_62_article_iv_fees_0.pdf","label":"Official source (neptunecitynj.com)"}]$j$::jsonb, $t$Applicants need to obtain a Certificate of Inspection "CI" for a residential or commercial property sale, rental, transfer of title for occupancy.$t$, $t$afeb79e462c4b1a5aaacf932c95be6dc8c6cc41bdc272e070f264500b7411148$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1336.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1336.json$t$, true),
  ($t$1336$t$, $t$Neptune City Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Neptune City Bureau of Fire Prevention (Borough Fire Marshal) (town fire bureau)","Contact: Chris Willms, Borough Fire Marshal · 732-580-2128 · firemarshal@neptunecitynj.com","How to apply: No separate Borough smoke/CO certificate application or fee schedule was found online. The Borough's Certificate of Inspection checks smoke and CO detectors. Contact the Fire Marshal at firemarshal@neptunecitynj.com or 732-580-2128 to confirm whether a separate smoke/CO certificate is issued for sales.","Fire official in the NJ state directory, updated 4/25/2025: Christopher Willms · (732) 776-7224 · firemarshal@neptunecitynj.com","Smoke alarms on each level and outside each sleeping area (N.J.A.C. 5:70-4.19); the Borough CI checklist also asks for a smoke detector on every story including the basement and within 10 feet of every bedroom","Carbon monoxide alarm near the sleeping areas in homes with fuel-burning appliances or an attached garage","Battery-only smoke alarms should be 10-year sealed units; hardwired alarms may not be replaced with battery-only units (state rule)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.neptunecitynj.com/fire-marshal$t$, $j$[{"url":"https://ecode360.com/36189350","label":"Official source (ecode360.com)"},{"url":"https://www.neptunecitynj.com/fire-marshal","label":"Official source (neptunecitynj.com)"},{"url":"https://www.neptunecitynj.com/sites/g/files/vyhlif5316/f/uploads/mercantile_license_packet_zoning_ci_fire_prevention_police_and_vending_initial_application_updated_04.26.pdf","label":"Official source (neptunecitynj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The local enforcing agency shall be the Bureau of Fire Prevention of the Borough of Neptune City.$t$, $t$c0a24001d4235aeb89e149c372ad9893ae52f66b44b3a5cee58e680bfc2b626b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1336.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1336.json$t$, true),
  ($t$1337$t$, $t$Ocean Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Code Compliance Inspection Certificate (CCIC) for sales$t$, $j$["Issued by: Township of Ocean Division of Housing, Code Enforcement and Clean Communities (Housing Inspector / Code Enforcement Official)","Contact: Ken Pieslak, Code Enforcement Administrator (ext. 3378); Toni Severini, Administrative Secretary (ext. 3392) · 732-531-5000 ext. 3392 · oceancode@oceantwp.org","Apply: The Township must inspect and issue the CCIC or a notice of violation within 10 business days of the application.","How to apply: Apply online (cheaper) or on paper through the Township's Community Portal link on the Housing Forms page, then schedule with the Housing Division (732-531-5000 ext. 3392, oceancode@oceantwp.org). Close all building permits first. Before the certificate is issued, submit the smoke/CO certificate from your fire district, any septic/well report, and the Level 1 chimney inspection report. Post-dated checks are not accepted. Office: 399 Monmouth Road, Oakhurst, Monday to Friday 8:30 a.m. to 4:30 p.m.","Valid for: If a Certificate of Transfer of Title is used first, a CCIC inspection within 90 days of the original inspection is billed as a reinspection; after 90 days a new application is needed.","Exterior and interior inspection under the International Property Maintenance Code (paint and siding, gutters, house number at least 4 inches, Township garbage and recycling containers, handrails, pool barriers, GFCI outlets, egress locks, bedroom doors)","All building permits must be closed before calling for the CCIC inspection","Smoke certification from your fire district must be submitted to the housing office before the certificate is issued","Septic or well report from the Monmouth County Health Department where the home is on a septic system or well; certified lab water test for wells","Level 1 fireplace or chimney inspection by a licensed chimney sweep","All utilities on at the time of inspection","Cracked sidewalks along the street must be repaired to the Municipal Engineer's requirements","Garage apartments or 2-family use need paperwork showing they are legal; finished third floors or attics will not pass without it","Also: Open building permits: All permits must be closed before calling for the CCIC inspection; the Township reviews for open permits before issuing the certificate.","Also: Septic and well: Homes on septic or well need a Monmouth County Health Department report; well water must be tested by a certified lab and meet NJDEP standards.","Also: Chimney inspection: A Level 1 fireplace/chimney inspection report from a licensed chimney sweep must be submitted before the CCIC is issued.","Also: Sidewalks: Cracked sidewalks and public access along the street are the owner's responsibility and must be repaired to the Municipal Engineer's requirements (CCIC checklist item).","Also: Certificate of Transfer of Title: A transfer-of-title certificate allows the sale without occupancy; a CCIC is still needed before anyone moves in."]$j$::jsonb, $j$[{"label":"CCIC for resale of a detached dwelling, applied and paid online","amount":"$150"},{"label":"CCIC for resale of an attached single-family dwelling, applied and paid online","amount":"$125"},{"label":"CCIC for resale of a detached dwelling, paper application","amount":"$175"},{"label":"CCIC for resale of an attached single-family dwelling, paper application","amount":"$150"},{"label":"Reinspection when utilities are off, and second or later reinspections (first reinspection is free if utilities are on)","amount":"$75"},{"label":"Extra charge if utilities are not on at the inspection (Township checklist)","amount":"$75.00"}]$j$::jsonb, $t$https://webgeo.co/prod1/portal/portal.jsp?c=3668658&p=264317679&g=277480433$t$, $t$https://www.oceantwp.org/p/division-of-housing-1$t$, $j$[{"url":"https://www.oceantwp.org/p/division-of-housing-1","label":"Official source (oceantwp.org)"},{"url":"https://www.oceantwp.org/p/housing-forms-1","label":"Official source (oceantwp.org)"},{"url":"https://ecode360.com/35337988","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35337993","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35922344","label":"Official source (ecode360.com)"},{"url":"https://oceantwp.qscendcms.com/ckfinder/connector?command=Proxy&lang=en&type=Files&currentFolder=%2F&hash=c245c263ce0eced480effe66bbede6b4d46c15ae&fileName=sales%20Checklist%206-2024.pdf","label":"Official source (oceantwp.qscendcms.com)"},{"url":"https://www.oceantwp.org/p/housing-code-enforcement-and-clean-communities-personnel","label":"Official source (oceantwp.org)"},{"url":"https://ecode360.com/35337996","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The Housing Division is responsible for conducting Code Compliance Inspection Certificate inspections on all new sales of homes, condos and townhouses and any rentals that change occupancy.$t$, $t$b7be4b4994e47d6ce35d19d1518f9f9731b468b89e1c42028c1e2f5d99f88309$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":14,"fee_ok":1,"fee_bad":0,"fee_unchecked":13,"quotes":20,"q_ok":11,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/1337.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1337.json$t$, true),
  ($t$1337$t$, $t$Ocean Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District #1 area of the township (Ordinance No: issued by Township of Ocean Fire District #1 Bureau of Fire Prevention (Oakhurst) (fire district). 510 boundaries)","Fire District #1 area of the township (Ordinance No contact: Craig Flannigan, Fire Marshal, Fire District #1 · 732-222-2624","Fire District #1 area of the township (Ordinance No, apply: Fee is set by business days between the request and the change of occupant: more than 10 business days for the lowest fee. Inspections are closed out in the system by the end of the inspection day.","Fire District #1 area of the township (Ordinance No, how to apply: Call the Fire Marshal's Office at 732-222-2624 to schedule, or use the online smoke/CO form for Fire District #1 and #2 linked on the Township Housing Forms page (www.oceantwp.org or www.tofd1.org). Send the passed certificate to the Housing Division with the CCIC.","Fire District #2 area of the township (Ordinance No: issued by Township of Ocean Fire District #2 Bureau of Fire Prevention (Wanamassa) (fire district). 506 boundaries)","Fire District #2 area of the township (Ordinance No contact: Tom Haege, Fire Official, Ocean Twp Fire District #2 · (732) 988-0880 · thaege.otfm@verizon.net","Fire District #2 area of the township (Ordinance No, apply: Same fee tiers as District #1 under Township Code Section 6-5.6.","Fire District #2 area of the township (Ordinance No, how to apply: Use the online smoke/CO form for Fire District #1 and #2 linked on the Township Housing Forms page, or call the District #2 fire official at (732) 988-0880.","Fire official in the NJ state directory (fire district), updated 7/22/2026: Tom Haege · (732) 988-0880 · thaege.otfm@verizon.net","Smoke alarms no older than 10 years; battery units must be 10-year sealed; UL listed","By construction year (Fire District #1 handout): before 1978 battery alarms on each level; 1978-1983 hardwired on each level; 1984-1990 interconnected hardwired with battery backup on each level; 1991 on interconnected hardwired with battery backup on each level and in all bedrooms","Smoke alarms within 10 feet of bedroom doors, near stairs; in 2-family homes in common hallways and at each stair landing","Carbon monoxide alarms on each sleeping level near bedroom doors in homes with fuel-burning devices or an attached garage","Central station alarm systems must be audible and testable and cannot replace required alarms","Secondary power source label (\"CAUTION: MULTIPLE SOURCES OF POWER\") within 18 inches of the main panel and meter for homes with generators, solar or batteries","Fire extinguisher no longer required in Ocean Township (Fire District #1 handout, 9-2025); the Township Code fee section still names it","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District #1 area of the township (Ordinance No: Smoke/CO certificate, request more than 10 business days before change of occupant","amount":"$35"},{"label":"Fire District #1 area of the township (Ordinance No: Request four to 10 business days before","amount":"$70"},{"label":"Fire District #1 area of the township (Ordinance No: Request fewer than four business days before","amount":"$125"},{"label":"Fire District #1 area of the township (Ordinance No: Reinspection","amount":"$20"},{"label":"Fire District #2 area of the township (Ordinance No: Smoke/CO certificate, request more than 10 business days before change of occupant","amount":"$35"},{"label":"Fire District #2 area of the township (Ordinance No: Request four to 10 business days before","amount":"$70"},{"label":"Fire District #2 area of the township (Ordinance No: Request fewer than four business days before","amount":"$125"},{"label":"Fire District #2 area of the township (Ordinance No: Reinspection","amount":"$20"}]$j$::jsonb, $t$https://webgeo.co/prod1/portal/portal.jsp?c=3668658&p=557697639&g=557697648$t$, $t$https://www.oceantwp.org/p/housing-forms-1$t$, $j$[{"url":"https://oceantwp.qscendcms.com/ckfinder/connector?command=Proxy&lang=en&type=Files&currentFolder=%2F&hash=c245c263ce0eced480effe66bbede6b4d46c15ae&fileName=fire%20inspection%20requirements%20FD1%209-24-25.pdf","label":"Official source (oceantwp.qscendcms.com)"},{"url":"https://www.oceantwp.org/p/housing-forms-1","label":"Official source (oceantwp.org)"},{"url":"https://ecode360.com/35335759","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35335884","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The owner/seller or realtor must contact the Fire Marshal's Office at (732) 222-2624 to schedule$t$, $t$0772b03eeb5720fd7433febcd7a468afa79e00a4b1132b2be45d4f8406c2bc38$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":14,"fee_ok":1,"fee_bad":0,"fee_unchecked":13,"quotes":20,"q_ok":11,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/1337.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1337.json$t$, true),
  ($t$1338$t$, $t$Oceanport Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Rental/Resale/New Tenant Certificate (resale certificate)$t$, $j$["Issued by: Borough of Oceanport Housing Inspector (Code Enforcement)","Contact: Timothy P. Griffin, Housing Inspector / Code Enforcement (also Fire Official) · 732-222-8221 · codeenforcement@oceanportboro.com","Apply: The certificate is granted or denied within 21 days of the application. Open permits or violations must be resolved before an inspection is scheduled. An expedited certificate is available for $125 where eligible.","How to apply: Apply online with the Borough's Rental/Resale (Real Estate) Certificate Application on the SDL portal and pay the fee at application. Resolve any open permits with the Construction Department first. Separately apply for the Smoke/CO certificate from the Fire Official (also on the SDL portal); the resale certificate is not issued until the fire certificate is secured. Borough Hall: 910 Oceanport Way, (732) 222-8221.","Inspection by the Housing Inspector for compliance with Borough zoning and property maintenance laws, site plans, building permits and Tax Assessor records","Smoke/CO certificate from the Fire Official must be secured before the resale certificate is issued","All permits must be closed before the inspection","All utilities on; grass cut; exterior in good condition; house numbers at least 3 inches","Smoke detector in every sleeping room, within 10 feet of each sleeping area and on each floor; hardwired units no older than 10 years, battery units 10-year sealed","CO detector within 10 feet of each sleeping area","Fire extinguisher 2A10BC in the kitchen with receipt or third-party inspection (checklist still lists it)","GFCI outlets near water and outside; handrails on steps over 3 risers; solid core or fire rated door from attached garage","Also: Open permits and violations: Open construction permits and outstanding violations must be resolved before the resale certificate application and inspection.","Also: Zoning and records match: The resale certificate verifies the property matches Borough zoning, site plans, building permits and Tax Assessor records."]$j$::jsonb, $j$[{"label":"Resale or transfer of ownership certificate","amount":"$65"},{"label":"Reinspection, each time","amount":"$50"},{"label":"Eligible expedited certificate","amount":"$125"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/oceanport/requests/certificate?rq=1$t$, $t$https://www.oceanportboro.com/departments/code$t$, $j$[{"url":"https://www.oceanportboro.com/departments/code","label":"Official source (oceanportboro.com)"},{"url":"https://ecode360.com/45429899","label":"Official source (ecode360.com)"},{"url":"https://www.oceanportboro.com/media/attachments/2021/06/01/housing-inspection-check-list.pdf","label":"Official source (oceanportboro.com)"},{"url":"https://www.oceanportboro.com/government/directory","label":"Official source (oceanportboro.com)"},{"url":"https://ecode360.com/45429930","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$All dwellings or commercial buildings being offered for resale in the Borough of Oceanport must be inspected and approved by the Housing Inspector/Construction Official.$t$, $t$c156a216ed38ad1c8c7198784647863162b4cb5d559e1c60f40e9ba5c704a88d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1338.json$t$, true),
  ($t$1338$t$, $t$Oceanport Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Oceanport Bureau of Fire Prevention (Fire Official / Fire Marshal) (town fire bureau)","Contact: Timothy P. Griffin, Fire Marshal / Fire Official · 732-222-8221 · tgriffin@oceanportboro.com","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lowest fee.","How to apply: Apply online with the Smoke/CO Certificate Application on the Borough's SDL portal. All sales and rentals must apply for a Smoke/CO certificate inspection by the Fire Official. An extension form is posted on the Fire Prevention page.","Fire official in the NJ state directory, updated 7/1/2026: Timothy P Griffin · (732) 222-8221 · tgriffin@oceanportboro.com","Ten-year sealed battery smoke alarms (or existing A/C powered alarms) for any residential property transfer; combination smoke/CO units included","Smoke detector in every sleeping room, within 10 feet of each sleeping area and on each floor (Borough checklist)","CO detector within 10 feet of each sleeping area","Portable fire extinguisher 2A-10B:C, 10 lb or less, within 10 feet of the kitchen, serviced and tagged within 12 months or with a purchase receipt (Borough pages and checklist still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), request more than 10 business days before change of occupant","amount":"$45"},{"label":"Request four to 10 business days before","amount":"$90"},{"label":"Request fewer than four business days before","amount":"$161"},{"label":"Reinspection","amount":"$35"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/oceanport/requests/smokeAlarm$t$, $t$https://www.oceanportboro.com/departments/fire-prevention$t$, $j$[{"url":"https://www.oceanportboro.com/departments/fire-prevention","label":"Official source (oceanportboro.com)"},{"url":"https://ecode360.com/45429899","label":"Official source (ecode360.com)"},{"url":"https://www.oceanportboro.com/departments/code","label":"Official source (oceanportboro.com)"},{"url":"https://www.oceanportboro.com/government/directory","label":"Official source (oceanportboro.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/11274750","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Effective October 18, 2021 ALL Sales/rentals shall be required to apply for a Smoke/CO certificate inspection by the Fire Official.$t$, $t$3f0e012828ae40f6a6c306e9e2dbb593b30aca0403f0b96736912a83d1683c51$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1338.json$t$, true),
  ($t$1339$t$, $t$Red Bank Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy on sale or transfer (Property Maintenance Code Section 102.1A); not required for owner-occupied single-family sales$t$, $j$["Issued by: Borough of Red Bank Department of Code Enforcement (Fire Marshal's Office)","Contact: James E Fenn, Fire Marshal · 732-530-2764 · jfenn@redbanknj.org","Apply: The owner must give at least 14 calendar days notice to Code Enforcement for the compliance inspection.","How to apply: Contact the Fire Marshal's Office / Code Enforcement at 90 Monmouth Street, 3rd Floor (732-530-2764, Monday to Friday 8 a.m. to 4 p.m.) at least 14 calendar days before the transfer. Applications with checks can be left in the drop box outside the office. Close any open permits first. No online C.O. application was found.","Valid for: A certificate issued within the prior six months can be reused (a copy of the prior certificate suffices).","Applies to the sale or transfer of 2-family homes and of single-family homes that will not be owner-occupied; owner-occupied single-family sales need only the smoke/CO certificate","Compliance inspection under the International Property Maintenance Code (address numbers at least 4 inches, no double cylinder locks, heating and water heater safety, garage fire door, floors, roof, range, plumbing)","All open permits must have a final inspection before a C.O. can be issued","Smoke and carbon monoxide certificate (CSDCMAC)","A conditional C.O. may be issued for owner-occupied 2- or 3-unit buildings if all defects are disclosed to the buyer and conditions are met","Also: Open permits: All open permits must have a final inspection before a C.O. can be issued."]$j$::jsonb, $j$[{"label":"C.O. on sale or transfer, one- or two-family dwelling (per dwelling unit)","amount":"$100"},{"label":"Reinspection after second reinspection and failure, residential","amount":"$50"}]$j$::jsonb, null, $t$https://www.redbanknj.org/183/Fire-Marshals-Office$t$, $j$[{"url":"https://ecode360.com/14163455","label":"Official source (ecode360.com)"},{"url":"https://www.redbanknj.org/DocumentCenter/View/9339/2019-04-Final","label":"Official source (redbanknj.org)"},{"url":"https://www.redbanknj.org/DocumentCenter/View/17726/2026---Fire-Marshals-Office-Certificate-of-Ocupancy-Check-List-IPMC","label":"Official source (redbanknj.org)"},{"url":"https://www.redbanknj.org/DocumentCenter/View/17730/2026---Fire-Marshals-Office-CO-and-Smoke-Inspection-Requirements","label":"Official source (redbanknj.org)"},{"url":"https://www.redbanknj.org/directory.aspx?did=9","label":"Official source (redbanknj.org)"}]$j$::jsonb, $t$This Section 102.1A shall not apply to the sale or transfer of single-family dwellings that are owner-occupied or to be owner-occupied upon sale or transfer.$t$, $t$3f9f9f431697f7ce2bba2f68e186959a5f9f0d5496e5f6783ade6dc95c9fa1ef$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1339.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1339.json$t$, true),
  ($t$1339$t$, $t$Red Bank Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Red Bank Fire Marshal's Office (Fire Prevention) (town fire bureau)","Contact: James E Fenn, Fire Marshal · 732-530-2764 · jfenn@redbanknj.org","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lowest fee. Inspections are done 10 a.m. to 2 p.m., Monday to Friday.","How to apply: Apply to the Fire Marshal's Office, 90 Monmouth Street, 3rd Floor, Red Bank (732-530-2764), Monday to Friday 8:00 a.m. to 4:00 p.m.; applications with checks (no cash) can go in the drop box outside the office door. The 2026 smoke and CO inspection requirements are posted on the Fire Marshal's Office page.","Fire official in the NJ state directory (town), updated 6/24/2026: James Fenn · (732) 530-2748 · jfenn@redbanknj.org","Ten-year sealed battery smoke alarms or A/C powered hardwired smoke detectors in each bedroom and on each level within ten feet of the bedrooms (basement, first floor, second floor), excluding crawl spaces and unfinished attics","Smoke detectors properly mounted (ceiling at least 4 inches from the wall; wall mount 4 to 12 inches from the ceiling), UL listed with a test button; A/C powered alarms may not be replaced with battery units","Carbon monoxide alarm on each level within ten feet of the bedrooms (battery, plug-in or part of a central station system), UL listed","Central station fire alarms need a letter from the monitoring company that the system works","An adult (18 or older) must be present; pets secured","Fire extinguisher no longer required (Fire Marshal's 2026 handout, citing the February 2025 change)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSDCMAC, request more than 10 business days before change of occupant","amount":"$100"},{"label":"Request four to 10 business days before","amount":"$125"},{"label":"Request fewer than four business days before","amount":"$150"}]$j$::jsonb, null, $t$https://www.redbanknj.org/183/Fire-Marshals-Office$t$, $j$[{"url":"https://www.redbanknj.org/DocumentCenter/View/17730/2026---Fire-Marshals-Office-CO-and-Smoke-Inspection-Requirements","label":"Official source (redbanknj.org)"},{"url":"https://www.redbanknj.org/DocumentCenter/View/9339/2019-04-Final","label":"Official source (redbanknj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/33067147","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$INSPECTION REQUIREMENTS for Certificate of Smoke Detector & Carbon Monoxide$t$, $t$da5a2f7d99ca6aa0050d3246add80a93c8e5e7f79d94760c57fb0abb0e153354$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1339.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1339.json$t$, true),
  ($t$1340$t$, $t$Roosevelt Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (resale)$t$, $j$["Issued by: Borough of Roosevelt Housing Inspector (Zoning Officer / Housing Inspector)","Contact: Jeremy Kuipers, Zoning Officer & Housing Inspector · 609-448-0539","Apply: The Housing Inspector grants or denies the C/O within 10 days of the application. The inspector keeps limited evening hours (normally Monday office hours 5 to 6 p.m. and inspections 6 to 7 p.m.; temporarily Tuesdays from 9/21/26 to 11/19/26).","How to apply: Complete the Borough's Certificate of Occupancy form (mark RESALE, give the approximate closing date) and submit it with a $115.00 check payable to Borough of Roosevelt at Borough Hall, 33 N. Rochdale Avenue (P.O. Box 128), Roosevelt, NJ 08555, 609-448-0539. Contact the Housing Inspector during his evening office hours to schedule.","Valid for: The inspection can be waived if the building was inspected within six months before the change in occupancy.","Visual inspection under the International Property Maintenance Code: no garbage, sidewalk and driveway in good repair, house number at least 6 inches, grass under 6 inches, exterior in good repair","Interior: no peeling paint, secure handrails, working windows and doors with screens, GFI outlets within 6 feet of sinks, working heating and cooking equipment, stove anti-tip bracket","Smoke detectors on each level and outside each sleeping area (10-year battery if battery powered); carbon monoxide detector near each sleeping area","Fire extinguisher 2A10BC, 10 lb max, mounted near the kitchen with an inspection date within 1 year (form still lists it)","Chimney certification by a certified chimney sweep for wood-burning fireplaces","Applicant certifies the dwelling complies with municipal ordinances and health and safety codes","Also: Chimney certification: Wood-burning fireplaces need a chimney certification from a certified chimney sweep for the C/O.","Also: Buyer repair certification: On a transfer of title the buyer can certify repairs will be completed within 90 days, and the C/O is issued; failure to finish is a violation."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy application and one inspection","amount":"$100"},{"label":"Filing fee (in addition)","amount":"$15"},{"label":"Reinspection, each","amount":"$10"},{"label":"Certificate of Occupancy, total on Borough form","amount":"$115.00"}]$j$::jsonb, $t$https://casite-785122.cloudaccess.net/images/forms/co-inspection-application.pdf$t$, $t$https://www.rooseveltnj.us/departments/zoning-officer-housing-inspector$t$, $j$[{"url":"https://ecode360.com/35766163","label":"Official source (ecode360.com)"},{"url":"https://casite-785122.cloudaccess.net/images/forms/co-inspection-application.pdf","label":"Official source (casite-785122.cloudaccess.net)"},{"url":"https://www.rooseveltnj.us/departments/zoning-officer-housing-inspector","label":"Official source (rooseveltnj.us)"}]$j$::jsonb, $t$No person shall sell, transfer, assign, rent, lease or sublet to another, or suffer or permit any change in occupancy of use of any building or a part thereof, without first obtaining from the Housing Inspector a Certificate of Occupancy stating that, at the time of the proposed sale transfer, assignment, rental, lease or subletting by such other persons, the premises comply with all ordinances of the Borough of Roosevelt.$t$, $t$1045ed45a4009c9189b51731c7cec06468c1d2f944ed1e1974f62fea128a2b81$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":3,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":3,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1340.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1340.json$t$, true),
  ($t$1340$t$, $t$Roosevelt Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety (state-enforced; State LEA for Roosevelt) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official of record for Roosevelt (NJ Division of Fire Safety), per the state directory · 609-633-6132","Apply: State fee tiers count business days before the change of occupant: more than 10 business days for the lowest fee.","How to apply: Apply online through the NJ DCA Fire Safety Service Portal (firesolutions.dca.nj.gov): choose Apply for Smoke Certification, enter the property and closing details and pay. Questions: 609-633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 7/1/2026: Louis Kilmer · (609)633-6132","Smoke alarms on each level and outside each separate sleeping area (N.J.A.C. 5:70-4.19); battery units 10-year sealed","Carbon monoxide alarm near the sleeping areas in homes with a fuel-burning appliance or attached garage","The Borough C/O form also lists a fire extinguisher; the state dropped it from the sale certificate in February 2025 (P.L.2025, c.19)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State smoke/CO certificate (N.J.A.C. 5:70-2.9(d)), received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Received four to 10 business days before","amount":"$90.00"},{"label":"Received fewer than four business days before","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/$t$, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/first-time-user-guide/$t$, $j$[{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/first-time-user-guide/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Click Apply for Smoke Certification$t$, $t$d4422ed2e3f5fff6791a2ab055f52e1596133c1d4c08d07b9f404c751ac9ba27$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":3,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":3,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1340.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1340.json$t$, true),
  ($t$1342$t$, $t$Sea Bright Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy on resale (Residential, sale)$t$, $j$["Issued by: Borough of Sea Bright Code Enforcement Officer (C. O. Inspector)","Contact: Thomas Haege, Fire Marshal, Construction Official, Fire Subcode Official, C. O. Inspector and Code Enforcement Officer · 732-842-0099 Ext. 130 · thaege@seabrightnj.org","How to apply: Get the certificate of occupancy application from the Borough (forms are kept at the office of the Borough Clerk, Borough Hall, 1099 Ocean Avenue) and file it with the $100 fee. The Code Enforcement Officer inspects the home. No online form is posted on the Borough website; call the office to schedule.","Valid for: The certificate applies only to the occupancy for which it is issued. No new fee is charged for an inspection within three months of a previous paid application for the same unit.","Inspection showing the dwelling is fit for human habitation under the New Jersey State Housing Code and complies with all other Borough ordinances","Dwelling must meet the Borough occupancy standards (minimum floor area per occupant and per sleeping room)","Fee paid to the Borough Clerk when the application is filed; not refundable","Smoke alarm / carbon monoxide alarm certificate for the sale (see fire certificate)"]$j$::jsonb, $j$[{"label":"Certificate of occupancy, residential sale","amount":"$100"},{"label":"Certificate of occupancy reinspection, each","amount":"$25"}]$j$::jsonb, null, $t$https://www.seabrightnj.org/sbnj/Departments/Building%20Department/$t$, $j$[{"url":"https://ecode360.com/8056032","label":"Official source (ecode360.com)"},{"url":"https://www.seabrightnj.org/sbnj/Departments/Borough%20Directory/","label":"Official source (seabrightnj.org)"}]$j$::jsonb, $t$Certificates of occupancy required upon resale of existing homes for which a certificate of occupancy has previously been issued or required upon rental of homes or individual apartment units for which a certificate of occupancy has previously been issued shall be issued upon application to the Code Enforcement Officer.$t$, $t$3f65b2e789657c68e0c7d30ec9cf7e87244e9c7ab002e2db05c02fbaf185d9b8$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":3,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1342.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1342.json$t$, true),
  ($t$1342$t$, $t$Sea Bright Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Sea Bright Bureau of Fire Prevention (Office of the Fire Marshal) (town fire bureau)","Contact: Thomas Haege, Fire Marshal · 732-842-0099 Ext. 130 · thaege@seabrightnj.org","How to apply: No online application or fee schedule is posted. Contact the Fire Marshal at Borough Hall, 1099 Ocean Avenue (732-842-0099 Ext. 130) to request the smoke and carbon monoxide alarm certificate inspection.","Fire official in the NJ state directory (town), updated 9/9/2013: Tom Haege · (732) 842-0099 · thaege.otfm@verizon.net","Smoke alarms, carbon monoxide alarms and fire extinguisher per N.J.A.C. 5:70-2.3; the Borough publishes no local checklist","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.seabrightnj.org/sbnj/Departments/Borough%20Directory/$t$, $j$[{"url":"https://ecode360.com/8055801","label":"Official source (ecode360.com)"},{"url":"https://www.seabrightnj.org/sbnj/Departments/Borough%20Directory/","label":"Official source (seabrightnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Office of the Sea Bright Fire Marshal shall enforce this article. The local enforcing agency shall be the Bureau of Fire Prevention for the Borough of Sea Bright which is hereby created.$t$, $t$adc45efabc7bb8f3413e2152e4bff6ed64bbde4460bf5e6e6c1b85e1c457a904$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":3,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1342.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1342.json$t$, true),
  ($t$1343$t$, $t$Sea Girt Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Sale (Certificate of Occupancy / CCO on sale)$t$, $j$["Issued by: Borough of Sea Girt Zoning and Code Enforcement (Code Official)","Contact: Chris Willms, Code Enforcement / Zoning · (732) 449-9433 ext. 118","How to apply: Apply online with the Borough's Sale and Rental Certificate application on GovPilot (paper applications are no longer accepted). Give the property, owner, agent and new occupant details, the closing (occupancy) date and the inspection contact, and pay the fee. The Code Enforcement office is on the 2nd floor of Borough Hall, 321 Baltimore Blvd.","On-site inspection of the home by the Code Official before any sale or transfer","Sidewalks, steps, driveways and similar paved areas must be in a proper state of repair before the sale","Inspection checklist covers the exterior (property clean and orderly, siding, roofing, windows, screens, handrails, decks, gutters, house number visible) and the interior (smoke and CO alarms, GFI outlets, plumbing, electrical, bedroom egress windows and doors, water heater relief valve, dryer venting)","Bedroom occupancy limits: 70 sq ft for 1 occupant, 100 for 2, 150 for 3, 200 for 4","Applicant certifies the home and other structures meet Sea Girt zoning and that no rubbish, debris or bulk garbage will be left before the new occupancy","Smoke alarm / CO alarm certificate (CSACMAPFEC) for the sale, charged separately (see fire certificate)","Also: Sidewalks, steps and driveways: No residential property may be sold unless its sidewalks, steps, driveways and similar paved areas are in a proper state of repair; this is checked at the certificate inspection."]$j$::jsonb, $j$[{"label":"Certificate of occupancy inspection and issuance on sale, transfer or lease","amount":"$100"},{"label":"Certificate of occupancy reinspection, each","amount":"$50"},{"label":"Sale certificate application fee (online form fee schedule)","amount":"$100"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/1222558b-a2f_CCO-Landlord-Application-seagirt?uid=7257&ust=NJ&pu=1&id=0$t$, $t$https://www.seagirt-nj.gov/zoning-and-code-enforcement$t$, $j$[{"url":"https://ecode360.com/36176356","label":"Official source (ecode360.com)"},{"url":"https://www.seagirt-nj.gov/zoning-and-code-enforcement","label":"Official source (seagirt-nj.gov)"},{"url":"https://www.seagirt-nj.gov/zoning-and-code-enforcement/pages/zoning-code-applicationspermits","label":"Official source (seagirt-nj.gov)"},{"url":"https://main.govpilot.com/web/public/1222558b-a2f_CCO-Landlord-Application-seagirt?uid=7257&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.seagirt-nj.gov/sites/g/files/vyhlif3791/f/uploads/updated_certificate_requirements.pdf","label":"Official source (seagirt-nj.gov)"}]$j$::jsonb, $t$A certificate of occupancy issued by the Borough Code Official will be required prior to any sale, transfer, or leasing of such property, which will be issued only after satisfactory on-site inspection of the premises by the Code Official.$t$, $t$cbbc0103a251a62f1d29c742e512edfb171fb6b151d135896d6b090d7ad3e842$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":1,"fee_bad":0,"fee_unchecked":7,"quotes":14,"q_ok":6,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1343.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1343.json$t$, true),
  ($t$1343$t$, $t$Sea Girt Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Sea Girt Fire Prevention Bureau (Borough of Sea Girt Code Enforcement / Fire Official) (town fire bureau)","Contact: Christopher Willms, Fire Official (state fire directory); Code Enforcement / Zoning (Borough page) · (732) 449-9433 ext. 118 · cwillms@seagirtboro.com","Apply: Fee depends on how many days before occupancy (closing) the application is filed: 10 or more days for the lowest fee.","How to apply: Request it with the Borough's online Sale and Rental Certificate application on GovPilot (the form collects the CO detector details and occupancy date), and pay the fee. Each reinspection is requested and paid separately.","Fire official in the NJ state directory, updated 8/5/2026: Christopher Willms · (732) 449-9433 · cwillms@seagirtboro.com","All smoke alarms tested by push button; homes built before 1978 need at least battery alarms on each level; 1978 to 1983 hardwired with battery backup on each level; 1984 to 1990 also interconnected; 1991 and later also one in each bedroom","Battery-only smoke alarms must be 10-year sealed units; alarms more than 10 years old are not accepted","If the home has a monitored alarm system, a letter from the owner, agent or monitoring company saying it is maintained and works","Carbon monoxide alarms outside each separate sleeping area where there are fuel burning appliances or an attached garage; not older than 5 years or past the maker's expiration date","Fire extinguisher, minimum 2A:10B:C, within 10 feet of the kitchen, mounted in the exit path and serviced within 12 months or newly bought (2018 guidelines still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSACMAPFEC, application filed 10 or more days before occupancy","amount":"$100"},{"label":"Application filed less than 10 and more than 5 days before occupancy","amount":"$150"},{"label":"Application filed less than 5 and more than 2 days before occupancy","amount":"$200"},{"label":"Application filed less than 2 days before occupancy","amount":"$250"},{"label":"Reinspection or missed appointment, each","amount":"$50"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/1222558b-a2f_CCO-Landlord-Application-seagirt?uid=7257&ust=NJ&pu=1&id=0$t$, $t$https://www.seagirt-nj.gov/zoning-and-code-enforcement$t$, $j$[{"url":"https://ecode360.com/36182038","label":"Official source (ecode360.com)"},{"url":"https://www.seagirt-nj.gov/sites/g/files/vyhlif3791/f/uploads/updated_certificate_requirements.pdf","label":"Official source (seagirt-nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The fee for any CSACMAPFEC and issuance of a certificate, as required by N.J.A.C. 5:70-2.3, will be indexed to the scheduled inspection date as it relates to the anticipated contract closing date as follows:$t$, $t$5c1881cd089a2351870116fff011807a554075e3badb1a98e22618bb6b52994f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":1,"fee_bad":0,"fee_unchecked":7,"quotes":14,"q_ok":6,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1343.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1343.json$t$, true),
  ($t$1345$t$, $t$Shrewsbury Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale MCCO Certificate (Municipal Certificate of Occupancy)$t$, $j$["Issued by: Shrewsbury Township Code Enforcement / Housing Department","Contact: David Boehing, Code Enforcement/Housing Department · 732-542-0572 · DBoehing@townshipofshrewsbury.com","Apply: Inspections are scheduled within ten calendar days and on a weekend; allow enough time between the inspection and the move-in date.","How to apply: Fill out the Township's Application for Resale MCCO Certificate (circle Resale), list the bedrooms and everyone who will live there, request an inspection date, and pay $100.00 by cash or check payable to Township of Shrewsbury at the Municipal Office, 1979 Crawford Street (open Monday to Thursday, 9 a.m. to 5 p.m.).","Valid for: 60 days from an approved inspection","Interior and exterior inspection by Township Code Enforcement","New or currently tagged 2A10BC fire extinguisher mounted in the kitchen (checklist still lists it)","Smoke detectors and CO detector","GFCI outlets at sinks, washing machines and bathrooms","Tip guard for the oven/stove","No open wiring; no holes in walls, ceilings or floors; no cracked or broken windows","Screens in all windows; handrails on interior and exterior stairs; working interior doors","Property overgrowth cleared","Heating and venting inspection current within 1 year","Application lists the number of bedrooms and the names of everyone who will occupy the unit","Also: Heating and venting inspection: A heating and venting inspection current within one year is on the Township's certificate of occupancy checklist."]$j$::jsonb, $j$[{"label":"Certificate of occupancy on sale, one or two family dwelling, per dwelling unit","amount":"$100.00"},{"label":"Reinspection after the second failed reinspection, residential","amount":"$75.00"},{"label":"Resale MCCO application fee (application form)","amount":"$100.00"}]$j$::jsonb, $t$https://www.townshipofshrewsbury.com/uploads/3/4/2/9/34299549/updatedcertificatecodeenforcement26.pdf$t$, $t$https://www.townshipofshrewsbury.com/departments.html$t$, $j$[{"url":"https://www.townshipofshrewsbury.com/uploads/3/4/2/9/34299549/2023_-03_ordinance_-_certificates_of_occupancy.pdf","label":"Official source (townshipofshrewsbury.com)"},{"url":"https://www.townshipofshrewsbury.com/uploads/3/4/2/9/34299549/updatedcertificatecodeenforcement26.pdf","label":"Official source (townshipofshrewsbury.com)"},{"url":"https://www.townshipofshrewsbury.com/uploads/3/4/2/9/34299549/certificate_of_occupancy_checklist.pdf","label":"Official source (townshipofshrewsbury.com)"},{"url":"https://www.townshipofshrewsbury.com/departments.html","label":"Official source (townshipofshrewsbury.com)"},{"url":"https://www.townshipofshrewsbury.com/index.html","label":"Official source (townshipofshrewsbury.com)"}]$j$::jsonb, $t$Inspection Fee Schedule for a Certificate of Occupancy upon the Sale, Transfer, Mortgage, Lease or otherwise disposed of shall be as follows:$t$, $t$5a4fd0618273249cb951c7ede1db8ea62d7da9c8be69826d1a0c0230b6be6584$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1345.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1345.json$t$, true),
  ($t$1345$t$, $t$Shrewsbury Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Shrewsbury Township Fire Marshal / Code Enforcement (Shrewsbury Twp Code Enf) (town fire bureau)","Contact: David Boehing, Fire Marshal · 732-542-0572 · DBoehing@townshipofshrewsbury.com","How to apply: No separate smoke/CO certificate application or fee is posted. The Township's resale MCCO checklist includes smoke detectors, the CO detector and the fire extinguisher; call the Municipal Office (732-542-0572) to confirm whether a separate smoke/CO certificate is issued and what it costs.","Fire official in the NJ state directory (town), updated 2/9/2026: David Boehnig · (732) 741-4200","Smoke detectors, CO detector and a new or currently tagged 2A10BC kitchen fire extinguisher are checked on the Township's certificate of occupancy checklist (form still lists the extinguisher)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.townshipofshrewsbury.com/departments.html$t$, $j$[{"url":"https://www.townshipofshrewsbury.com/departments.html","label":"Official source (townshipofshrewsbury.com)"},{"url":"https://www.townshipofshrewsbury.com/uploads/3/4/2/9/34299549/certificate_of_occupancy_checklist.pdf","label":"Official source (townshipofshrewsbury.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Marshal$t$, $t$49c8e0fae17b00f2776af6fb58baf1e8ac74492a27367ce67cf12752b02937df$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1345.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1345.json$t$, true),
  ($t$1346$t$, $t$Lake Como Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Inspection (CI), Sale of Property$t$, $j$["Issued by: Borough of Lake Como Code Enforcement Officer","Contact: Frank Cinelli, Code Enforcement Office (Code Enforcement Assistant: Dawn Dayton, ddayton@lakecomonj.org) · 732-681-3232 · fcinelli@lakecomonj.org","Apply: Submit the form and fee at least 7 days before the desired inspection date (sale form).","How to apply: Download the 'Application for the Sale of Property' from the Building & Code Dept page, complete it with the owner, buyer and closing date, and submit it with a check or cash for $120.00 at least 7 days before the inspection date to the Code Enforcement office, Lake Como Borough Hall, 1740 Main Street, Lake Como, NJ 07719.","Residential Certificate of Inspection Form, Sale of Property, signed by the owner or agent and the buyer or agent, with the closing date","Inspection by the Code Enforcement Officer; no certificate is issued while violations exist","Someone must be present to give the inspector entry","The home must comply with all other Borough ordinances and requirements"]$j$::jsonb, $j$[{"label":"Certificate of Inspection, sale or transfer of title of each dwelling (Code 9-4.8a)","amount":"$120"},{"label":"Second (complete) inspection, per dwelling (Code 9-4.8c)","amount":"$250"},{"label":"Each reinspection after the first and second, per dwelling (Code 9-4.8d)","amount":"$500"},{"label":"Sale of property inspection form fee","amount":"$120.00"}]$j$::jsonb, $t$https://lakecomonj.org/useruploads//Sale_of_Property_Inspection_Form.pdf$t$, $t$https://lakecomonj.org/home/page/9$t$, $j$[{"url":"https://lakecomonj.org/home/page/9","label":"Official source (lakecomonj.org)"},{"url":"https://lakecomonj.org/useruploads//Sale_of_Property_Inspection_Form.pdf","label":"Official source (lakecomonj.org)"},{"url":"https://ecode360.com/34658523","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/34677147","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$NOTE: A Certificate of Inspection (CI) is required for all property Sales & Rentals in the Borough of Lake Como.$t$, $t$fa0d534dd67a04b442def1655ebe48661d34879738085b52e46029ad81eef7d3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":12,"q_ok":6,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1346.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1346.json$t$, true),
  ($t$1346$t$, $t$Lake Como Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Belmar Bureau of Fire Prevention (local enforcing agency for Lake Como) (town fire bureau)","Contact: Edward Ratyniak, Fire Marshal · 732-681-3700 x 239 · firemarshal@belmar.com","How to apply: Contact the Belmar Fire Prevention office (Fire Marshal Edward Ratyniak) at 732.681.3700 x 239 to request the smoke/CO certificate for a Lake Como sale. No Lake Como or Belmar application form or fee for this certificate was found online.","Fire official in the NJ state directory (town), updated n/a: Edward Ratyniak · (732) 681-3232 · firemarshal@belmar.com","Smoke detectors on each floor and the basement, UL listed (Code 16-6.8)","Carbon monoxide detectors in homes with fuel-burning appliances or an attached garage, one per sleeping area (Code 16-6.8)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.belmar.com/departments/fire-prevention$t$, $j$[{"url":"https://ecode360.com/34659289","label":"Official source (ecode360.com)"},{"url":"https://www.belmar.com/departments/fire-prevention","label":"Official source (belmar.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The local enforcing agency shall be the Borough of Belmar Bureau of Fire Prevention ("Bureau of Fire Prevention").$t$, $t$dbe4f82701b0a5bb9e89189cc55e478d15e64760a11875294d458033f512882e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":12,"q_ok":6,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1346.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1346.json$t$, true),
  ($t$1347$t$, $t$Spring Lake Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection Permitting Occupancy (Sale Certificate of Occupancy)$t$, $j$["Issued by: Borough of Spring Lake Code Enforcement Officer","Contact: Frank Cinelli, Code Enforcement Officer · (732) 449-0800 ext. 613 · codeenforcement@springlakeboro.org","Apply: Inspections are scheduled only after payment; the Code Enforcement Officer needs 48 hours notice and same day appointments are not offered.","How to apply: Apply online through the Borough's SDL portal (create an SDL account and select the Borough of Spring Lake). Once the application is complete, a payment request is emailed; pay online or drop off a check payable to Borough of Spring Lake at Borough Hall, 423 Warren Avenue. After payment the office emails the inspection date and time. Review the Sale and Rental Inspection Checklist before the inspection.","Inspection by the Code Enforcement Officer before transfer of title or occupancy; title may transfer first, but no occupancy until all items marked for correction are completed","Application lists the seller, buyer and new occupants and the number of persons who will occupy the home; each adult occupant signs an affidavit","Sale and rental checklist: fire extinguisher (2A:10B:C within 10 feet of the kitchen, checklist still lists it), smoke and CO detectors in the basement and on every floor near bedrooms, house number at least 3 inches visible from the street","Utilities on; appliances and bathroom fixtures clean and working; walls and trim repaired and painted; windows operable with locks and screens; keyless interior deadbolts; handrails on stairs with 2 or more risers","Sump pumps may not discharge into the sewer system","Sidewalks in good repair with no trip hazards; exterior clean and safe; proper garbage containers stored at the side or rear","Home must comply with all other Borough ordinances","Also: Sidewalks: Sidewalks must be in good repair with no trip hazards; checked at the sale inspection.","Also: Sump pump discharge: Sump pumps may not discharge into the sewer system; checked at the sale inspection."]$j$::jsonb, $j$[{"label":"Sale certificate, house up to four bedrooms (raised from $100 by Ord. 2026-003)","amount":"$150"},{"label":"Sale certificate, house with more than four bedrooms (raised from $150 by Ord. 2026-003)","amount":"$200"},{"label":"Reinspection","amount":"$25"},{"label":"GIS update fee charged when the certificate is issued","amount":"$20"}]$j$::jsonb, $t$https://www.sdlportal.com/$t$, $t$https://springlakeboro.org/departments/code-enforcement$t$, $j$[{"url":"https://springlakeboro.org/departments/code-enforcement","label":"Official source (springlakeboro.org)"},{"url":"https://ecode360.com/8207576","label":"Official source (ecode360.com)"},{"url":"https://springlakeboro.org/government/forms/code-enforcement/835-certificate-of-occupancy-process-rental-rules-procedures/file","label":"Official source (springlakeboro.org)"},{"url":"https://springlakeboro.org/government/forms/code-enforcement/674-sales-renal-inspection-checklist/file","label":"Official source (springlakeboro.org)"}]$j$::jsonb, $t$The Borough Code Enforcement Officer and is responsible for the investigation of complaints and the enforcement of the Borough's zoning and property maintenance laws and regulations, as well as the issuance of Certificates of Occupancy for property sales or rentals.$t$, $t$441518ee613d05c2558356572185912a76a2ae20cd109f5b9c68a48e063848f7$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1347.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1347.json$t$, true),
  ($t$1347$t$, $t$Spring Lake Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Sea Girt Borough Fire Prevention (fire code enforcing agency for Spring Lake under a shared service); smoke/CO items are also checked at the Spring Lake sale inspection (town fire bureau)","Contact: Christopher Willms, Fire Official (state fire directory) · (732) 449-0800 ext. 613 · cwillms@seagirtboro.com","How to apply: No separate smoke/CO certificate application or fee is posted by Spring Lake. The Borough's sale inspection checklist covers smoke and CO detectors and the extinguisher. Call Spring Lake Code Enforcement (732-449-0800 ext. 613) to confirm whether a separate smoke/CO certificate from the Sea Girt fire official is needed and what it costs.","Fire official in the NJ state directory (town), updated 2/13/2023: Christopher Willms · (732) 681-3700 · cwillms@seagirtboro.com","Fire extinguisher, minimum 2A:10B:C, within 10 feet of the kitchen and clearly visible (Borough checklist still lists it)","Carbon monoxide and smoke detectors in the basement and on every floor near the bedrooms","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://springlakeboro.org/departments/code-enforcement$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://springlakeboro.org/government/forms/code-enforcement/674-sales-renal-inspection-checklist/file","label":"Official source (springlakeboro.org)"}]$j$::jsonb, $t$Sea Girt Borough is the LEA for Brielle Borough & Spring Lake Boro$t$, $t$f2a7632600fe7a87a5abcc68c6ad172998a5645fa5a7273210880c85c95ae938$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1347.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1347.json$t$, true),
  ($t$1348$t$, $t$Spring Lake Heights Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection for Transfer of Title (Certificate of Occupancy on sale)$t$, $j$["Issued by: Borough of Spring Lake Heights Zoning / Code Enforcement Officer (Public Officer)","Contact: Barbara Van Wagner, Zoning / Code Enforcement Officer · 732-449-3500 · code@springlakehts.com","Apply: The Borough code adds a surcharge when the application is filed less than 10 calendar days before occupancy.","How to apply: Fill out the Borough's 2026 Certificate of Inspection Application (Rental and Transfer of Title), including the signed smoke detector and carbon monoxide alarm certification, and file it with the fee at the Municipal Building, 555 Brighton Avenue (Zoning/Code Enforcement office hours Monday and Wednesday, 9:00 AM to 4:30 PM). Fees are non-refundable and non-transferable.","Inspection of the home before transfer of title or occupancy","Signed owner certification that smoke and CO alarms are installed and working, plus the smoke/CO inspection (see fire certificate)","Exterior: roof, gutters, siding, fences, windows, screens and doors in good condition; handrails on stairs with three or more risers; guardrail gaps no more than 5 inches; house number at least 3 inches visible from the street; no debris","Driveway must have an apron and a paved, brick, paver or stone surface; sidewalk, curb, driveway and apron free of cracks, trip hazards or standing water","No open construction permits; all work done during ownership must have been permitted and passed final inspection","Municipal taxes, water and sewer should be paid up to date","Interior: no bedrooms in basements or more than 2 feet below grade; bedroom size minimums; GFI outlets within 6 feet of water; stove anti-tip bracket and gas shut off valves; emergency furnace switch; keyless interior deadbolts; no sump pump discharge into the sewer","Wood burning fireplaces and stoves certified by a certified chimney sweep company","Secondary power source warning label within 18 inches of the electric panel and meter for homes with a generator, solar or battery storage (P.L.2025, c.19)","Zoning permit also required for transfer of title of anything other than a single family home","Application lists sale price, closing and occupancy dates, buyer and all occupants with dates of birth","Also: Sidewalk, curb, driveway and apron: Must be in good condition, free of cracks, trip hazards or standing water; driveways need an apron and a finished surface. Checked at the Certificate of Inspection.","Also: Open permits: All open construction permits must have a passed final inspection on file before the inspection.","Also: Taxes, water and sewer: Municipal taxes, water and sewer should be paid up to date.","Also: Chimney certification: Wood burning fireplaces and stoves must be certified safe by a certified chimney sweep company.","Also: Zoning permit for non single family sales: A $100.00 zoning permit is also required for transfer of title of anything other than a single family home (so a two-family sale needs one)."]$j$::jsonb, $j$[{"label":"Certificate of Inspection, transfer of title for a single family dwelling","amount":"$200.00"},{"label":"Certificate of Inspection, transfer of title for a two-family, multi-family or apartment building","amount":"$15 per unit + $200.00 per building"},{"label":"Zoning permit for transfer of title (all uses except single family)","amount":"$100.00"},{"label":"Reinspection, per dwelling unit or building","amount":"$50.00"},{"label":"Late filing surcharge, 6 to 9 calendar days before occupancy (Borough code)","amount":"$50 additional"},{"label":"Late filing surcharge, 5 calendar days or less before occupancy (Borough code)","amount":"$100 additional"}]$j$::jsonb, $t$https://springlakehts.com/wp-content/uploads/2026/02/2026-Certificate-of-INSPECTION-Application-NEW-fillable.pdf$t$, $t$https://springlakehts.com/departments/construction-zoning-code-enforcement/$t$, $j$[{"url":"https://ecode360.com/36505324","label":"Official source (ecode360.com)"},{"url":"https://springlakehts.com/wp-content/uploads/2026/02/2026-Certificate-of-INSPECTION-Application-NEW-fillable.pdf","label":"Official source (springlakehts.com)"},{"url":"https://springlakehts.com/departments/construction-zoning-code-enforcement/","label":"Official source (springlakehts.com)"}]$j$::jsonb, $t$Prior to the rental, transfer of title or occupancy of any dwelling house or houses or any dwelling unit or units provided for in this subsection, application for a Certificate of Occupancy shall be made in writing to the Public Officer of the Borough$t$, $t$a3e263c98334b6402879faf05fe2eaaac3394d2ca2445efc1c54e9532a58c016$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1348.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1348.json$t$, true),
  ($t$1348$t$, $t$Spring Lake Heights Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Spring Lake Heights Bureau of Fire Prevention (with the Zoning Office, as part of the Certificate of Inspection) (town fire bureau)","Contact: Chris Willms, Fire Official · 732-449-9433 ex. 118 · firemarshal@springlakehts.com","How to apply: The smoke detector and carbon monoxide alarm certification is a page of the Borough's Certificate of Inspection application and is checked at that inspection; no separate smoke/CO fee is published. Questions go to the Fire Official, Chris Willms (firemarshal@springlakehts.com).","Fire official in the NJ state directory (town), updated 6/25/2026: Christopher Willms · (732) 449-3500 · firemarshal@springlakehts.com","Smoke alarms tested by push button; homes built before 1978 need at least battery alarms on each level and near bedrooms; 1978 to 1983 hardwired with battery backup; 1984 to 1990 also interconnected; 1991 and later also one in each bedroom","Battery-only smoke alarms must be 10-year sealed units; detectors over 10 years old are not accepted","Monitored systems need a letter from the owner, agent or monitoring company","Carbon monoxide alarms outside each separate sleeping area where there are fuel burning appliances or an attached garage; not older than 5 years or past the maker's expiration date","Fire extinguisher of the correct size, properly mounted within 10 feet of the kitchen (form still lists it)","Owner signs a certification that the smoke and CO alarms are installed and working","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://springlakehts.com/wp-content/uploads/2026/02/2026-Certificate-of-INSPECTION-Application-NEW-fillable.pdf$t$, $t$https://springlakehts.com/departments/bureau-of-fire-prevention/$t$, $j$[{"url":"https://springlakehts.com/departments/bureau-of-fire-prevention/","label":"Official source (springlakehts.com)"},{"url":"https://springlakehts.com/wp-content/uploads/2026/02/2026-Certificate-of-INSPECTION-Application-NEW-fillable.pdf","label":"Official source (springlakehts.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Chris Willms, Fire Official$t$, $t$c6f412fd7b4c49b0984a6df37e62bcb9767f994b68b2d34ebf7c6c3a5b4eb8d1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1348.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1348.json$t$, true),
  ($t$1349$t$, $t$Tinton Falls Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale/Rental Certificate of Occupancy (R/R-CO), also called Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Tinton Falls Code Enforcement (Code Enforcement Official)","Contact: Cary Costa, Code Enforcement Official · 732-542-3400 Ext. 267 · code-zoning@tintonfalls.com","Apply: Applications are processed within 15 business days; inspections are scheduled once the application is complete. The smoke/CO certificate and the CCO are picked up 36 to 72 hours after a passed inspection.","How to apply: Submit the R/R-CO application and the Smoke Detector application online through the Borough's SDL portal, along with the Supplemental Information form and any required certifications. Paper applications cost $15 more.","Valid for: 90 days. Applications without a CCO within 120 days of the first inspection are closed and need a new application and fee.","Property taxes must be current before applying","Resale inspection is limited to zoning compliance and the exterior of the property under the Property Maintenance Code","Separate smoke detector and carbon monoxide alarm application and inspection (Fire Prevention)","Supplemental Information form; application lists number of bedrooms, buyer name and names and ages of all occupants","Heat certification by a licensed HVAC technician or licensed plumber, issued no more than 6 months before the application","Wood burning stove or fireplace chimney certification by a CSIA certified chimney sweep, if applicable","Gas fireplace certification, if applicable","Well water certification by a state certified lab and septic certification (NJDEP format report) if applicable; well and septic reports go to the Freehold Township Health Department for review","Fire sprinkler report and elevator certification, if applicable","No open zoning or building permits or zoning violations; no transfer of title with unabated zoning violations","Also: Heat certification: Heating system certified by a licensed HVAC technician or licensed plumber, issued no more than six months before the CCO application.","Also: Chimney / fireplace certification: Wood burning stove or fireplace chimney certification by a CSIA certified chimney sweep, and gas fireplace certification by a licensed HVAC technician or plumber, if present.","Also: Well and septic certification: Homes on a well or septic system need a certified lab well water test and a septic cleaning and certification (NJDEP format report), submitted to the Freehold Township Health Department for review.","Also: Property taxes current: Property taxes must be current before the CCO application is submitted.","Also: Open permits and zoning violations: No CCO is issued with outstanding zoning or building permits or violations, and title may not transfer with unabated zoning violations."]$j$::jsonb, $j$[{"label":"Resale/Rental CO, detached single family dwelling","amount":"$150"},{"label":"Resale/Rental CO, attached multi-family dwelling (condos, townhomes, apartments), per unit","amount":"$75"},{"label":"R/R-CO reinspection, after the first free reinspection","amount":"$50.00"},{"label":"Surcharge for an R/R-CO application not submitted through the online portal","amount":"$15"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/tintonfalls/requests/certificate$t$, $t$https://www.tintonfalls.com/departments/code-enforcement$t$, $j$[{"url":"https://www.tintonfalls.com/construction-page-list/313-cco","label":"Official source (tintonfalls.com)"},{"url":"https://www.tintonfalls.com/government/documents/department-documents/code-enforcement-1/473-certificates-of-continued-occupancy-cco-required-residential-dwellings/file","label":"Official source (tintonfalls.com)"},{"url":"https://www.tintonfalls.com/departments/code-enforcement","label":"Official source (tintonfalls.com)"}]$j$::jsonb, $t$The Borough of Tinton Falls requires a ‘R/R-CO’ for all rentals, transfers of title, and changes in occupancy$t$, $t$8167f1c94f5dc8262423b46677ef1d9bbbf088ba88f262c7a39ac401d3ae2b06$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":14,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1349.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1349.json$t$, true),
  ($t$1349$t$, $t$Tinton Falls Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Tinton Falls Fire Prevention Bureau (Fire Marshal) (town fire bureau)","Contact: Cary Costa, Fire Marshal (Fire Inspector: David Boehning, Ext. 235) · 732-542-3400 Ext. 238 · firemarshal@tintonfalls.com","Apply: After the application and fee, the applicant receives an inspection date; inspections are weekday mornings. The certificate is picked up with the CCO 36 to 72 hours after a passed inspection and expires 90 days from the inspection date.","How to apply: Submit the residential Smoke Detector application on the Borough's SDL portal and pay by credit card, exact cash, or check payable to Borough of Tinton Falls. The Bureau sets an inspection date. After a failed inspection, fix the items and call the office to schedule a reinspection.","Fire official in the NJ state directory (town), updated 4/21/2022: Cary Costa · (732) 542-3400 · ccosta@tintonfalls.com","Smoke alarms and carbon monoxide alarms per the Borough's posted Residential Smoke Alarm and Carbon Monoxide Alarm Requirements documents","Portable fire extinguisher (form still lists it; the Borough page says extinguishers are still required by local ordinance regardless of state law)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and carbon monoxide certificate, per dwelling","amount":"$50"},{"label":"Smoke/CO reinspection, each","amount":"$35"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/monmouth/tintonfalls/requests/smokealarm$t$, $t$https://www.tintonfalls.com/departments/fire-prevention$t$, $j$[{"url":"https://www.tintonfalls.com/departments/fire-prevention","label":"Official source (tintonfalls.com)"},{"url":"https://www.tintonfalls.com/construction-page-list/313-cco","label":"Official source (tintonfalls.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke Detection Certificate expires 90 days from date of inspection.$t$, $t$96e922197ac3162454e3703d86eb51613df4cdd68e1129f99883343a4c423699$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":14,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1349.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1349.json$t$, true),
  ($t$1350$t$, $t$Union Beach Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (sale or rental)$t$, $j$["Issued by: Borough of Union Beach Office of Code Enforcement (Code Enforcement Officer)","Contact: Amado Bencosme, Code Enforcement Officer · 732-526-8686 · CodeEnforcement@unionbeachnj.gov","Apply: Inspections are held every half hour: Monday, Tuesday and Thursday 9:30am to 3pm, Wednesday 9:30am to 11am. Bring the application with a preferred day and time in mind.","How to apply: Download the Certificate of Occupancy application from the Code Enforcement forms page, mark it for a sale, and drop it off at Code Enforcement, Municipal Building, 650 Poole Avenue, Union Beach, NJ 07735, with a check or money order. Pick an inspection day and time when you drop it off. The fee covers the first inspection and one reinspection.","Code Enforcement inspection for compliance with the International Property Maintenance Code (2015 edition) as adopted by the Borough","Smoke detectors in working order sufficient to warn all occupants, plus one in the basement or cellar, before the CO is issued (Borough Code 10-3)","If the house has not been raised, a Zoning-Floodplain Development application must be completed before the CO can be issued","Application lists the prospective owner or tenant and everyone who will occupy the home","Fees paid by check or money order only","Also: Floodplain application for homes not raised: If the house has not been raised, a Zoning-Floodplain Development application must be completed before the Certificate of Occupancy can be issued."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy, single-family dwelling","amount":"$100.00"},{"label":"Certificate of Occupancy, commercial or multi-family dwelling (likely includes a 2 family home)","amount":"$125.00"},{"label":"Third inspection and each later reinspection, single family residence","amount":"$50"},{"label":"Third inspection and each later reinspection, commercial or multi-family","amount":"$100"}]$j$::jsonb, $t$https://www.unionbeachnj.gov/ubnj/Forms/Code%20Enforcement/Certificate%20of%20Occupancy%20Application$t$, $t$https://www.unionbeachnj.gov/ubnj/Departments/Code%20Enforcement/$t$, $j$[{"url":"https://www.unionbeachnj.gov/ubnj/Departments/Code%20Enforcement/","label":"Official source (unionbeachnj.gov)"},{"url":"https://www.unionbeachnj.gov/ubnj/Forms/Code%20Enforcement/Certificate%20of%20Occupancy%20Application","label":"Official source (unionbeachnj.gov)"},{"url":"https://ecode360.com/36143469","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36143482","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate of Occupancy is required for all rentals or sales of properties.$t$, $t$1145db0f5725aceeb5720ee6a5faffb2fed2736fa0497b9b2bbd12097925d9cd$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1350.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1350.json$t$, true),
  ($t$1350$t$, $t$Union Beach Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Union Beach Fire Department, Bureau of Fire Prevention (Fire Marshal) (town fire bureau)","Contact: Elizabeth Sweeney, Fire Marshal · 732-264-2277 · firemarshal@unionbeachnj.gov","How to apply: No online application or fee schedule was found. Contact the Fire Marshal (firemarshal@unionbeachnj.gov) or the Borough at 732-264-2277 to request the smoke and CO certificate inspection.","Fire official in the NJ state directory, updated 1/6/2025: Elizabeth Sweeney · (732) 264-2277 · firemarshal@unionbeachnj.gov","Smoke and carbon monoxide alarm certificate required before a 1 or 2 family home is sold (N.J.A.C. 5:70-2.3)","No Borough checklist for the certificate was found online; state rules apply (smoke alarm on each level and outside sleeping areas, 10-year sealed battery units where battery-only, CO alarm near sleeping areas when there is a fuel-burning appliance or attached garage)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.unionbeachnj.gov/ubnj/Community/Fire%20Department/$t$, $j$[{"url":"https://www.unionbeachnj.gov/ubnj/Community/Fire%20Department/","label":"Official source (unionbeachnj.gov)"},{"url":"https://ecode360.com/36143258","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Marshal Elizabeth Sweeney firemarshal@unionbeachnj.gov$t$, $t$22e1a5477e92d5a59b8535d8c74ccfbd0215e41fa5fa8e13c7169e9b0a2b300e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1350.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1350.json$t$, true),
  ($t$1351$t$, $t$Upper Freehold Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$CCO (Continued Certificate of Occupancy) for resale$t$, $j$["Issued by: Upper Freehold Township Housing Inspector (application to the Construction Office)","Contact: Ronald Gafgen, Housing Inspector · 609-758-7738 ext. 222 · Rgafgen@uftnj.com","How to apply: Submit the Township's Resale or Rental Application with the $100 fee (cash or check payable to Upper Freehold Township) to the Construction Office / Housing Department, 314 Route 539, Cream Ridge, NJ 08514. An appointment is then scheduled with the Housing Inspector. If the home has a septic system or well, call the Freehold Area Health Department for the septic inspection and send it the well water test results. Office hours are Monday to Thursday, 8:30 a.m. to 4:15 p.m.","Onsite inspection by the Housing Inspector for compliance with the Housing Code and applicable safety codes","Visual inspection of the septic system (if any), scheduled with the Freehold Area Health Department","Well water test by a State certified laboratory (if the home has a well), with results sent to the Freehold Area Health Department","Certificate of Compliance from the Freehold Area Health Department before the CCO is issued","Fee paid by cash or check only, payable to Upper Freehold Township","Also: Septic inspection and well water test (Freehold Area Health Department): For homes with a septic system, a visual septic inspection by the Freehold Area Health Department is required; homes on a well need a well water test by a State certified lab. The Health Department then issues a Certificate of Compliance, which the Housing Inspector needs before issuing the CCO."]$j$::jsonb, $j$[{"label":"CCO inspection for resale or rental","amount":"$100.00"},{"label":"Resale or rental Certificate of Occupancy inspection fee (Township Code 11-3.7)","amount":"$100"}]$j$::jsonb, $t$https://uftnj.com/wp-admin/admin-ajax.php?juwpfisadmin=false&action=wpfd&task=file.download&wpfd_category_id=98&wpfd_file_id=3226$t$, $t$https://uftnj.com/departments/housing-department/$t$, $j$[{"url":"https://uftnj.com/departments/housing-department/","label":"Official source (uftnj.com)"},{"url":"https://ecode360.com/36383567","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A CCO (Continued Certificate of Occupancy) is required any time occupancy changes for all Resale & Rental Properties.$t$, $t$8ed2a93ad7946065cfe5735eea2038d81d2ca8746128b9be7b5bbb036a028549$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":12,"q_ok":2,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/1351.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1351.json$t$, true),
  ($t$1351$t$, $t$Upper Freehold Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Upper Freehold Township (Bureau of Fire Prevention / Construction office)","Contact: Alex Nebbia, Fire Official · 609-259-7665 · fireofficial@uftnj.com","Apply: Fee depends on business days between the application and the occupant change: more than 10 business days for the lowest fee.","How to apply: No online application was found. Call the Township at 609-758-7738 or the Fire Official at 609-259-7665 to request the smoke and CO certificate inspection.","Fire official in the NJ state directory (town), updated 4/28/2025: Alex Nebbia · (609) 259-7665 · fireofficial@uftnj.com","Certificate of smoke detector and carbon monoxide detector compliance required under N.J.A.C. 5:70-2.3 before a 1 or 2 family home changes occupants","No Township checklist was found online; state rules apply (smoke alarm on each level and outside sleeping areas, 10-year sealed battery units where battery-only, CO alarm near sleeping areas when there is a fuel-burning appliance or attached garage)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and CO certificate, application received more than 10 business days before occupant change","amount":"$45"},{"label":"Application received 4 to 10 business days before occupant change","amount":"$90"},{"label":"Application received less than 4 business days before occupant change","amount":"$161"}]$j$::jsonb, null, $t$https://uftnj.com/departments/fire-official/$t$, $j$[{"url":"https://ecode360.com/36389249","label":"Official source (ecode360.com)"},{"url":"https://uftnj.com/departments/fire-official/","label":"Official source (uftnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The application fee for a certificate of smoke detector and carbon monoxide detector compliance as required by N.J.A.C. 5:70-2.3 shall be:$t$, $t$051d3bf1ce4c7d81b32c1904d7485c29edb4c65719941edd862808817943d143$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":12,"q_ok":2,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/1351.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1351.json$t$, true),
  ($t$1352$t$, $t$Wall Township$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Wall Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Robert Torrance, Construction Official · 732-449-8444 ext. 2225 · rtorrance@wallnj.gov","How to apply: No Township resale Certificate of Continued Occupancy. The Township's building FAQ says only the smoke detector, carbon monoxide (and fire extinguisher) certification from the Fire Bureau is needed for the resale of a home (see fire certificate).","Also: Final water/sewer meter reading: The Township's forms page offers a Final Meter Reading Request for sales and tenant changes (online form).","Also: Uninhabitable home transfer of title: If the house is uninhabitable, the Fire Bureau has a Transfer of Title for a Residential Property form ($75/$125); the home cannot be occupied until the Building Department issues a Certificate of Occupancy."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.wallnj.gov/284/Building-Department$t$, $j$[{"url":"https://www.wallnj.gov/DocumentCenter/View/538","label":"Official source (wallnj.gov)"},{"url":"https://www.wallnj.gov/284/Building-Department","label":"Official source (wallnj.gov)"}]$j$::jsonb, $t$Does Wall Township require an inspection by the building department on resale of a home?$t$, $t$c3380307bb3d844abca9ee149ebadaf78875d337061f3d2d58587e024b6e5864$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":2,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":13,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1352.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1352.json$t$, true),
  ($t$1352$t$, $t$Wall Township$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Wall Township Fire Bureau (Fire Prevention Bureau, governed by the Joint Board of Fire Commissioners of Fire Districts 1, 2 and 3) (fire district)","Contact: William Newberry, Fire Marshal · 732-820-4854 · inspection@wallfirebureau.com","Apply: Fee depends on business days before closing: more than 5 business days for the lower fee. Staff call within one business day after an online application to schedule.","How to apply: Apply online with the Fire Bureau's Smoke Detector Inspection Application (or email a printed application to inspection@wallfirebureau.com). Have the block, lot, address, owner, buyer, closing date and an inspection contact ready. Checks are payable to Wall Township Fire Bureau. Office: 1612 Route 71, Wall Township, NJ 07719, Monday to Friday 8am to 4pm.","Fire official in the NJ state directory (fire district), updated 7/29/2026: William G Newberry · (732) 820-4854 · wnewberry@wtfd1.com","Smoke Detector and Carbon Monoxide Alarm Certificate of Compliance before any residential unit is sold or changes occupancy","Battery-only smoke alarms must be 10-year sealed units; hardwired alarms cannot be replaced with battery alarms","Smoke alarm type depends on the year built (for example, homes from March 1991 on need interconnected hardwired alarms on all levels and in each bedroom with battery back-up)","Smoke alarm near every bedroom door; basement and non-sleeping levels near the stairway to the floor above","Carbon monoxide alarm on each sleeping level near every bedroom door in homes with a fuel-burning appliance or attached garage","Central station monitored alarm systems must be certified by a licensed NJ Fire Protection Contractor before the inspection","Secondary power source (for example solar or battery storage) labeling checked under P.L.2025, c.19 when applicable","Portable fire extinguisher (the Township FAQ and the uninhabitable transfer form still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, initial inspection more than 5 business days before closing","amount":"$75"},{"label":"Initial inspection 5 or fewer days before closing","amount":"$125"},{"label":"First reinspection (more than 5 days / 5 or fewer days before closing)","amount":"$30 / $40"},{"label":"Second and later reinspections","amount":"$40"},{"label":"Missed appointment or no entry","amount":"$30"},{"label":"Secondary power source label inspection, when needed","amount":"$20"}]$j$::jsonb, $t$https://wallfirebureau.com/smoke-detector-inspection-application-2/$t$, $t$https://wallfirebureau.com/smoke-detector-inspection/$t$, $j$[{"url":"https://wallfirebureau.com/smoke-detector-inspection/","label":"Official source (wallfirebureau.com)"},{"url":"https://wallfirebureau.com/smoke-detector-inspection-application-2/","label":"Official source (wallfirebureau.com)"},{"url":"http://wallfirebureau.com/","label":"Official source (wallfirebureau.com)"},{"url":"https://ecode360.com/9593155","label":"Official source (ecode360.com)"},{"url":"https://www.wallnj.gov/DocumentCenter/View/538","label":"Official source (wallnj.gov)"},{"url":"https://www.wallnj.gov/461/Fire-Districts","label":"Official source (wallnj.gov)"},{"url":"http://wallfirebureau.com/wp-content/uploads/Uninhabitable-Transfer-of-Title-for-Residence.pdf","label":"Official source (wallfirebureau.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Pursuant to the New Jersey Uniform Fire Code, before any residential structure/unit is sold, leased, or otherwise made subject to change of occupancy the owner shall obtain a Smoke Detector & Carbon Monoxide Alarm Certificate of Compliance.$t$, $t$528ae19633d8f63017dc00ff69b973a92a41c8fd8a241336b0f4dbf16d09647e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":2,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":13,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1352.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1352.json$t$, true),
  ($t$1353$t$, $t$West Long Branch Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for sale (residential housing inspection)$t$, $j$["Issued by: Borough of West Long Branch Housing Department (Housing Inspector)","Contact: Christopher Neyhart, Housing Inspector · 732-229-1756 ext. 119 · housing@westlongbranch.org","Apply: After payment is processed, the Housing Department contacts the applicant within 7 business days to schedule the inspection. No inspection is scheduled until all building permits are closed.","How to apply: Apply online with the Borough's Certificate of Occupancy application (WebGeo portal). Print the application when prompted, then pay online or mail it with a check or money order to Borough of West Long Branch, 965 Broadway, West Long Branch, NJ 07764, Attn: Housing. If paying by check, the smoke/CO certificate fee must be a separate check. Submit the Level II chimney certification and close all permits first; the Housing Department then calls to schedule the inspection.","Valid for: Valid while the occupant it was issued to stays in possession. Occupant names may only be changed within ten days of the inspection; after that a new application is needed.","Online application with the required forms and payment","Home inspection by the Housing Inspector using the Borough's Housing Inspection Checklist (working doors, windows and locks, handrails on stairs with four or more risers, hot water at all fixtures, relief valve discharge pipe, house numbers at least 3 inches, clean and free of debris, sidewalks and driveways in good repair, and more)","All building permits closed out with the Building Department","Level II chimney certification for a sale for any wood-burning fireplace, or an invoice showing the fireplace was properly sealed","Smoke and carbon monoxide alarm certificate (fee added to the online CO application); 10-year sealed smoke alarms in all bedrooms and sleeping areas","If the home has an alarm system, it must be registered with the Police Department (alarm monitoring certificate if monitored)","No temporary or \"as is\" sale certificates are issued","Also: Open permits: All building permits must be closed out with the Building Department (344 Broadway, Long Branch, 732-571-5690) before the housing inspection is scheduled.","Also: Chimney Level II certification: A sale requires a Level II chimney certification for wood-burning fireplaces (direct-vent and ventless units are exempt), or an invoice from a certified chimney company showing the fireplace is sealed top and bottom.","Also: Alarm system registration: If the home has an alarm, it must be registered with the Police Department; a monitored alarm needs an Alarm Monitoring Certificate."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy for a sale (Borough web page)","amount":"$100.00"},{"label":"Certificate of Occupancy, single-family dwelling (Borough Code 9-2.10, amended 9-17-2025)","amount":"$200"},{"label":"Apartments or multi-family dwellings, per unit (Borough Code 9-2.10)","amount":"$200"},{"label":"Second and later reinspections","amount":"$100"}]$j$::jsonb, $t$https://webgeo.co/prod1/portal/portal.jsp?c=3777464&p=131401733&g=131401735$t$, $t$https://www.westlongbranch.org/1219/Housing-Residential-Certificate-of-Occup$t$, $j$[{"url":"https://www.westlongbranch.org/1306/Certificate-of-Occupancy-residential-pro","label":"Official source (westlongbranch.org)"},{"url":"https://www.westlongbranch.org/1219/Housing-Residential-Certificate-of-Occup","label":"Official source (westlongbranch.org)"},{"url":"https://www.westlongbranch.org/1300/Required-forms-prior-to-application-subm","label":"Official source (westlongbranch.org)"},{"url":"https://www.westlongbranch.org/DocumentCenter/View/347/wlb_housing_prep_for_inspec","label":"Official source (westlongbranch.org)"},{"url":"https://ecode360.com/36233496","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36233505","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate of Occupancy is required for a change of occupancy in a residential property, whether it be a change in tenancy or owner re-occupancy.$t$, $t$ddcbe205f6f84afb81adde05ed20ada95f8d58c2ec6355a11a7e16bae22a67dc$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":4,"fee_bad":0,"fee_unchecked":6,"quotes":18,"q_ok":13,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1353.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1353.json$t$, true),
  ($t$1353$t$, $t$West Long Branch Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of West Long Branch Housing Department / Fire Prevention Bureau (smoke and CO certificate is added to the online CO application)","Contact: James Miller, Fire Official (also Deputy Housing Inspector) · 732-229-1756 ext. 119 · housing@westlongbranch.org","Apply: Fee depends on business days before the change of occupancy: more than 10 business days for the lowest fee.","How to apply: The smoke and CO certificate fee is added automatically when you complete the online Certificate of Occupancy application. If paying by check or money order, pay it separately from the CO fee.","Fire official in the NJ state directory (town), updated 3/11/2024: James Miller · (732) 229-1756 · jmiller@westlongbranch.org","Smoke and carbon monoxide alarm certificate when a 1 or 2 family home is sold (Borough Code 9-2.5f); the obligation is on the owner or seller","10-year sealed smoke detectors in all bedrooms or potential sleeping areas and guest rooms","Newly installed smoke alarms must be photoelectric type (NFPA 72, January 1, 2022)","Carbon monoxide alarms as required by N.J.A.C. 5:70-4.19(d) and 5:70-2.3","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and CO certificate, request more than 10 business days before change of occupancy (Borough web page)","amount":"$45.00"},{"label":"Request 4 to 10 business days before change of occupancy (Borough web page)","amount":"$90.00"},{"label":"Request fewer than 4 business days before change of occupancy (Borough web page)","amount":"$161.00"},{"label":"Smoke and CO inspection, request more than 10 business days before change of occupancy (Borough Code 9-2.15, amended 9-17-2025)","amount":"$100"},{"label":"Request 4 to 10 business days before change of occupancy (Borough Code)","amount":"$150"},{"label":"Request fewer than 4 business days before change of occupancy (Borough Code)","amount":"$250"}]$j$::jsonb, $t$https://webgeo.co/prod1/portal/portal.jsp?c=3777464&p=131401733&g=131401735$t$, $t$https://www.westlongbranch.org/1306/Certificate-of-Occupancy-residential-pro$t$, $j$[{"url":"https://www.westlongbranch.org/1306/Certificate-of-Occupancy-residential-pro","label":"Official source (westlongbranch.org)"},{"url":"https://www.westlongbranch.org/1219/Housing-Residential-Certificate-of-Occup","label":"Official source (westlongbranch.org)"},{"url":"https://ecode360.com/36233481","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36233515","label":"Official source (ecode360.com)"},{"url":"https://www.westlongbranch.org/1221/Fire-Prevention-Bureau-Fire-Permit-Appli","label":"Official source (westlongbranch.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Smoke and Carbon Monoxide Detector Certificate fee will be added to your initial application automatically when you complete the application online.$t$, $t$9c6ab1c6d0ed82d22f6d5862d4ab07e69be4aa6d964e79302b1cea577008daea$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":4,"fee_bad":0,"fee_unchecked":6,"quotes":18,"q_ok":13,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1353.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1353.json$t$, true)
